// .storybook/preview.js
// Preview do Storybook - NOVAIX FITNESS

import { withBackgrounds } from '@storybook/addon-onbackgrounds';
import { COLORS } from '../src/constants/colors';

export const decorators = [
  withBackgrounds([
    { name: 'dark', value: COLORS.background, default: true },
    { name: 'light', value: '#FFFFFF' },
    { name: 'surface', value: COLORS.surface },
  ]),
];

export const parameters = {
  controls: {
    matchers: {
      color: /(background|color)$/i,
      date: /Date$/,
    },
  },
  backgrounds: {
    default: 'dark',
    values: [
      { name: 'dark', value: COLORS.background },
      { name: 'light', value: '#FFFFFF' },
      { name: 'surface', value: COLORS.surface },
    ],
  },
};

import React from 'react';
import TestRenderer from 'react-test-renderer';

export function renderHook(hookFn) {
  let result = { current: null };
  let error = null;

  const TestComponent = () => {
    try {
      result.current = hookFn();
    } catch (e) {
      error = e;
    }
    return null;
  };

  let renderer;
  const act = (callback) => {
    return new Promise(async (resolve) => {
      await TestRenderer.act(async () => {
        await callback();
      });
      resolve();
    });
  };

  TestRenderer.act(() => {
    renderer = TestRenderer.create(React.createElement(TestComponent));
  });

  return {
    result,
    rerender: () => {
      TestRenderer.act(() => {
        renderer.update(React.createElement(TestComponent));
      });
    },
    unmount: () => {
      renderer.unmount();
    },
  };
}

export const act = TestRenderer.act;

