jest.mock('react-native', () => {
  const rn = jest.requireActual('react-native');
  rn.Dimensions.get = () => ({ width: 375, height: 812 });
  return rn;
});

import { SPACING, BORDER_RADIUS } from '../../src/constants/spacing';

describe('Spacing Constants', () => {
  describe('SPACING', () => {
    it('has xs spacing', () => {
      expect(SPACING.xs).toBe(4);
    });

    it('has sm spacing', () => {
      expect(SPACING.sm).toBe(8);
    });

    it('has md spacing', () => {
      expect(SPACING.md).toBe(12);
    });

    it('has lg spacing', () => {
      expect(SPACING.lg).toBe(16);
    });

    it('has xl spacing', () => {
      expect(SPACING.xl).toBe(20);
    });

    it('has xxl spacing', () => {
      expect(SPACING.xxl).toBe(24);
    });

    it('has xxxl spacing', () => {
      expect(SPACING.xxxl).toBe(32);
    });

    it('has huge spacing', () => {
      expect(SPACING.huge).toBe(40);
    });

    it('has massive spacing', () => {
      expect(SPACING.massive).toBe(48);
    });

    it('spacing values increase progressively', () => {
      expect(SPACING.xs).toBeLessThan(SPACING.sm);
      expect(SPACING.sm).toBeLessThan(SPACING.md);
      expect(SPACING.md).toBeLessThan(SPACING.lg);
      expect(SPACING.lg).toBeLessThan(SPACING.xl);
      expect(SPACING.xl).toBeLessThan(SPACING.xxl);
      expect(SPACING.xxl).toBeLessThan(SPACING.xxxl);
      expect(SPACING.xxxl).toBeLessThan(SPACING.huge);
      expect(SPACING.huge).toBeLessThan(SPACING.massive);
    });

    it('all values are numbers', () => {
      Object.values(SPACING).forEach(value => {
        expect(typeof value).toBe('number');
      });
    });

    it('all values are positive', () => {
      Object.values(SPACING).forEach(value => {
        expect(value).toBeGreaterThan(0);
      });
    });
  });

  describe('BORDER_RADIUS', () => {
    it('has sm border radius', () => {
      expect(BORDER_RADIUS.sm).toBe(8);
    });

    it('has md border radius', () => {
      expect(BORDER_RADIUS.md).toBe(12);
    });

    it('has lg border radius', () => {
      expect(BORDER_RADIUS.lg).toBe(16);
    });

    it('has xl border radius', () => {
      expect(BORDER_RADIUS.xl).toBe(20);
    });

    it('has full border radius', () => {
      expect(BORDER_RADIUS.full).toBe(9999);
    });

    it('border radius values increase progressively', () => {
      expect(BORDER_RADIUS.sm).toBeLessThan(BORDER_RADIUS.md);
      expect(BORDER_RADIUS.md).toBeLessThan(BORDER_RADIUS.lg);
      expect(BORDER_RADIUS.lg).toBeLessThan(BORDER_RADIUS.xl);
      expect(BORDER_RADIUS.xl).toBeLessThan(BORDER_RADIUS.full);
    });

    it('all values are numbers', () => {
      Object.values(BORDER_RADIUS).forEach(value => {
        expect(typeof value).toBe('number');
      });
    });

    it('all values are positive', () => {
      Object.values(BORDER_RADIUS).forEach(value => {
        expect(value).toBeGreaterThan(0);
      });
    });
  });
});

import { DETAILED_EXERCISES } from '../../src/data/exercises';

describe('Exercises Data', () => {
  it('has exercises', () => {
    expect(Object.keys(DETAILED_EXERCISES).length).toBeGreaterThan(0);
  });

  it('each exercise has steps, tips, and mistakes', () => {
    Object.entries(DETAILED_EXERCISES).forEach(([key, exercise]) => {
      expect(exercise).toHaveProperty('steps');
      expect(exercise).toHaveProperty('tips');
      expect(exercise).toHaveProperty('mistakes');
      expect(Array.isArray(exercise.steps)).toBe(true);
      expect(exercise.steps.length).toBeGreaterThan(0);
      expect(Array.isArray(exercise.tips)).toBe(true);
      expect(Array.isArray(exercise.mistakes)).toBe(true);
    });
  });

  it('each step has step number, title, text, and image', () => {
    Object.values(DETAILED_EXERCISES).forEach(exercise => {
      exercise.steps.forEach(step => {
        expect(step).toHaveProperty('step');
        expect(step).toHaveProperty('title');
        expect(step).toHaveProperty('text');
        expect(step).toHaveProperty('image');
      });
    });
  });

  it('includes common exercises', () => {
    expect(DETAILED_EXERCISES).toHaveProperty('push_up');
    expect(DETAILED_EXERCISES).toHaveProperty('squat');
  });
});

import {
  formatDateBR,
  formatDateShort,
  formatRelativeDate,
  formatTimeBR,
  formatTimeAgo,
  formatTimestampAgo,
  formatSeconds,
  formatMinutes,
  formatDuration,
  isToday,
  isSameDay,
  getDaysBetween,
} from '../../src/helpers/dates';

describe('formatDateBR', () => {
  it('returns empty string for null/undefined', () => {
    expect(formatDateBR(null)).toBe('');
    expect(formatDateBR(undefined)).toBe('');
  });

  it('formats date in pt-BR', () => {
    const result = formatDateBR('2025-01-15T12:00:00');
    expect(result).toContain('2025');
  });
});

describe('formatRelativeDate', () => {
  it('returns "Sem data" for null', () => {
    expect(formatRelativeDate(null)).toBe('Sem data');
  });

  it('returns "Hoje" for today', () => {
    expect(formatRelativeDate(new Date().toISOString())).toBe('Hoje');
  });

  it('returns "Ontem" for yesterday', () => {
    const yesterday = new Date(Date.now() - 86400000).toISOString();
    expect(formatRelativeDate(yesterday)).toBe('Ontem');
  });
});

describe('formatSeconds', () => {
  it('formats 0 as 0:00', () => {
    expect(formatSeconds(0)).toBe('0:00');
  });

  it('formats 65 as 1:05', () => {
    expect(formatSeconds(65)).toBe('1:05');
  });

  it('formats 3661 as 61:01', () => {
    expect(formatSeconds(3661)).toBe('61:01');
  });
});

describe('formatMinutes', () => {
  it('formats minutes only', () => {
    expect(formatMinutes(30)).toBe('30min');
  });

  it('formats hours only', () => {
    expect(formatMinutes(60)).toBe('1h');
  });

  it('formats hours and minutes', () => {
    expect(formatMinutes(90)).toBe('1h30min');
  });
});

describe('formatDuration', () => {
  it('formats seconds only', () => {
    expect(formatDuration(45)).toBe('0:45');
  });

  it('formats minutes and seconds', () => {
    expect(formatDuration(125)).toBe('2:05');
  });

  it('formats hours, minutes, seconds', () => {
    expect(formatDuration(3665)).toBe('1:01:05');
  });
});

describe('isToday', () => {
  it('returns true for today', () => {
    expect(isToday(new Date().toISOString())).toBe(true);
  });

  it('returns false for null', () => {
    expect(isToday(null)).toBe(false);
  });
});

describe('isSameDay', () => {
  it('returns true for same day', () => {
    const date = '2025-01-15T10:00:00';
    expect(isSameDay(date, '2025-01-15T15:00:00')).toBe(true);
  });

  it('returns false for different days', () => {
    expect(isSameDay('2025-01-15', '2025-01-16')).toBe(false);
  });

  it('returns false for null', () => {
    expect(isSameDay(null, '2025-01-15')).toBe(false);
  });
});

describe('getDaysBetween', () => {
  it('calculates days between dates', () => {
    expect(getDaysBetween('2025-01-10', '2025-01-15')).toBe(5);
  });

