      expect(result).toEqual(['Frente', 'Lado', 'Costas']);
    });
  });

  describe('PHOTO_LABELS', () => {
    it('has all labels', () => {
      expect(PHOTO_LABELS).toContain('Frente');
      expect(PHOTO_LABELS).toContain('Costas');
    });
  });
});

