// app/(tabs)/perfil/user-profile.js
// Página de perfil público de outro usuário

import { useState, useEffect } from 'react';
import { View, Text, ScrollView, TouchableOpacity, StyleSheet, RefreshControl } from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import { useRouter, useLocalSearchParams } from 'expo-router';
import { COLORS } from '../../../src/constants/colors';
import { SPACING, BORDER_RADIUS } from '../../../src/constants/spacing';
import { Avatar } from '../../../src/components';
import { useAuth } from '../../../src/context/AuthContext';
import { supabase } from '../../../src/config/supabase';
import { Header, ErrorBoundary, PostCard } from '../../../src/components';
import { followUser, unfollowUser, isFollowing } from '../../../src/services/social';
import { formatRelativeDate } from '../../../src/helpers/dates';

export default function UserProfileScreen() {
  const router = useRouter();
  const { id } = useLocalSearchParams() as { id: string };
  const { user } = useAuth();
  const [profile, setProfile] = useState(null);
  const [posts, setPosts] = useState([]);
  const [following, setFollowing] = useState(false);
  const [refreshing, setRefreshing] = useState(false);
  const [loading, setLoading] = useState(true);

  useEffect(() => { if (id) loadProfile(); }, [id]);

  const loadProfile = async () => {
    setLoading(true);
    const { data } = await supabase.from('profiles').select('*').eq('id', id).single();
    setProfile(data);

    const { data: postData } = await supabase
      .from('posts')
      .select('*, profiles:user_id(name, avatar_url)')
      .eq('user_id', id)
      .order('created_at', { ascending: false })
      .limit(20);

    setPosts((postData || []).map(p => ({
      id: p.id, userId: p.user_id,
      user: { name: p.profiles?.name || 'Atleta', avatar: p.profiles?.avatar_url || null },
      content: p.content, image: p.image_url,
      createdAt: formatRelativeDate(p.created_at),
      likes: p.likes_count || 0, comments: p.comments_count || 0, isLiked: false,
    })));

    if (user?.id && id !== user.id) {
      const f = await isFollowing(user.id, id);
      setFollowing(f);
    }
    setLoading(false);
  };

  const handleFollow = async () => {
    if (following) {
      await unfollowUser(user.id, id);
      setFollowing(false);
      setProfile(prev => ({ ...prev, followers_count: Math.max(0, (prev?.followers_count || 1) - 1) }));
    } else {
      await followUser(user.id, id);
      setFollowing(true);
      setProfile(prev => ({ ...prev, followers_count: (prev?.followers_count || 0) + 1 }));
    }
  };

  const onRefresh = async () => {
    setRefreshing(true);
    await loadProfile();
    setRefreshing(false);
  };

  if (loading || !profile) {
    return (
      <View style={styles.center}>
        <Header title="PERFIL" showBack onBack={() => router.back()} />
        <Text style={styles.loadingText}>Carregando...</Text>
      </View>
    );
  }

  const isOwnProfile = user?.id === id;

  return (
    <ErrorBoundary screenName="UserProfile">
      <View style={styles.screen}>
        <Header title={profile.name || 'Perfil'} showBack onBack={() => router.back()} />

        <ScrollView
          contentContainerStyle={styles.content}
          refreshControl={<RefreshControl refreshing={refreshing} onRefresh={onRefresh} tintColor={COLORS.primary} />}
        >
          <View style={styles.profileCard}>
            <Avatar name={profile.name} size="xl" />
            <Text style={styles.name}>{profile.name}</Text>
            {profile.bio && <Text style={styles.bio}>{profile.bio}</Text>}

            <View style={styles.statsRow}>
              <View style={styles.stat}>
                <Text style={styles.statValue}>{profile.total_workouts || 0}</Text>
                <Text style={styles.statLabel}>Treinos</Text>
              </View>
              <View style={styles.stat}>
                <Text style={styles.statValue}>{profile.level || 1}</Text>
                <Text style={styles.statLabel}>Nível</Text>
              </View>
              <View style={styles.stat}>
                <Text style={styles.statValue}>{profile.followers_count || 0}</Text>
                <Text style={styles.statLabel}>Seguidores</Text>
              </View>
              <View style={styles.stat}>
                <Text style={styles.statValue}>{profile.streak || 0}</Text>
                <Text style={styles.statLabel}>Streak</Text>
              </View>
            </View>

            {!isOwnProfile && (
              <TouchableOpacity style={[styles.followBtn, following && styles.followingBtn]} accessibilityLabel={following ? 'Deixar de seguir' : 'Seguir'} accessibilityRole="button" onPress={handleFollow}>
                <Ionicons name={following ? 'checkmark' : 'person-add'} size={16} color={following ? COLORS.primary : COLORS.background} />
                <Text style={[styles.followText, following && styles.followingText]}>
                  {following ? 'Seguindo' : 'Seguir'}
                </Text>
              </TouchableOpacity>
            )}
          </View>

          <Text style={styles.sectionTitle}>POSTS</Text>
          {posts.length === 0 ? (
            <View style={styles.empty}>
              <Ionicons name="chatbubble-outline" size={40} color={COLORS.textMuted} />
              <Text style={styles.emptyText}>Nenhum post ainda</Text>
            </View>
          ) : (
            posts.map(p => (
              <PostCard key={p.id} post={p} currentUserId={user?.id} />
            ))
          )}
        </ScrollView>
      </View>
    </ErrorBoundary>
  );
}

const styles = StyleSheet.create({
  screen: { flex: 1, backgroundColor: COLORS.background },
  center: { flex: 1, backgroundColor: COLORS.background },
  content: { padding: SPACING.lg, paddingBottom: SPACING.massive },
  loadingText: { fontFamily: 'Inter_400Regular', fontSize: 14, color: COLORS.textMuted, textAlign: 'center', marginTop: SPACING.xxl },
  profileCard: { alignItems: 'center', marginBottom: SPACING.xl, paddingVertical: SPACING.xl, backgroundColor: COLORS.surface, borderRadius: BORDER_RADIUS.lg, borderWidth: 1, borderColor: COLORS.border },
  name: { fontFamily: 'Montserrat_700Bold', fontSize: 18, color: COLORS.textTitle, marginTop: SPACING.md, marginBottom: SPACING.xs },
  bio: { fontFamily: 'Inter_400Regular', fontSize: 13, color: COLORS.textDescription, textAlign: 'center', marginBottom: SPACING.lg, paddingHorizontal: SPACING.lg },
  statsRow: { flexDirection: 'row', gap: SPACING.xl, marginBottom: SPACING.xl },
  stat: { alignItems: 'center' },
  statValue: { fontFamily: 'Montserrat_700Bold', fontSize: 16, color: COLORS.textTitle },
  statLabel: { fontFamily: 'Inter_400Regular', fontSize: 11, color: COLORS.textMuted },
  followBtn: { flexDirection: 'row', alignItems: 'center', gap: SPACING.xs, backgroundColor: COLORS.primary, paddingHorizontal: SPACING.xxl, paddingVertical: SPACING.md, borderRadius: BORDER_RADIUS.full },
  followText: { fontFamily: 'Montserrat_600SemiBold', fontSize: 13, color: COLORS.background },
  followingBtn: { backgroundColor: 'transparent', borderWidth: 1, borderColor: COLORS.primary },
  followingText: { color: COLORS.primary },
  sectionTitle: { fontFamily: 'Montserrat_700Bold', fontSize: 12, color: COLORS.textMuted, marginBottom: SPACING.md, letterSpacing: 1 },
  empty: { alignItems: 'center', paddingVertical: SPACING.xxxl },
  emptyText: { fontFamily: 'Inter_400Regular', fontSize: 14, color: COLORS.textMuted, marginTop: SPACING.md },
});

import React, { useEffect, Suspense, useState, lazy } from 'react';
import { Stack, useRouter, useSegments } from 'expo-router';
import { useFonts } from 'expo-font';
import { Montserrat_400Regular, Montserrat_600SemiBold, Montserrat_700Bold, Montserrat_800ExtraBold } from '@expo-google-fonts/montserrat';
import { Inter_400Regular, Inter_500Medium, Inter_600SemiBold, Inter_700Bold } from '@expo-google-fonts/inter';
import { ActivityIndicator, View } from 'react-native';
import { ThemeProvider as NavigationThemeProvider, DarkTheme, DefaultTheme } from '@react-navigation/native';
import AsyncStorage from '@react-native-async-storage/async-storage';
import { AuthProvider, useAuth } from '../src/context/AuthContext';
import { ThemeProvider, useTheme } from '../src/context/ThemeContext';
import { COLORS } from '../src/constants/colors';
import { BRAND_SHORT } from '../src/constants/brand';
import { registerForPushNotificationsAsync, addNotificationReceivedListener, addNotificationResponseListener } from '../src/services/pushNotifications';
import { setupCrashHandler } from '../src/services/crashReport';
import { startAutoSync, stopAutoSync } from '../src/services/autoSync';
import { injectWebStyles, ErrorBoundary, OfflineIndicator } from '../src/components';
import { APP_SCREENS, PUBLIC_ROUTES } from '../src/config/appScreens';
import { initSentry, captureError } from '../src/config/sentry';

import { I18nProvider } from '../src/i18n';

// Lazy-loaded heavy screens for bundle optimization
const LazyDashboard = lazy(() => import('./dashboard'));
const LazyAdmin = lazy(() => import('./admin'));
const LazyAnalytics = lazy(() => import('./analytics'));
const LazyMarketplace = lazy(() => import('./marketplace'));
const LazyForum = lazy(() => import('./forum'));
const LazyNutrition = lazy(() => import('./nutrition'));
const LazyGamification = lazy(() => import('./gamification'));
const LazyBlog = lazy(() => import('./blog'));
const LazyPlayer = lazy(() => import('./player'));
const LazyWorkoutDetail = lazy(() => import('./workout-detail'));
const LazyLive = lazy(() => import('./live'));
const LazySocial = lazy(() => import('./social'));

// Map of heavy screens to their lazy-loaded versions
const LAZY_SCREEN_MAP: Record<string, React.LazyExoticComponent<React.ComponentType<any>>> = {
  dashboard: LazyDashboard,
  admin: LazyAdmin,
  analytics: LazyAnalytics,
  marketplace: LazyMarketplace,
  forum: LazyForum,
  nutrition: LazyNutrition,
  gamification: LazyGamification,
  blog: LazyBlog,
  player: LazyPlayer,
  'workout-detail': LazyWorkoutDetail,
  live: LazyLive,
  social: LazySocial,
};

// Wrapper for lazy-loaded screens with Suspense fallback
function LazyScreenWrapper({ name }: { name: string }) {
  const LazyComponent = LAZY_SCREEN_MAP[name];
  if (!LazyComponent) return null;
  return (
    <Suspense fallback={<LoadingScreen />}>
      <LazyComponent />
    </Suspense>
  );
}

const INTRO_STORAGE_KEY = '@novaix:intro_seen';

initSentry();

function AuthRedirect() {
  const { user, profile, loading } = useAuth();
  const router = useRouter();
  const segments = useSegments();
  const [introSeen, setIntroSeen] = useState<boolean | null>(null);

  useEffect(() => {
    AsyncStorage.getItem(INTRO_STORAGE_KEY).then((val) => setIntroSeen(val === 'true'));
  }, []);

  useEffect(() => {
    if (loading || introSeen === null) return;
    const inTabsGroup = segments[0] === '(tabs)';
    const inOnboarding = segments[0] === 'onboarding';
    const inPaywall = segments[0] === 'paywall';
    const currentRoute = segments[0] || 'index';
    const isPublicRoute = PUBLIC_ROUTES.includes(currentRoute);

    if (user) {
      if (!profile) return;
      const step = profile.current_step || 'onboarding';
      if (step === 'onboarding') { if (!inOnboarding) router.replace('/onboarding/objetivo'); return; }
      if (step === 'pagamento') { if (!inPaywall) router.replace('/paywall'); return; }
      if (isPublicRoute || inOnboarding || inPaywall) router.replace('/(tabs)/home');
      return;
    }
    if (!introSeen && currentRoute !== 'intro') { router.replace('/intro'); return; }
    if (inTabsGroup || inOnboarding || inPaywall) router.replace('/');
  }, [user, profile, loading, segments, introSeen]);

  useEffect(() => {
    if (!user?.id) return;
    registerForPushNotificationsAsync(user.id);
    const receivedSub = addNotificationReceivedListener(({ title, body }: { title?: string; body?: string }) => {
      if (title || body) {
        import('react-native').then(({ Alert, Platform }) => {
          if (Platform.OS === 'web') alert(`${title}: ${body}`);
          else Alert.alert(title || BRAND_SHORT, body || '');
        });
      }
    });
    const responseSub = addNotificationResponseListener(router);
    return () => { receivedSub?.remove(); responseSub?.remove(); };
  }, [user?.id, router]);

  return null;
}

function LoadingScreen() {
  return (
    <View style={{ flex: 1, backgroundColor: COLORS.background, justifyContent: 'center', alignItems: 'center' }}>
      <ActivityIndicator size="large" color={COLORS.primary} />
    </View>
  );
}

function AppContent() {
  const { isDark } = useTheme();
  const navTheme = isDark ? DarkTheme : DefaultTheme;

  useEffect(() => { startAutoSync(() => {}); return () => stopAutoSync(); }, []);

  return (
    <ErrorBoundary screenName="AppRoot">
      <NavigationThemeProvider value={navTheme}>
        <OfflineIndicator />
        <Suspense fallback={<LoadingScreen />}>
          <Stack screenOptions={{ headerShown: false }}>
            {APP_SCREENS.map(name => {
              const isLazy = name in LAZY_SCREEN_MAP;
              return isLazy ? (
                <Stack.Screen
                  key={name}
                  name={name}
                  component={() => <LazyScreenWrapper name={name} />}
                />
              ) : (
                <Stack.Screen key={name} name={name} />
              );
            })}
            <Stack.Screen name="(tabs)" />
          </Stack>
        </Suspense>
      </NavigationThemeProvider>
    </ErrorBoundary>
  );
}

export default function RootLayout() {
  const [fontsLoaded] = useFonts({
    Montserrat_400Regular, Montserrat_600SemiBold, Montserrat_700Bold, Montserrat_800ExtraBold,
    Inter_400Regular, Inter_500Medium, Inter_600SemiBold, Inter_700Bold,
  });

  useEffect(() => { setupCrashHandler(); injectWebStyles(); }, []);

  if (!fontsLoaded) return <LoadingScreen />;

  return (
    <I18nProvider initialLocale={null}>
      <AuthProvider>
        <ThemeProvider>
          <AuthRedirect />
          <AppContent />
        </ThemeProvider>
      </AuthProvider>
    </I18nProvider>
  );
}

