  const slideAnim = useMemo(() => new Animated.Value(20), []);
  const tabIndicator = useMemo(() => new Animated.Value(0), []);

  useEffect(() => {
    Animated.parallel([
      Animated.timing(fadeAnim, { toValue: 1, duration: 400, useNativeDriver: true }),
      Animated.spring(slideAnim, { toValue: 0, friction: 8, tension: 55, useNativeDriver: true }),
    ]).start();
  }, []);

  useEffect(() => {
    Animated.spring(tabIndicator, {
      toValue: activeTab === 'list' ? 0 : 1,
      friction: 8,
      tension: 55,
      useNativeDriver: false,
    }).start();
  }, [activeTab]);

  const renderNotification = ({ item, index }: { item: any; index: number }) => (
    <Animated.View style={[styles.notifItem, { opacity: Math.min(1, 0.5 + index * 0.1) }]}>
      <NotificationItem
        notification={item}
        onPress={() => markAsRead(item.id)}
      />
    </Animated.View>
  );

  return (
    <ErrorBoundary screenName="Notifications">
      <View style={layout.screen}>
        <TutorialOverlay visible={tutorialVisible} steps={tutorialSteps} onComplete={handleComplete} onSkip={handleSkip} />

        {/* Header */}
        <Animated.View style={[styles.header, { opacity: fadeAnim, transform: [{ translateY: slideAnim }] }]}>
          <TouchableOpacity onPress={() => router.back()} style={styles.backBtn}>
            <Ionicons name="arrow-back" size={24} color={COLORS.textTitle} />
          </TouchableOpacity>
          <View style={styles.headerCenter}>
            <Text style={[typography.h2, { fontSize: isSmall ? 22 : 28 }]}>Notificacoes</Text>
            {unreadCount > 0 && (
              <View style={styles.badge}>
                <Text style={styles.badgeText}>{unreadCount}</Text>
              </View>
            )}
          </View>
          <View style={styles.headerActions}>
            {activeTab === 'list' && unreadCount > 0 && (
              <TouchableOpacity onPress={markAllAsRead} style={styles.headerBtn}>
                <Ionicons name="checkmark-done" size={20} color={COLORS.primary} />
              </TouchableOpacity>
            )}
            {activeTab === 'list' && notifications.length > 0 && (
              <TouchableOpacity onPress={clearAll} style={styles.headerBtn}>
                <Ionicons name="trash-outline" size={20} color={COLORS.textMuted} />
              </TouchableOpacity>
            )}
          </View>
        </Animated.View>

        {/* Tabs */}
        <View style={styles.tabsContainer}>
          <View style={styles.tabs}>
            {TABS.map(tab => (
              <TouchableOpacity
                key={tab.key}
                style={[styles.tab, activeTab === tab.key && styles.tabActive]}
                onPress={() => setActiveTab(tab.key)}
              >
                <Ionicons name={tab.icon} size={16} color={activeTab === tab.key ? COLORS.primary : COLORS.textMuted} />
                <Text style={[styles.tabText, activeTab === tab.key && styles.tabTextActive]}>{tab.label}</Text>
              </TouchableOpacity>
            ))}
          </View>
        </View>

        {/* Conteudo */}
        {activeTab === 'list' ? (
          notifications.length === 0 && !loading ? (
            <EmptyState
              icon="notifications-off-outline"
              title="Sem notificacoes"
              message="Quando algo acontecer, voce sera notificado aqui."
            />
          ) : (
            <FlatList
              data={notifications}
              keyExtractor={(item) => item.id}
              renderItem={renderNotification}
              contentContainerStyle={styles.listContent}
              refreshControl={
                <RefreshControl refreshing={refreshing} onRefresh={onRefresh} tintColor={COLORS.primary} />
              }
              ListEmptyComponent={loading ? <Loading variant="dots" /> : null}
            />
          )
        ) : (
          <NotificationConfig
            prefs={prefs}
            reminderTime={reminderTime}
            setReminderTime={setReminderTime}
            pushEnabled={pushEnabled}
            quietHours={quietHours}
            onNotifToggle={handleNotifToggle}
            onPushToggle={handlePushToggle}
          />
        )}
      </View>
    </ErrorBoundary>
  );
}

