const { requireRole, requireMinLevel, isRoleAllowed, resolveUserRole, clearRoleCache, ROLE_HIERARCHY } = require('../../src/middleware/role');

describe('Role Middleware (RBAC)', () => {
  let req, res, next;

  beforeEach(() => {
    req = { user: { id: 'user-123' } };
    res = { status: jest.fn().mockReturnThis(), json: jest.fn() };
    next = jest.fn();
    clearRoleCache();
    jest.clearAllMocks();
  });

  describe('ROLE_HIERARCHY', () => {
    it('deve ter hierarquia correta', () => {
      expect(ROLE_HIERARCHY.superadmin).toBeGreaterThan(ROLE_HIERARCHY.admin);
      expect(ROLE_HIERARCHY.admin).toBeGreaterThan(ROLE_HIERARCHY.manager);
      expect(ROLE_HIERARCHY.manager).toBeGreaterThan(ROLE_HIERARCHY.employee);
      expect(ROLE_HIERARCHY.employee).toBeGreaterThan(ROLE_HIERARCHY.user);
    });

    it('community_admin e workout_admin devem ter mesmo nível', () => {
      expect(ROLE_HIERARCHY.community_admin).toBe(ROLE_HIERARCHY.workout_admin);
    });
  });

  describe('isRoleAllowed', () => {
    it('superadmin deve ter acesso a tudo', () => {
      expect(isRoleAllowed('superadmin', ['admin'])).toBe(true);
      expect(isRoleAllowed('superadmin', ['user'])).toBe(true);
      expect(isRoleAllowed('superadmin', ['workout_admin'])).toBe(true);
    });

    it('admin deve herdar manager e employee', () => {
      expect(isRoleAllowed('admin', ['manager'])).toBe(true);
      expect(isRoleAllowed('admin', ['employee'])).toBe(true);
      expect(isRoleAllowed('admin', ['workout_admin'])).toBe(true);
    });

    it('user não deve ter acesso admin', () => {
      expect(isRoleAllowed('user', ['admin'])).toBe(false);
      expect(isRoleAllowed('user', ['superadmin'])).toBe(false);
    });

    it('community_admin não deve ter acesso admin', () => {
      expect(isRoleAllowed('community_admin', ['admin'])).toBe(false);
    });

    it('acesso direto deve funcionar', () => {
      expect(isRoleAllowed('workout_admin', ['workout_admin'])).toBe(true);
      expect(isRoleAllowed('user', ['user'])).toBe(true);
    });
  });

  describe('requireRole', () => {
    it('deve retornar 401 sem usuário', async () => {
      req.user = null;
      const middleware = requireRole(['admin']);
      await middleware(req, res, next);
      expect(res.status).toHaveBeenCalledWith(401);
    });

    it('deve retornar 403 quando role insuficiente', async () => {
      mockSupabase.single.mockResolvedValue({ data: { role: 'user' }, error: null });
      const middleware = requireRole(['admin']);
      await middleware(req, res, next);
      expect(res.status).toHaveBeenCalledWith(403);
    });

    it('deve chamar next quando role permitido', async () => {
      mockSupabase.single.mockResolvedValue({ data: { role: 'admin' }, error: null });
      const middleware = requireRole(['admin']);
      await middleware(req, res, next);
      expect(next).toHaveBeenCalled();
      expect(req.userRole).toBe('admin');
    });

    it('superadmin deve passar em qualquer requireRole', async () => {
      mockSupabase.single.mockResolvedValue({ data: { role: 'superadmin' }, error: null });
      const middleware = requireRole(['admin']);
      await middleware(req, res, next);
      expect(next).toHaveBeenCalled();
      expect(req.userRole).toBe('superadmin');
    });

    it('deve usar cache na segunda chamada', async () => {
      mockSupabase.single.mockResolvedValue({ data: { role: 'admin' }, error: null });
      const middleware = requireRole(['admin']);
      await middleware(req, res, next);
      expect(next).toHaveBeenCalledTimes(1);

      // Segunda chamada com mesmo user
      jest.clearAllMocks();
      res = { status: jest.fn().mockReturnThis(), json: jest.fn() };
      next = jest.fn();
      await middleware(req, res, next);
      expect(next).toHaveBeenCalledTimes(1);
      // Supabase NÃO deve ter sido chamado novamente (cache)
      expect(mockSupabase.single).not.toHaveBeenCalled();
    });

    it('deve adicionar roleLevel ao request', async () => {
      mockSupabase.single.mockResolvedValue({ data: { role: 'superadmin' }, error: null });
      const middleware = requireRole(['admin']);
      await middleware(req, res, next);
      expect(req.roleLevel).toBe(ROLE_HIERARCHY.superadmin);
    });
  });

  describe('requireMinLevel', () => {
    it('deve retornar 401 sem usuário', async () => {
      req.user = null;
      const middleware = requireMinLevel(3);
      await middleware(req, res, next);
      expect(res.status).toHaveBeenCalledWith(401);
    });

    it('deve retornar 403 quando nível insuficiente', async () => {
      mockSupabase.single.mockResolvedValue({ data: { role: 'user' }, error: null });
      const middleware = requireMinLevel(3);
      await middleware(req, res, next);
      expect(res.status).toHaveBeenCalledWith(403);
    });

    it('deve chamar next quando nível suficiente', async () => {
      mockSupabase.single.mockResolvedValue({ data: { role: 'superadmin' }, error: null });
      const middleware = requireMinLevel(3);
      await middleware(req, res, next);
      expect(next).toHaveBeenCalled();
    });
  });
});

const {
  blockBlacklistedIP,
  whitelistOnly,
