// src/middleware/role.ts
// Middleware de Autorização por Cargo (RBAC) - NOVAIX FITNESS

import { Request, Response, NextFunction } from 'express';
import supabase from '../config/supabase';

interface CacheEntry {
  role: string;
  timestamp: number;
}

// Cache de roles em memória com TTL de 5 minutos
const roleCache = new Map<string, CacheEntry>();
const CACHE_TTL_MS = 5 * 60 * 1000;

// Hierarquia de cargos (maior número = mais permissões)
const ROLE_HIERARCHY: Record<string, number> = {
  user: 0,
  creator: 1,
  workout_admin: 2,
  community_admin: 2,
  employee: 2,
  manager: 3,
  admin: 4,
  superadmin: 5,
};

function getCachedRole(userId: string): string | null {
  const entry = roleCache.get(userId);
  if (!entry) return null;
  if (Date.now() - entry.timestamp > CACHE_TTL_MS) {
    roleCache.delete(userId);
    return null;
  }
  return entry.role;
}

function setCachedRole(userId: string, role: string): void {
  roleCache.set(userId, { role, timestamp: Date.now() });
}

function clearRoleCache(userId?: string): void {
  if (userId) roleCache.delete(userId);
  else roleCache.clear();
}

async function resolveUserRole(userId: string): Promise<string> {
  const cached = getCachedRole(userId);
  if (cached) return cached;

  try {
    const { data: profile, error } = await supabase
      .from('profiles')
      .select('role')
      .eq('id', userId)
      .single();

    const role = (!error && profile?.role) ? profile.role : 'user';
    setCachedRole(userId, role);
    return role;
  } catch {
    return 'user';
  }
}

function isRoleAllowed(userRole: string, allowedRoles: string[]): boolean {
  // Verificação direta
  if (allowedRoles.includes(userRole)) return true;

  // Verificação hierárquica: superadmin herda tudo
  if (userRole === 'superadmin') return true;

  // Admin herda roles de manager, employee e admin
  if (userRole === 'admin') {
    return allowedRoles.some(r =>
      ['admin', 'manager', 'employee', 'workout_admin', 'community_admin'].includes(r)
    );
  }

  // Manager herda roles de employee
  if (userRole === 'manager') {
    return allowedRoles.some(r => ['manager', 'employee'].includes(r));
  }

  return false;
}

const requireRole = (allowedRoles: string[]) => {
  return async (req: Request, res: Response, next: NextFunction) => {
    if (!(req as any).user) {
      return res.status(401).json({ error: 'Usuário não autenticado' });
    }

    try {
      const userRole = await resolveUserRole((req as any).user.id);

      if (!isRoleAllowed(userRole, allowedRoles)) {
        return res.status(403).json({
          error: 'Acesso negado. Privilégios insuficientes.',
          requiredRoles: allowedRoles,
          currentRole: userRole,
        });
      }

      (req as any).userRole = userRole;
      (req as any).roleLevel = ROLE_HIERARCHY[userRole] || 0;
      next();
    } catch (err) {
      return res.status(500).json({ error: 'Erro ao verificar permissões' });
    }
  };
};

const requireMinLevel = (minLevel: number) => {
  return async (req: Request, res: Response, next: NextFunction) => {
    if (!(req as any).user) {
      return res.status(401).json({ error: 'Usuário não autenticado' });
    }

    try {
      const userRole = await resolveUserRole((req as any).user.id);
      const level = ROLE_HIERARCHY[userRole] || 0;

      if (level < minLevel) {
        return res.status(403).json({
          error: 'Nível de acesso insuficiente.',
          currentLevel: level,
          requiredLevel: minLevel,
        });
      }

      (req as any).userRole = userRole;
      (req as any).roleLevel = level;
      next();
    } catch (err) {
      return res.status(500).json({ error: 'Erro ao verificar nível de acesso' });
    }
  };
};

export {
  requireRole,
  requireMinLevel,
  resolveUserRole,
  clearRoleCache,
  isRoleAllowed,
  ROLE_HIERARCHY,
};

// src/middleware/subscription.ts
// Middleware de validação de assinatura - NOVAIX FITNESS

import { Request, Response, NextFunction } from 'express';
import supabase from '../config/supabase';

interface PlanConfig {
  maxWorkouts: number;
  maxMessages: number;
  maxCustomWorkouts: number;
  maxFavorites: number;
  features: string[];
}

const PLANS: Record<string, PlanConfig> = {
  free: { 
    maxWorkouts: 3, 
    maxMessages: 0, 
    maxCustomWorkouts: 0,
    maxFavorites: 5,
    features: [] 
  },
  basic: { 
    maxWorkouts: 5, 
    maxMessages: 0, 
    maxCustomWorkouts: 0,
    maxFavorites: 10,
    features: ['workouts', 'favorites'] 
  },
  intermediate: { 
    maxWorkouts: 10, 
    maxMessages: 10, 
    maxCustomWorkouts: 5,
    maxFavorites: 25,
    features: ['workouts', 'chat', 'favorites', 'custom_workouts'] 
  },
  premium: { 
    maxWorkouts: 20, 
    maxMessages: 20, 
    maxCustomWorkouts: 15,
    maxFavorites: 50,
    features: ['workouts', 'chat', 'analytics', 'favorites', 'custom_workouts', 'export'] 
  },
  ultra: { 
    maxWorkouts: 50, 
    maxMessages: 50, 
    maxCustomWorkouts: 50,
    maxFavorites: -1, // ilimitado
    features: ['workouts', 'chat', 'analytics', 'priority', 'favorites', 'custom_workouts', 'export', 'priority_support'] 
  },
};

const requireSubscription = (requiredPlan = 'basic') => {
  return async (req: Request, res: Response, next: NextFunction) => {
    if (!(req as any).user) {
      return res.status(401).json({ error: 'Usuário não autenticado' });
    }

    try {
      const { data: profile, error } = await supabase
        .from('profiles')
        .select('subscription_status, subscription_plan')
        .eq('id', (req as any).user.id)
        .single();

      if (error || !profile) {
        return res.status(404).json({ error: 'Perfil não encontrado' });
      }

      if (profile.subscription_status !== 'active') {
        return res.status(403).json({ 
          error: 'Assinatura necessária',
          required: true,
          currentPlan: profile.subscription_plan || 'free'
        });
      }

      const planHierarchy = ['free', 'basic', 'intermediate', 'premium', 'ultra'];
      const currentLevel = planHierarchy.indexOf(profile.subscription_plan || 'free');
      const requiredLevel = planHierarchy.indexOf(requiredPlan);

      if (currentLevel < requiredLevel) {
        return res.status(403).json({ 
          error: `Plano ${requiredPlan} ou superior necessário`,
          required: true,
          currentPlan: profile.subscription_plan
        });
      }

      (req as any).subscription = {
        plan: profile.subscription_plan,
        status: profile.subscription_status,
        config: PLANS[profile.subscription_plan] || PLANS.free,
      };

      next();
    } catch (err) {
      return res.status(500).json({ error: 'Erro ao verificar assinatura' });
    }
  };
};

const checkFeature = (feature: string) => (req: Request, res: Response, next: NextFunction) => {
  const sub = (req as any).subscription;
  if (!sub) {
    return res.status(403).json({ error: 'Assinatura não verificada' });
  }

  if (!sub.config.features.includes(feature)) {
    return res.status(403).json({ 
      error: `Recurso '${feature}' não disponível no seu plano`,
      feature,
      currentPlan: sub.plan
    });
  }

  next();
};

const checkLimit = (limitType: keyof Omit<PlanConfig, 'features'>) => (req: Request, res: Response, next: NextFunction) => {
  const sub = (req as any).subscription;
  if (!sub) {
    return res.status(403).json({ error: 'Assinatura não verificada' });
  }

  const limit = sub.config[limitType];
  if (limit === undefined) return next();

  (req as any).subscriptionLimit = limit;
  (req as any).subscriptionLimitType = limitType;
  next();
};

export {
  PLANS,
  requireSubscription,
  checkFeature,
  checkLimit,
};

