// Rotas de Ranking Regional e Geolocalização - NOVAIX FITNESS

import express, { Request, Response, Router } from 'express';
import supabase from '../config/supabase';
import { authenticate } from '../middleware/auth';
import { validateBody, sanitizeString } from '../middleware/validate';
import { asyncHandler } from '../middleware/errorHandler';

const router: Router = express.Router();

// Atualizar localização do usuário
router.post('/location',
  authenticate,
  validateBody({
    state: { required: true, type: 'string', minLength: 2, maxLength: 50 },
    city: { required: true, type: 'string', minLength: 2, maxLength: 100 },
    neighborhood: { type: 'string', maxLength: 100 }
  }),
  asyncHandler(async (req: Request, res: Response) => {
    const userId = (req as any).user.id;
    const { state, city, neighborhood } = req.body;

    const cleanState = sanitizeString(state).toUpperCase();
    const cleanCity = sanitizeString(city);
    const cleanNeighborhood = neighborhood ? sanitizeString(neighborhood) : null;

    const { error } = await supabase
      .from('profiles')
      .update({
        state: cleanState,
        city: cleanCity,
        neighborhood: cleanNeighborhood,
        updated_at: new Date()
      })
      .eq('id', userId);

    if (error) throw error;

    res.json({ success: true, message: 'Localização regional atualizada com sucesso' });
  })
);

// Obter ranking regional dinâmico (Fallback de Nível Bairro -> Cidade -> Estado)
router.get('/',
  authenticate,
  asyncHandler(async (req: Request, res: Response) => {
    const userId = (req as any).user.id;

    // 1. Obter localização do usuário logado
    const { data: user, error: userError } = await supabase
      .from('profiles')
      .select('state, city, neighborhood')
      .eq('id', userId)
      .single();

    if (userError || !user || !user.state || !user.city) {
      return res.json({
        level: 'state',
        region: 'Geral',
        message: 'Defina sua localização para ver o ranking regional',
        rankings: []
      });
    }

    const currentPeriod = 'monthly';
    const periodStart = new Date().toISOString().substring(0, 7) + '-01';

    // 2. Tentar nível Bairro (Neighborhood)
    if (user.neighborhood) {
      const { count: neighborhoodCount } = await supabase
        .from('profiles')
        .select('id', { count: 'exact', head: true })
        .eq('state', user.state)
        .eq('city', user.city)
        .eq('neighborhood', user.neighborhood);

      if (neighborhoodCount !== null && neighborhoodCount >= 10) {
        const { data: rankings, error } = await supabase
          .from('regional_rankings')
          .select('points, profiles(name, avatar_url)')
          .eq('region', user.state)
          .eq('city', user.city)
          .eq('neighborhood', user.neighborhood)
          .eq('period', currentPeriod)
          .order('points', { ascending: false })
          .limit(50);

        if (error) throw error;

        return res.json({
          level: 'neighborhood',
          region: user.neighborhood,
          rankings: rankings || []
        });
      }
    }

    // 3. Tentar nível Cidade (City)
    const { count: cityCount } = await supabase
      .from('profiles')
      .select('id', { count: 'exact', head: true })
      .eq('state', user.state)
      .eq('city', user.city);

    if (cityCount !== null && cityCount >= 10) {
      const { data: rawRankings, error } = await supabase
        .from('regional_rankings')
        .select('user_id, points, profiles(name, avatar_url)')
        .eq('region', user.state)
        .eq('city', user.city)
        .eq('period', currentPeriod);

      if (error) throw error;

      // Agrupar pontos por usuário (vários bairros na mesma cidade)
      const aggregated: Record<string, { name: string; avatar_url: string | null; points: number }> = {};
      (rawRankings || []).forEach((r: any) => {
        const uid = r.user_id;
        if (!aggregated[uid]) {
          aggregated[uid] = {
            name: r.profiles?.name || 'Atleta',
            avatar_url: r.profiles?.avatar_url || null,
            points: 0
          };
        }
        aggregated[uid].points += r.points || 0;
      });

      const sorted = Object.values(aggregated)
        .sort((a, b) => b.points - a.points)
        .slice(0, 50);

      return res.json({
        level: 'city',
        region: user.city,
        rankings: sorted
      });
    }

    // 4. Fallback nível Estado (Region/State)
    const { data: rawRankings, error } = await supabase
      .from('regional_rankings')
      .select('user_id, points, profiles(name, avatar_url)')
      .eq('region', user.state)
      .eq('period', currentPeriod);

    if (error) throw error;

    const aggregated: Record<string, { name: string; avatar_url: string | null; points: number }> = {};
    (rawRankings || []).forEach((r: any) => {
      const uid = r.user_id;
      if (!aggregated[uid]) {
        aggregated[uid] = {
          name: r.profiles?.name || 'Atleta',
          avatar_url: r.profiles?.avatar_url || null,
          points: 0
        };
      }
      aggregated[uid].points += r.points || 0;
    });

    const sorted = Object.values(aggregated)
      .sort((a, b) => b.points - a.points)
      .slice(0, 50);

    res.json({
      level: 'state',
      region: user.state,
      rankings: sorted
    });
  })
);

export = router;

// src/routes/webhooks.ts
// Webhooks de Pagamento e Transferência - Asaas (com idempotência e DLQ)

import express, { Request, Response, Router } from 'express';
import * as asaas from '../services/asaas';
import { 
  isEventProcessed, 
  markEventProcessing, 
  markEventCompleted, 
  markEventFailed 
} from '../services/webhookIdempotency';
import { 
  handlePaymentReceived, 
  handlePaymentCreated, 
  handlePaymentUpdated, 
  handlePaymentOverdue, 
  handlePaymentDeleted, 
  handlePaymentRefunded 
} from '../services/paymentHandlers';
import { 
  handleSubscriptionCreated, 
  handleSubscriptionUpdated, 
  handleSubscriptionDeleted, 
  handleSubscriptionInactivated, 
  handleSubscriptionReactivated 
} from '../services/subscriptionHandlers';
import { 
  handleTransferConfirmed, 
  handleTransferFailed 
} from '../services/transferHandlers';

const router: Router = express.Router();

interface AsaasWebhookBody {
  event: string;
  payment?: {
    id: string;
    dateCreated?: string;
    value?: number;
    billingType?: string;
    paymentDate?: string;
    status?: string;
  };
  subscription?: {
    id: string;
  };
  transfer?: {
    id: string;
    failReason?: string;
  };
}

const HANDLERS: Record<string, (payload: any) => Promise<void>> = {
  PAYMENT_RECEIVED: handlePaymentReceived,
  PAYMENT_CREATED: handlePaymentCreated,
  PAYMENT_UPDATED: handlePaymentUpdated,
  PAYMENT_OVERDUE: handlePaymentOverdue,
  PAYMENT_DELETED: handlePaymentDeleted,
  PAYMENT_REFUNDED: handlePaymentRefunded,
  SUBSCRIPTION_CREATED: handleSubscriptionCreated,
  SUBSCRIPTION_UPDATED: handleSubscriptionUpdated,
  SUBSCRIPTION_DELETED: handleSubscriptionDeleted,
  SUBSCRIPTION_INACTIVATED: handleSubscriptionInactivated,
  SUBSCRIPTION_REACTIVATED: handleSubscriptionReactivated,
  TRANSFER_CONFIRMED: handleTransferConfirmed,
  TRANSFER_FAILED: handleTransferFailed,
};

function deriveEventId(body: AsaasWebhookBody): string {
  const { event, payment, subscription, transfer } = body;
  const entityId = payment?.id || subscription?.id || transfer?.id || 'unknown';
  return `${event}_${entityId}_${payment?.dateCreated || Date.now()}`;
}

router.get('/asaas', (req: Request, res: Response) => {
  res.json({ ok: true, message: 'Nix Asaas Webhook Active' });
});

router.post('/asaas', async (req: Request, res: Response) => {
  const token = req.headers['asaas-access-token'];
  if (!asaas.verifyWebhookToken(token as string)) {
    console.warn(`⚠️ Webhook token inválido. Recebido: "${token}" | Esperado: "${process.env.ASAAS_WEBHOOK_TOKEN}"`);
    return res.status(401).json({ error: 'Token inválido' });
  }

  console.log('📦 Webhook Body:', JSON.stringify(req.body, null, 2));
  const { event, payment, subscription, transfer } = req.body as AsaasWebhookBody;
  const eventId = deriveEventId(req.body);

  // Responder imediatamente ao Asaas para autorização e evitar timeout
  res.json({ received: true, approved: true, status: 'APPROVED' });

  // Processar em background
  try {
    if (await isEventProcessed(eventId)) {
      console.info(`⏩ Evento já processado: ${eventId}`);
      return;
    }

    await markEventProcessing(eventId, event, req.body);
    console.info('📨 Webhook recebido:', event, '| ID:', eventId);

    const handler = HANDLERS[event];
    if (handler) {
      const payload = payment || subscription || transfer;
      await handler(payload);
    } else {
      console.warn('Evento não tratado:', event);
    }

    await markEventCompleted(eventId);
    console.info('✅ Webhook processado:', eventId);
  } catch (err: any) {
    console.error('❌ Erro no webhook:', event, err.message);
    await markEventFailed(eventId, event, req.body, err);
  }
});

export = router;

// src/routes/workouts/activity.ts
// Rotas de Atividade de Treinos - NOVAIX FITNESS

import express, { Request, Response, Router } from 'express';
import supabase from '../../config/supabase';
import { authenticate } from '../../middleware/auth';
import { requireSubscription } from '../../middleware/subscription';
import { validateQuery, validateBody, sanitizeString } from '../../middleware/validate';
import { auditWorkout } from '../../middleware/audit';
import { asyncHandler } from '../../middleware/errorHandler';

const router: Router = express.Router();

// Marcar treino como concluído
router.post('/:id/complete', 
  authenticate, 
  requireSubscription('basic'),
  auditWorkout,
  validateBody({
    rating: { type: 'number', min: 1, max: 5 },
    notes: { type: 'string', maxLength: 500 },
    duration: { type: 'number', min: 1, max: 600 },
    calories: { type: 'number', min: 0, max: 5000 }
  }),
  asyncHandler(async (req: Request, res: Response) => {
    const { rating, notes, duration, calories } = req.body;
    const workoutId = sanitizeString(req.params.id);
    const { data: workout } = await supabase
      .from('workouts')
      .select('id, name, is_premium')
      .eq('id', workoutId)
      .single();
    if (!workout) {
      return res.status(404).json({ error: 'Treino não encontrado' });
    }
    const { count } = await supabase
      .from('user_workouts')
      .select('*', { count: 'exact', head: true })
      .eq('user_id', (req as any).user.id)
      .eq('completed', true);
    const maxWorkouts = (req as any).subscription.config.maxWorkouts;
    if (count !== null && count >= maxWorkouts) {
      return res.status(403).json({ 
        error: 'Limite de treinos do plano atingido',
        limit: true,
        current: count,
        max: maxWorkouts,
        plan: (req as any).subscription.plan,
        upgradeRequired: true
      });
    }
    const { data, error } = await supabase
      .from('user_workouts')
      .upsert({
        user_id: (req as any).user.id,
        workout_id: workoutId,
        completed: true,
        completed_at: new Date(),
        rating: rating || null,
        notes: notes ? sanitizeString(notes) : null,
        duration_minutes: duration || null,
        calories_burned: calories || null
      }, { onConflict: 'user_id,workout_id' })
      .select()
      .single();
    if (error) throw error;
    const earnedPoints = 50 + (rating || 0) * 10;
    await supabase.rpc('increment_user_stats', {
      p_user_id: (req as any).user.id,
      p_workouts: 1,
      p_minutes: duration || 0,
      p_xp: earnedPoints
    });
    try {
      const { data: profile } = await supabase
        .from('profiles')
        .select('state, city, neighborhood')
        .eq('id', (req as any).user.id)
        .single();
      if (profile && profile.state && profile.city) {
        const periodStart = new Date().toISOString().substring(0, 7) + '-01';
        const { data: existingRanking } = await supabase
          .from('regional_rankings')
          .select('points')
          .eq('user_id', (req as any).user.id)
          .eq('region', profile.state)
          .eq('city', profile.city)
          .eq('neighborhood', profile.neighborhood)
          .eq('period', 'monthly')
          .maybeSingle();
        await supabase
          .from('regional_rankings')
          .upsert({
            user_id: (req as any).user.id,
            region: profile.state,
            city: profile.city,
            neighborhood: profile.neighborhood,
            period: 'monthly',
            period_start: periodStart,
            points: (existingRanking?.points || 0) + earnedPoints
          }, { onConflict: 'user_id,region,city,neighborhood,period' });
      }
    } catch (err: any) {
      console.warn('Erro ao atualizar ranking regional:', err.message);
    }
    res.json({
      success: true,
      workout: data,
      stats: {
        completedToday: (count || 0) + 1,
        maxWorkouts,
        remaining: maxWorkouts - (count || 0) - 1
      }
    });
  })
);

// Estatísticas do usuário
router.get('/user/stats', 
  authenticate, 
  asyncHandler(async (req: Request, res: Response) => {
    const { data: profile } = await supabase
      .from('profiles')
      .select('total_workouts, total_minutes, total_xp, streak, max_streak, subscription_plan')
      .eq('id', (req as any).user.id)
      .single();
    const { count: completedWorkouts } = await supabase
      .from('user_workouts')
      .select('*', { count: 'exact', head: true })
      .eq('user_id', (req as any).user.id)
      .eq('completed', true);
    const { count: favoriteCount } = await supabase
      .from('favorites')
      .select('*', { count: 'exact', head: true })
      .eq('user_id', (req as any).user.id);
    const { data: recentWorkouts } = await supabase
      .from('user_workouts')
      .select('completed_at, rating')
      .eq('user_id', (req as any).user.id)
      .eq('completed', true)
      .order('completed_at', { ascending: false })
      .limit(10);
    const avgRating = recentWorkouts && recentWorkouts.length > 0
      ? recentWorkouts.reduce((sum, w) => sum + (w.rating || 0), 0) / recentWorkouts.length
      : 0;
    res.json({
      totalWorkouts: profile?.total_workouts || completedWorkouts || 0,
      totalMinutes: profile?.total_minutes || 0,
      totalXP: profile?.total_xp || 0,
      currentStreak: profile?.streak || 0,
      maxStreak: profile?.max_streak || 0,
      favoriteCount: favoriteCount || 0,
      averageRating: Math.round(avgRating * 10) / 10,
      plan: profile?.subscription_plan || 'free'
    });
  })
);

// Gerar link de compartilhamento
router.post('/:id/share', 
  authenticate, 
  requireSubscription('basic'),
  auditWorkout,
  asyncHandler(async (req: Request, res: Response) => {
    const workoutId = sanitizeString(req.params.id);
    const { data: workout } = await supabase
      .from('workouts')
      .select('id, name, category, level')
      .eq('id', workoutId)
      .single();
    if (!workout) {
      return res.status(404).json({ error: 'Treino não encontrado' });
    }
    const shareUrl = `https://novaixfitness.com/workout/${workoutId}`;
    const shareText = `Treinei "${workout.name}" no NOVAIX Fitness! 🏋️`;
    res.json({
      url: shareUrl,
      text: shareText,
      workout: {
        id: workout.id,
        name: workout.name,
        category: workout.category,
        level: workout.level
      }
    });
  })
);

export = router;

