// find-collisions.js - Find all duplicate barrel exports
const fs = require('fs');
const path = require('path');

function findExports(dir, prefix = '') {
  const results = [];
  const entries = fs.readdirSync(dir, { withFileTypes: true });
  for (const entry of entries) {
    const fullPath = path.join(dir, entry.name);
    if (entry.isDirectory()) {
      results.push(...findExports(fullPath, prefix ? `${prefix}/${entry.name}` : entry.name));
    } else if (entry.name === 'barrel.ts' || entry.name === 'index.ts') {
      const content = fs.readFileSync(fullPath, 'utf8');
      const exportMatches = content.matchAll(/export\s*\{[^}]*as\s+(\w+)/g);
      for (const m of exportMatches) {
        results.push({ name: m[1], file: `${prefix}/${entry.name}` });
      }
    }
  }
  return results;
}

const exports = findExports(path.join(process.cwd(), 'src', 'components'));
const byName = {};
for (const e of exports) {
  if (!byName[e.name]) byName[e.name] = [];
  byName[e.name].push(e.file);
}
const collisions = Object.entries(byName).filter(([_, files]) => files.length > 1);
console.log(`Found ${collisions.length} collisions:`);
for (const [name, files] of collisions) {
  console.log(`  ${name}: ${files.join(' vs ')}`);
}

