// fix-service-tests.js
// Transform all service tests to use the shared mock pattern
const fs = require('fs');
const path = require('path');

const dir = path.join(process.cwd(), '__tests__', 'services');
let count = 0;

// Get all .test.js files in services dir
const files = fs.readdirSync(dir).filter(f => f.endsWith('.test.js'));

for (const file of files) {
  const filePath = path.join(dir, file);
  let content = fs.readFileSync(filePath, 'utf8');

  // Skip if no jest.mock for supabase
  if (!content.includes("jest.mock('../../src/config/supabase'")) {
    console.log('SKIP (no mock):', file);
    continue;
  }

  // Skip if already transformed (has _reset)
  if (content.includes('_reset()') || content.includes('createServiceMock')) {
    console.log('SKIP (already done):', file);
    continue;
  }

  // Find import section and everything after
  const importRegex = /^(import [\s\S]*?from ['"][^'"]+['"];?\s*\n?)+/m;
  const importMatch = content.match(importRegex);

  if (!importMatch) {
    console.log('SKIP (no imports):', file);
    continue;
  }

  const imports = importMatch[0];
  const afterImports = content.slice(importMatch.index + imports.length);

  // Find the jest.mock block for supabase
  const mockBlockRegex = /jest\.mock\('(\.\.\/\.\.\/src\/config\/supabase)',\s*\(\)\s*=>\s*\([\s\S]*?\)\);\s*/;
  const mockMatch = afterImports.match(mockBlockRegex);

  if (!mockMatch) {
    console.log('SKIP (mock pattern not matched):', file);
    continue;
  }

  // Find the old const mockSupabase declaration (if any)
  const oldMockRegex = /const mockSupabase = \{[\s\S]*?\};\s*\n?/;
  const oldMockMatch = afterImports.match(oldMockRegex);

  // Get content after the old mock + jest.mock block
  let rest = afterImports;
  if (oldMockMatch) {
    rest = rest.slice(oldMockMatch.index + oldMockMatch[0].length);
  }
  // Remove the jest.mock block too
  const mockInRest = rest.match(mockBlockRegex);
  if (mockInRest) {
    rest = rest.slice(mockInRest.index + mockInRest[0].length);
  }

  // Build new content
  const newContent = `${imports}jest.mock('../../src/config/supabase', () => {
  const { createServiceMock } = require('../../__mocks__/supabase-test');
  return { supabase: createServiceMock() };
});

const { supabase: mockSupabase } = require('../../src/config/supabase');
${rest}`;

  // Replace mockSupabase.data = X with mockSupabase._setData(X)
  let fixed = newContent.replace(/mockSupabase\.data\s*=\s*([^;]+);/g, 'mockSupabase._setData($1);');
  fixed = fixed.replace(/mockSupabase\.error\s*=\s*([^;]+);/g, 'mockSupabase._setError($1);');

  // Add _reset() in beforeEach
  fixed = fixed.replace(
    /beforeEach\(\(\)\s*=>\s*\{([\s\S]*?)\}\);/g,
    (match, body) => {
      if (body.includes('_reset()')) return match;
      return `beforeEach(() => {${body}
    mockSupabase._reset();
  });`;
    }
  );

  fs.writeFileSync(filePath, fixed, 'utf8');
  count++;
  console.log('FIXED:', file);
}

console.log('Total fixed:', count);

