  const imports = importMatch[0];

  // Extract mock object
  const propsMatch = content.match(/const mockSupabase = (\{[\s\S]*?\});\s*\njest\.mock/);
  if (!propsMatch) {
    console.log('SKIP (no props):', file);
    continue;
