  const afterImports = content.slice(importMatch.index + imports.length);

  // Remove old jest.mock from afterImports if present
  const cleanedAfter = afterImports.replace(
    /jest\.mock\('([^']+config\/supabase)', \(\) => \(\{[\s\S]*?\}\)\);\s*\n?/,
    ''
  );

  // Extract the mock properties
  const propsBlock = propsMatch[1];

  const newContent = `jest.mock('${mockPath}', () => {
  const mockObj = ${propsBlock};
  if (mockObj.from) {
    const origFrom = mockObj.from;
    mockObj.from = jest.fn((...args) => {
      const chain = origFrom(...args);
      return chain && chain.then ? chain : mockObj;
    });
  }
  return { supabase: mockObj };
});

const { supabase: mockSupabase } = require('${mockPath}');

${cleanedAfter}`;

