#!/usr/bin/env node
// scripts/security-gate.js
// Security gate - bloqueia commit se houver violações

const { SecurityChecker } = require('./security-check');
const { execSync } = require('child_process');

console.log('🛡️  SECURITY GATE - Verificando segurança antes do commit...\n');

// ============================================
// 1. VERIFICAR SEGURANÇA DO CÓDIGO
// ============================================

const checker = new SecurityChecker();
checker.checkDirectory('src');
checker.checkDirectory('app');

const report = checker.getReport();

if (report.errors.length > 0) {
  console.log('❌ BLOCKED: Violações de segurança encontradas!\n');
  checker.printReport();
  console.log('\n🔧 Corrija os erros antes de commitar.\n');
  process.exit(1);
}

// ============================================
// 2. VERIFICAR SECRETS NO GIT
// ============================================

try {
  const gitDiff = execSync('git diff --cached --name-only', { encoding: 'utf8' });
  const files = gitDiff.split('\n').filter(Boolean);

  for (const file of files) {
    if (file.endsWith('.env') || file.endsWith('.env.local') || file.endsWith('.env.production')) {
      console.log(`❌ BLOCKED: Arquivo ${file} não pode ser commitado!`);
      console.log('   Adicione ao .gitignore.\n');
      process.exit(1);
    }
  }
} catch (err) {
  // git diff pode falhar se não estiver em um repo git
}

// ============================================
// 3. VERIFICAR .gitignore
// ============================================

const fs = require('fs');
const path = require('path');

const gitignorePath = path.join(process.cwd(), '.gitignore');
if (fs.existsSync(gitignorePath)) {
  const gitignore = fs.readFileSync(gitignorePath, 'utf8');
  const requiredPatterns = ['.env', 'node_modules', '*.log'];

  for (const pattern of requiredPatterns) {
    if (!gitignore.includes(pattern)) {
      console.log(`⚠️  AVISO: ${pattern} não está no .gitignore`);
    }
  }
}

// ============================================
// 4. VERIFICAR DEPENDÊNCIAS VULNERÁVEIS
// ============================================

try {
  execSync('npm audit --audit-level=high 2>/dev/null', { stdio: 'pipe' });
} catch (err) {
  if (err.status !== 0) {
    console.log('⚠️  AVISO: Dependências com vulnerabilidades altas encontradas.');
    console.log('   Execute: npm audit fix\n');
  }
}

// ============================================
// 5. VERIFICAR SE HÁ MUDANÇAS NOS ARQUIVOS DE SEGURANÇA
// ============================================

try {
  const gitDiff = execSync('git diff --cached --name-only', { encoding: 'utf8' });
  const securityFiles = [
    'src/security/',
    'src/middleware/auth.js',
    'src/middleware/rateLimit.js',
    'src/services/security.js',
    'src/services/contentModeration.js',
  ];

  const changedSecurityFiles = gitDiff.split('\n').filter(f =>
    securityFiles.some(sf => f.includes(sf))
  );

  if (changedSecurityFiles.length > 0) {
    console.log('🔒 AVISO: Arquivos de segurança foram modificados:');
    changedSecurityFiles.forEach(f => console.log(`   - ${f}`));
    console.log('\n   Certifique-se de que as mudanças são seguras.\n');
  }
} catch (err) {
  // Pode falhar se não estiver em repo git
}

// ============================================
// RESULTADO
// ============================================

if (report.warnings.length > 0) {
  console.log(`\n⚠️  ${report.warnings.length} avisos encontrados.`);
  console.log('   Recomendado corrigir antes de commitar.\n');
}

console.log('✅ Security gate passou! Commit permitido.\n');
process.exit(0);

// ============================================
// REGRA 1: CONSOLE.LOG EM PRODUÇÃO
// ============================================
// Nível: CRÍTICO | Tipo: BLOCK
// Padrão: Netflix, Stripe, Nubank

/**
 * OBJETIVO: Impedir QUALQUER console.log() que não esteja
 * protegido por if (__DEV__) ou use logger.dev().
 *
 * POR QUE É PERIGOSO:
 * - console.log() em produção expõe dados sensíveis no console
 * - Navegadores móveis salvam logs que podem ser acessados
 * - Ferramentas como Sentry capturam logs e enviam para servidores
 * - Atacantes podem usar console.log para mapear estrutura interna
 *
 * O QUE VERIFICA:
 * 1. Procura TODOS os console.log() no arquivo
 * 2. Verifica se cada um está DENTRO de um bloco if (__DEV__)
 * 3. Verifica se usa logger.dev() ou wrapper seguro
 * 4. Detecta console.log em strings templates
 * 5. Detecta console.log em callbacks aninhados
 * 6. Verifica console.log dentro de funções arrow
 * 7. Detecta console.log condicional complexo
 */

module.exports = {
  name: 'Console.log Protection',
  version: '1.0.0',
  severity: 'BLOCK',
  description: 'Bloqueia console.log() fora de blocos __DEV__',

  rules: [
    {
      id: 'R01_CONSOLE_LOG',
      name: 'Console.log Detection',
      severity: 'BLOCK',

      // ============================================
      // MÉTODO 1: Análise linha por linha com rastreamento de escopo
      // ============================================
      check: (filePath, content) => {
        // Excluir arquivos de logger (são o wrapper)
        if (filePath.includes('logger.js') || filePath.includes('logger.ts')) {
          return [];
        }

        const violations = [];
        const lines = content.split('\n');

        // Estado do rastreamento de escopo
        let devBlockDepth = 0;      // Profundidade dentro de if (__DEV__)
        let isInDevBlock = false;    // Estamos dentro de um bloco __DEV__?
        let braceCount = 0;          // Contador de chaves
        let parenCount = 0;          // Contador de parênteses
        let bracketCount = 0;        // Contador de colchetes

        // Padrões que indicam proteção __DEV__
        const devPatterns = [
          /if\s*\(\s*__DEV__\s*\)/,
          /if\s*\(\s*__DEV__\s*&&/,
          /if\s*\(\s*!?\s*__DEV__\s*\)/,
          /if\s*\(\s*process\.env\.NODE_ENV\s*===?\s*['"]development['"]\s*\)/,
          /if\s*\(\s*process\.env\.NODE_ENV\s*!==?\s*['"]production['"]\s*\)/,
        ];

        // Padrões que indicam wrapper seguro
        const safePatterns = [
          /logger\.dev\(/,
          /logger\.info\(/,
          /devLog\(/,
          /debug\(/,
          /logDev\(/,
          /if\s*\(\s*__DEV__\s*\)\s*console\./,
        ];

        // Padrões que indicam retorno antecipado em dev
        const devReturnPatterns = [
          /if\s*\(\s*!?\s*__DEV__\s*\)\s*return/,
          /if\s*\(\s*!?\s*__DEV__\s*\)\s*return\s*;/,
        ];

        // Arquivos que são o próprio logger (excluir)
        if (filePath.includes('logger.js') || filePath.includes('logger.ts')) {
          return [];
        }

        for (let i = 0; i < lines.length; i++) {
          const line = lines[i];
          const trimmed = line.trim();

          // Detectar início de bloco __DEV__
          for (const pattern of devPatterns) {
            if (pattern.test(trimmed)) {
              isInDevBlock = true;
              devBlockDepth = 0;
              braceCount = 0;
            }
          }

          // Rastrear escopo com chaves
          if (isInDevBlock) {
            braceCount += (line.match(/{/g) || []).length;
            braceCount -= (line.match(/}/g) || []).length;

            // Se saiu do bloco
            if (braceCount <= 0 && i > 0) {
              isInDevBlock = false;
              devBlockDepth = 0;
            }
          }

          // Verificar se tem console.log
          if (trimmed.includes('console.log(')) {
            // Verificar se é wrapper seguro
            const isSafe = safePatterns.some(p => p.test(trimmed));

          // Verificar se está dentro de __DEV__
          const isInDev = isInDevBlock || devPatterns.some(p => {
            // Verificar nas 20 linhas anteriores
            const start = Math.max(0, i - 20);
            return lines.slice(start, i + 1).some(l => p.test(l));
          }) || devReturnPatterns.some(p => {
            // Verificar se há retorno antecipado com __DEV__
            const start = Math.max(0, i - 30);
            return lines.slice(start, i + 1).some(l => p.test(l));
          });

            if (!isSafe && !isInDev) {
              violations.push({
                file: filePath,
                line: i + 1,
                rule: 'R01_CONSOLE_LOG',
                message: `console.log() fora de bloco __DEV__. Use logger.dev() ou if (__DEV__) console.log()`,
                severity: 'BLOCK',
                code: trimmed.substring(0, 80),
                context: getContext(lines, i, 3),
              });
            }
          }

          // Detectar console.log em template literals
          if (trimmed.match(/console\.log\s*\(\s*`/)) {
            const isSafe = safePatterns.some(p => p.test(trimmed));
            if (!isSafe) {
              violations.push({
                file: filePath,
                line: i + 1,
                rule: 'R01_CONSOLE_LOG',
                message: `console.log com template literal. Dados podem vazar em produção`,
                severity: 'BLOCK',
                code: trimmed.substring(0, 80),
              });
            }
          }

          // Detectar console.log com spread de objetos
          if (trimmed.match(/console\.log\s*\(\s*\.\.\./)) {
            violations.push({
              file: filePath,
              line: i + 1,
              rule: 'R01_CONSOLE_LOG',
              message: `console.log com spread de objeto expõe todos os dados`,
              severity: 'BLOCK',
              code: trimmed.substring(0, 80),
            });
          }

          // Detectar console.log com JSON.stringify
          if (trimmed.match(/console\.log\s*\(\s*JSON\.stringify/)) {
            violations.push({
              file: filePath,
              line: i + 1,
              rule: 'R01_CONSOLE_LOG',
              message: `console.log com JSON.stringify expõe dados estruturados`,
              severity: 'BLOCK',
              code: trimmed.substring(0, 80),
            });
          }
        }

        return violations;
      },
    },
  ],
};

// Função auxiliar para obter contexto
function getContext(lines, currentIndex, radius) {
  const start = Math.max(0, currentIndex - radius);
  const end = Math.min(lines.length, currentIndex + radius + 1);
  return lines.slice(start, end).join('\n');
}

// ============================================
// REGRA 37: LOCKFILE SYNC
// ============================================
// Nível: ALTO | Tipo: WARNING

/**
 * OBJETIVO: Verificar sincronia entre package.json e lockfile.
 */

module.exports = {
  name: 'Lockfile Sync Check',
  version: '1.0.0',
  severity: 'WARNING',
  description: 'Verifica se lockfile existe',

  rules: [
    {
      id: 'R37_LOCKFILE',
      name: 'Lockfile Sync Check',
      severity: 'WARNING',

      check: (filePath, content) => {
        if (!filePath.endsWith('package.json')) return [];

        const violations = [];
        const fs = require('fs');
        const path = require('path');

        const dir = path.dirname(filePath);
        const hasLock = fs.existsSync(path.join(dir, 'package-lock.json'));
        const hasYarnLock = fs.existsSync(path.join(dir, 'yarn.lock'));

        if (!hasLock && !hasYarnLock) {
          violations.push({
            file: filePath, line: 0, rule: 'R37_LOCKFILE',
            message: 'package.json sem lockfile. Rode npm install ou yarn install',
            severity: 'WARNING', code: 'Sem package-lock.json ou yarn.lock',
          });
        }
        return violations;
      },
    },
  ],
};

// ============================================
// REGRAS 77-80: SEGURANÇA DO SERVIDOR
// ============================================
// Nível: ALTO | Tipo: WARNING

/**
 * Regras 77-80:
 * 77. Criptografia pós-quântica
 * 78. Computação confidencial
 * 79. Criptografia homomórfica
 * 80. Decepção ativa (Honey Network)
 */

module.exports = {
  name: 'Server Security',
  rules: [
    {
      id: 'R77_POST_QUANTUM',
      check: (fp, content) => {
        if (!content.includes('crypto') && !content.includes('encrypt')) return null;
        const hasModern = content.includes('AES-256') || content.includes('ChaCha20') || content.includes('Ed25519');
        if (!hasModern) return { msg: 'Considere algoritmos pós-quânticos para criptografia', severity: 'WARNING' };
        return null;
      },
    },
    {
      id: 'R78_CONFIDENTIAL_COMPUTING',
      check: (fp, content) => {
        if (!fp.includes('security') && !fp.includes('crypto')) return null;
        return { msg: 'Para dados ultra-sensíveis, considere Intel SGX ou AMD SEV', severity: 'WARNING' };
      },
    },
    {
      id: 'R79_HOMOMORPHIC',
      check: (fp, content) => {
        if (!content.includes('encrypt') || !content.includes('analytics')) return null;
        return { msg: 'Para analytics com dados sensíveis, considere criptografia homomórfica', severity: 'WARNING' };
      },
    },
    {
      id: 'R80_HONEY_NETWORK',
      check: (fp, content) => {
        if (!fp.includes('honey') && !content.includes('honeytoken')) return null;
        return { msg: 'Honey tokens implementados - bom para detecção de intrusão', severity: 'WARNING' };
      },
    },
  ],
};

