const MAX_COMMENT_LENGTH = 500;

function ProductReviews({ productId }) {
  const { t } = useI18n();
  const { user } = useAuth();
  const [reviews, setReviews] = useState([]);
  const [rating, setRating] = useState(5);
  const [comment, setComment] = useState('');
  const [submitting, setSubmitting] = useState(false);
  const [showForm, setShowForm] = useState(false);

  useEffect(() => {
    async function load() {
      const { data } = await supabase
        .from('marketplace_reviews')
        .select('*, profiles(name)')
        .eq('product_id', productId)
        .order('created_at', { ascending: false })
        .limit(20);
      setReviews(data || []);
    }
    load();
  }, [productId]);

  const handleSubmit = async () => {
    if (!user?.id || !comment.trim()) return;
    setSubmitting(true);
    try {
      const { data, error } = await supabase
        .from('marketplace_reviews')
        .insert({ product_id: productId, user_id: user.id, rating, comment: comment.trim().slice(0, MAX_COMMENT_LENGTH) })
        .select('*, profiles(name)')
        .single();
      if (error) {
        Alert.alert(error.code === '23505' ? t('common.success') : t('common.error'), error.code === '23505' ? t('marketplace.reviewDuplicate') : t('marketplace.reviewSendError'));
        return;
      }
      if (data) {
        setReviews(prev => [data, ...prev]);
        setComment('');
        setRating(5);
        setShowForm(false);
      }
    } catch { Alert.alert(t('common.error'), t('marketplace.reviewSendFailed')); }
    setSubmitting(false);
  };

  const avgRating = reviews.length > 0 ? (reviews.reduce((s, r) => s + r.rating, 0) / reviews.length).toFixed(1) : 0;

  return (
    <View style={styles.container}>
      <View style={styles.header}>
        <Text style={styles.title}>AVALIACOES ({reviews.length})</Text>
        {reviews.length > 0 && (
          <View style={styles.avgRow}>
            <Ionicons name="star" size={14} color={COLORS.star} />
            <Text style={styles.avgText}>{avgRating}</Text>
          </View>
        )}
      </View>

      {user?.id && (
        <>
          {!showForm ? (
            <TouchableOpacity style={styles.addBtn} onPress={() => setShowForm(true)}>
              <Ionicons name="create-outline" size={16} color={COLORS.primary} />
              <Text style={styles.addBtnText}>Escrever avaliacao</Text>
            </TouchableOpacity>
          ) : (
            <ReviewForm rating={rating} setRating={setRating} comment={comment} setComment={setComment} submitting={submitting} onSubmit={handleSubmit} onCancel={() => setShowForm(false)} />
          )}
        </>
      )}

      {reviews.map((review) => (
        <View key={review.id} style={styles.reviewCard}>
          <View style={styles.reviewHeader}>
            <Text style={styles.reviewerName}>{review.profiles?.name || 'Anonimo'}</Text>
            <View style={styles.reviewStars}>
              {[1, 2, 3, 4, 5].map(i => (
                <Ionicons key={i} name={i <= review.rating ? 'star' : 'star-outline'} size={12} color={COLORS.star} />
              ))}
            </View>
          </View>
          <Text style={styles.reviewComment}>{review.comment}</Text>
          <Text style={styles.reviewDate}>{new Date(review.created_at).toLocaleDateString('pt-BR')}</Text>
        </View>
      ))}
    </View>
  );
}

