        </View>
      </View>
    </View>
  );
}

export default function FoodDatabase() {
  const [foods, setFoods] = useState(FALLBACK_FOODS);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState('');
  const [selectedCategory, setSelectedCategory] = useState('Todos');

  useEffect(() => { loadFoods(); }, []);

  const loadFoods = async () => {
    setLoading(true);
    try {
      const data = await getNutritionContent('foods');
      if (data?.foods && data.foods.length > 0) {
        setFoods(data.foods);
      }
    } catch (e) { if (__DEV__) console.warn('FoodDatabase:', e); }
    finally { setLoading(false); }
  };

  const handleRefresh = async () => {
    setLoading(true);
    try {
      const data = await refreshNutritionContent('foods');
      if (data?.foods && data.foods.length > 0) {
        setFoods(data.foods);
      }
    } catch (e) { if (__DEV__) console.warn('FoodDatabase:', e); }
    finally { setLoading(false); }
  };

  const filtered = useMemo(() => {
    let result = foods;
    if (selectedCategory !== 'Todos') {
      result = result.filter(f => f.cat === selectedCategory);
    }
    if (search.trim()) {
      const lower = search.toLowerCase();
      result = result.filter(f => f.name.toLowerCase().includes(lower));
    }
    return result;
  }, [foods, search, selectedCategory]);

  return (
    <View style={styles.container}>
      <View style={styles.header}>
        <Ionicons name="nutrition" size={18} color={COLORS.primary} />
        <Text style={styles.title}>TABELA DE ALIMENTOS</Text>
        <TouchableOpacity accessibilityLabel="Atualizar lista" accessibilityRole="button" onPress={handleRefresh} style={styles.refreshBtn}>
          <Ionicons name={loading ? 'sync' : 'refresh'} size={14} color={COLORS.primary} />
        </TouchableOpacity>
      </View>

      <View style={styles.searchContainer}>
        <Ionicons name="search" size={18} color={COLORS.textMuted} />
        <TextInput
          style={styles.searchInput}
          value={search}
          onChangeText={setSearch}
          placeholder="Buscar alimento..."
          placeholderTextColor={COLORS.textMuted}
        />
        {search.length > 0 && (
          <TouchableOpacity accessibilityLabel="Limpar busca" accessibilityRole="button" onPress={() => setSearch('')}>
            <Ionicons name="close-circle" size={18} color={COLORS.textMuted} />
          </TouchableOpacity>
        )}
      </View>

      <View style={styles.categoryRow}>
        {FOOD_CATEGORIES.map(cat => (
          <TouchableOpacity key={cat} accessibilityLabel={`Filtrar por ${cat}`} accessibilityRole="button" style={[styles.categoryBtn, selectedCategory === cat && styles.categoryActive]} onPress={() => setSelectedCategory(cat)}>
            <Text style={[styles.categoryText, selectedCategory === cat && styles.categoryTextActive]}>{cat}</Text>
          </TouchableOpacity>
        ))}
      </View>

      <Text style={styles.resultCount}>{filtered.length} alimentos{loading ? ' (carregando...)' : ''}</Text>

      <FlatList
          removeClippedSubviews={true}
          maxToRenderPerBatch={10}
          windowSize={5}
        data={filtered}
        keyExtractor={(item, i) => `${item.name}-${i}`}
        renderItem={({ item }) => <FoodItem food={item} />}
        scrollEnabled={false}
        ItemSeparatorComponent={() => <View style={styles.separator} />}
      />
    </View>
  );
}

const styles = StyleSheet.create({
