export default function MealHistory({ userId }) {
  const { t } = useI18n();
  const [meals, setMeals] = useState([]);
  const [loading, setLoading] = useState(true);
  const [filter, setFilter] = useState('all');
  const mounted = useMountedRef();

  useEffect(() => { loadMeals(); }, [userId]);

  const loadMeals = async () => {
    if (!mounted.current) return;
    setLoading(true);
    try {
      const data = await getMealLogs(userId);
      if (!mounted.current) return;
      setMeals(data);
    } catch (err) {
      if (__DEV__) console.error('Erro ao carregar histórico:', err);
    } finally {
      if (mounted.current) setLoading(false);
    }
  };

  const filtered = useMemo(() => {
    if (filter === 'all') return meals;
    return meals.filter(m => m.meal_type === filter);
  }, [meals, filter]);

  const filters = [
    { key: 'all', label: t('common.all') },
    { key: 'cafe', label: t('nutrition.breakfast') },
    { key: 'almoco', label: t('nutrition.lunch') },
    { key: 'lanche', label: t('nutrition.snack') },
    { key: 'jantar', label: t('nutrition.dinner') },
  ];

  const totalCalories = useMemo(() => filtered.reduce((sum, m) => sum + (m.calories || 0), 0), [filtered]);

  if (loading) {
    return <View style={styles.loading}><Text style={styles.loadingText}>{t('common.loading')}</Text></View>;
  }

  return (
    <View style={styles.container}>
      <View style={styles.header}>
        <Text style={styles.title}>{t('nutrition.mealHistory')}</Text>
        <Text style={styles.total}>{t('nutrition.kcalTotal', { amount: totalCalories })}</Text>
      </View>

      <View style={styles.filterRow}>
        {filters.map(f => (
          <TouchableOpacity key={f.key} style={[styles.filterBtn, filter === f.key && styles.filterActive]} onPress={() => setFilter(f.key)}>
            <Text style={[styles.filterText, filter === f.key && styles.filterTextActive]}>{f.label}</Text>
          </TouchableOpacity>
        ))}
      </View>

      {filtered.length === 0 ? (
        <View style={styles.empty}>
          <Ionicons name="restaurant-outline" size={32} color={COLORS.textMuted} />
          <Text style={styles.emptyText}>{t('nutrition.noMeals')}</Text>
        </View>
      ) : (
        <FlatList
          removeClippedSubviews={true}
          maxToRenderPerBatch={10}
          windowSize={5}
          data={filtered}
          keyExtractor={(item, index) => item.id?.toString() || `meal-${index}`}
          renderItem={({ item }) => <MealItem meal={item} />}
          scrollEnabled={false}
          ItemSeparatorComponent={() => <View style={styles.separator} />}
        />
      )}
    </View>
  );
}

