// Relatórios de nutrição - NOVAIX FITNESS

import React, { useState, useEffect } from 'react';
import { View, Text, TouchableOpacity, StyleSheet, ScrollView } from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import * as Print from 'expo-print';
import * as Sharing from 'expo-sharing';
import { COLORS } from '../../constants/colors';
import { SPACING, BORDER_RADIUS } from '../../constants/spacing';
import { getMealLogs, getDailySummary } from '../../services/mealAnalyzer';
import { formatDateBR } from '../../helpers/dates';
import { useI18n } from '../../i18n';

const TITLE_KEYS = { daily: 'nutrition.reports.dailyShort', weekly: 'nutrition.reports.weeklyShort', monthly: 'nutrition.reports.monthlyShort' };

function generateReportHTML(type, data, t) {
  const title = t(TITLE_KEYS[type]);

  const mealsHTML = data.meals.map(m => `
    <tr>
      <td>${formatDateBR(m.logged_at)}</td>
      <td>${m.description || t('nutrition.mealDefault')}</td>
      <td>${m.calories || 0} kcal</td>
      <td>${m.protein || 0}g</td>
      <td>${m.carbs || 0}g</td>
      <td>${m.fat || 0}g</td>
    </tr>
  `).join('');

  return `
    <!DOCTYPE html>
    <html><head><meta charset="utf-8"><style>
      body { font-family: Arial, sans-serif; padding: 20px; color: #333; }
      h1 { color: #CCFF00; background: #12161A; padding: 15px; text-align: center; border-radius: 8px; }
      h2 { color: #12161A; margin-top: 20px; }
      .summary { background: #f8f9fa; padding: 15px; border-radius: 8px; margin-bottom: 20px; }
      .stat { display: inline-block; text-align: center; padding: 10px 20px; margin: 5px; background: white; border-radius: 8px; border: 1px solid #eee; }
      .statValue { font-size: 24px; font-weight: bold; color: #CCFF00; }
      .statLabel { font-size: 11px; color: #666; }
      table { width: 100%; border-collapse: collapse; margin-top: 10px; }
      th { background: #12161A; color: white; padding: 8px; text-align: left; font-size: 12px; }
      td { padding: 8px; border-bottom: 1px solid #eee; font-size: 12px; }
      .footer { text-align: center; color: #999; margin-top: 30px; font-size: 11px; }
    </style></head><body>
      <h1>📊 ${t('nutrition.reports.pdfTitle', { type: title.toUpperCase() })}</h1>
      <div class="summary">
        <div class="stat"><div class="statValue">${data.totalMeals}</div><div class="statLabel">${t('nutrition.meals')}</div></div>
        <div class="stat"><div class="statValue">${Math.round(data.totalCalories)}</div><div class="statLabel">${t('nutrition.reports.kcalTotal')}</div></div>
        <div class="stat"><div class="statValue">${Math.round(data.avgCalories)}</div><div class="statLabel">${t('nutrition.reports.kcalAvgDay')}</div></div>
        <div class="stat"><div class="statValue">${Math.round(data.avgProtein)}g</div><div class="statLabel">${t('nutrition.reports.avgProtein')}</div></div>
      </div>
      <h2>${t('nutrition.reports.mealDetails')}</h2>
      <table>
        <tr><th>${t('nutrition.reports.date')}</th><th>${t('nutrition.mealDefault')}</th><th>${t('nutrition.reports.caloriesHeader')}</th><th>${t('nutrition.protein')}</th><th>${t('nutrition.reports.carbsHeader')}</th><th>${t('nutrition.reports.fatHeader')}</th></tr>
        ${mealsHTML}
      </table>
      <p class="footer">${t('nutrition.reports.generatedBy')} • ${formatDateBR(new Date())}</p>
    </body></html>
  `;
}

export default function NutritionReports({ userId }) {
  const [loading, setLoading] = useState(false);
  const { t } = useI18n();

  const REPORT_TYPES = [
    { id: 'daily', title: t('nutrition.reports.daily'), icon: 'calendar', color: COLORS.primary, desc: t('nutrition.reports.dailyDesc') },
    { id: 'weekly', title: t('nutrition.reports.weekly'), icon: 'bar-chart', color: COLORS.success, desc: t('nutrition.reports.weeklyDesc') },
    { id: 'monthly', title: t('nutrition.reports.monthly'), icon: 'trending-up', color: COLORS.info, desc: t('nutrition.reports.monthlyDesc') },
  ];

  const generateReport = async (type) => {
    setLoading(true);
    try {
      const now = new Date();
      let startDate;

      if (type === 'daily') {
        startDate = new Date(now);
        startDate.setHours(0, 0, 0, 0);
      } else if (type === 'weekly') {
        startDate = new Date(now.getTime() - 7 * 86400000);
      } else {
        startDate = new Date(now.getTime() - 30 * 86400000);
      }

      const allLogs = await getMealLogs(userId);
      const filtered = allLogs.filter(l => new Date(l.logged_at) >= startDate);

      const data = {
        meals: filtered,
        totalMeals: filtered.length,
        totalCalories: filtered.reduce((s, m) => s + (m.calories || 0), 0),
        avgCalories: filtered.length > 0 ? filtered.reduce((s, m) => s + (m.calories || 0), 0) / (type === 'daily' ? 1 : type === 'weekly' ? 7 : 30) : 0,
        avgProtein: filtered.length > 0 ? filtered.reduce((s, m) => s + (m.protein || 0), 0) / (type === 'daily' ? 1 : type === 'weekly' ? 7 : 30) : 0,
      };

      const html = generateReportHTML(type, data, t);
      const { uri } = await Print.printToFileAsync({ html, base64: false });
      await Sharing.shareAsync(uri, { mimeType: 'application/pdf', dialogTitle: t('nutrition.reports.dialogTitle', { type }) });
    } catch (err) {
      if (__DEV__) console.error('Erro ao gerar relatório:', err);
    } finally {
      setLoading(false);
    }
  };

  return (
    <View style={styles.container}>
      <View style={styles.header}>
        <Ionicons name="document-text" size={18} color={COLORS.primary} />
        <Text style={styles.title}>{t('nutrition.reports.title')}</Text>
      </View>

      <View style={styles.list}>
        {REPORT_TYPES.map(report => (
          <TouchableOpacity key={report.id} accessibilityLabel={`Gerar ${report.title}`} accessibilityRole="button" style={styles.reportCard} onPress={() => generateReport(report.id)} disabled={loading}>
            <View style={[styles.reportIcon, { backgroundColor: report.color + '20' }]}>
              <Ionicons name={report.icon} size={20} color={report.color} />
            </View>
            <View style={styles.reportInfo}>
              <Text style={styles.reportTitle}>{report.title}</Text>
              <Text style={styles.reportDesc}>{report.desc}</Text>
            </View>
