      <View style={styles.inputContainer}>
        <TextInput
          style={styles.input}
          value={value}
          onChangeText={onChange}
          keyboardType="numeric"
          placeholder="--"
          placeholderTextColor={COLORS.textMuted}
        />
        <Text style={styles.inputUnit}>{measurement.unit}</Text>
      </View>
    </View>
  );
}

export default function ProgressPhotos({ userId }: { userId?: string }) {
  const { t } = useI18n();
  const [values, setValues] = useState<Record<string, string>>({});
  const [lastEntry, setLastEntry] = useState<Record<string, any> | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => { loadData(); }, [userId]);

  const loadData = async () => {
    if (!userId) { setLoading(false); return; }
    try {
      const { data } = await supabase.from('body_measurements')
        .select('*')
        .eq('user_id', userId)
        .order('recorded_at', { ascending: false })
        .limit(1)
        .single();
      if (data) {
        setLastEntry(data);
        setValues({
          weight: data.weight?.toString() || '',
          bodyFat: data.body_fat?.toString() || '',
          chest: data.chest?.toString() || '',
          waist: data.waist?.toString() || '',
          hip: data.hip?.toString() || '',
          arm: data.arm?.toString() || '',
        });
      }
    } catch (e) { if (__DEV__) console.warn('ProgressPhotos:', e); }
    finally { setLoading(false); }
  };

  const handleSave = async () => {
    const hasAny = Object.values(values).some(v => v && v.trim());
    if (!hasAny) {
      Alert.alert(t('common.error'), t('progress.fillMeasurementError'));
      return;
    }

    try {
      await supabase.from('body_measurements').insert({
        user_id: userId,
        weight: parseFloat(values.weight) || null,
        body_fat: parseFloat(values.bodyFat) || null,
        chest: parseFloat(values.chest) || null,
        waist: parseFloat(values.waist) || null,
        hip: parseFloat(values.hip) || null,
        arm: parseFloat(values.arm) || null,
        recorded_at: new Date().toISOString(),
      });
      Alert.alert(t('common.success'), t('progress.measurementSaved'));
      loadData();
    } catch (err) {
      Alert.alert(t('common.error'), t('progress.measurementSaveError'));
    }
  };

  const handleChange = (key, value) => {
    setValues(prev => ({ ...prev, [key]: value }));
  };

  return (
    <View style={styles.container}>
      <View style={styles.header}>
        <Ionicons name="fitness" size={18} color={COLORS.primary} />
        <Text style={styles.title}>MEDIDAS CORPORAIS</Text>
      </View>

      {lastEntry && (
        <View style={styles.lastEntry}>
          <Text style={styles.lastLabel}>Última medição: {new Date(lastEntry.recorded_at).toLocaleDateString('pt-BR')}</Text>
        </View>
      )}

      <View style={styles.inputsGrid}>
        {MEASUREMENTS.map(m => (
          <MeasurementInput
            key={m.key}
            measurement={m}
            value={values[m.key] || ''}
            onChange={(v) => handleChange(m.key, v)}
          />
        ))}
      </View>

      <TouchableOpacity style={styles.saveBtn} onPress={handleSave}>
        <Ionicons name="checkmark-circle" size={18} color={COLORS.background} />
        <Text style={styles.saveText}>SALVAR MEDIDAS</Text>
      </TouchableOpacity>
    </View>
  );
}

