        <Ionicons name={saved ? 'checkmark-circle' : 'save'} size={18} color={COLORS.background} />
        <Text style={styles.saveText}>{saved ? t('nutrition.sleep.saved') : t('nutrition.sleep.register')}</Text>
      </TouchableOpacity>
    </View>
  );
