// Slider de régua física com feedback tátil e visual premium - NOVAIX FITNESS

import { useState, useRef, useMemo } from 'react';
import { View, Text, TouchableOpacity, TextInput, PanResponder, Animated, StyleSheet } from 'react-native';
import { COLORS } from '../../constants/colors';
import { SPACING, BORDER_RADIUS } from '../../constants/spacing';
import { typography } from '../../styles';
import * as Haptics from 'expo-haptics';

interface DraggableSliderProps {
  label: string;
  value: number;
  setValue: (val: number) => void;
  min: number;
  max: number;
  unit: string;
}

export default function DraggableSlider({ label, value, setValue, min, max, unit }: DraggableSliderProps) {
  const [editing, setEditing] = useState(false);
  const [editText, setEditText] = useState(String(value));
  const trackWidth = useRef(260);

  const pct = (value - min) / (max - min);
  const thumbLeft = `${pct * 100}%`;

  // Controlar vibracao sutil ao mudar os valores (feedback tatil)
  const lastValueRef = useRef(value);

  const panResponder = useMemo(() => PanResponder.create({
    onMoveShouldSetPanResponder: () => true,
    onPanResponderGrant: () => {},
    onPanResponderMove: (_, gesture) => {
      const width = trackWidth.current;
      const dx = gesture.dx;
      const ratio = Math.max(0, Math.min(1, (pct * width + dx) / width));
      const newVal = Math.round(min + ratio * (max - min));
      const boundedVal = Math.max(min, Math.min(max, newVal));

      setValue(boundedVal);

      // Trigger haptic feedback when value changes (rounded to units)
      if (boundedVal !== lastValueRef.current) {
        lastValueRef.current = boundedVal;
        try {
          Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
        } catch {}
      }
    },
    onPanResponderRelease: () => {},
  }), [pct, min, max, setValue]);

  const commitEdit = () => {
    const cleaned = editText.replace(/\D/g, '');
    const num = parseInt(cleaned, 10);
    if (!isNaN(num) && num >= min && num <= max) {
      setValue(num);
      setEditText(String(num));
    }
    setEditing(false);
  };

  // Gerar linhas de escala da régua baseadas em porcentagem
  const ticksCount = 20;

  return (
    <View style={styles.card}>
      <View style={styles.header}>
        <Text style={styles.label}>{label}</Text>
        {editing ? (
          <TextInput
            style={styles.input}
            value={editText}
            onChangeText={setEditText}
            keyboardType="numeric"
            autoFocus
            onBlur={commitEdit}
            onSubmitEditing={commitEdit}
          />
        ) : (
          <TouchableOpacity onPress={() => { setEditText(String(value)); setEditing(true); }}>
            <Text style={styles.valueText}>{value} {unit}</Text>
          </TouchableOpacity>
        )}
      </View>

      {/* Régua de marcações */}
      <View style={styles.trackRow} onLayout={(e) => { trackWidth.current = e.nativeEvent.layout.width; }}>
        <View style={styles.track}>
          {/* Fundo com marcadores de régua física */}
          <View style={styles.ticksContainer}>
            {Array.from({ length: ticksCount }).map((_, i) => {
              const tickPct = i / (ticksCount - 1);
              const isActive = tickPct <= pct;
              return (
                <View 
                  key={i} 
                  style={[
                    styles.tickLine, 
                    isActive && styles.tickLineActive,
                    i % 5 === 0 && styles.tickLineMajor
                  ]} 
                />
              );
            })}
          </View>
          <View style={[styles.fill, { width: `${pct * 100}%` }]} />
        </View>
        <Animated.View style={[styles.thumb, { left: thumbLeft as any }]} {...panResponder.panHandlers}>
          <View style={styles.thumbDot} />
        </Animated.View>
      </View>

      <View style={styles.labels}>
        <Text style={styles.labelText}>{min}{unit}</Text>
        <Text style={styles.labelText}>{max}{unit}</Text>
      </View>
    </View>
  );
}

const styles = StyleSheet.create({
  card: { 
    padding: SPACING.lg, 
    backgroundColor: 'rgba(30, 35, 42, 0.85)', 
    borderRadius: BORDER_RADIUS.lg, 
    borderWidth: 1, 
