  },
  trackRow: { height: 44, justifyContent: 'center', position: 'relative' },
  track: { height: 16, backgroundColor: COLORS.surfaceOverlay, borderRadius: 8, overflow: 'hidden', justifyContent: 'center', position: 'relative' },
  fill: { height: '100%', backgroundColor: COLORS.primary + '20', position: 'absolute', left: 0, top: 0, borderRadius: 8 },
