import { View, Text, TouchableOpacity, ScrollView, StyleSheet, Animated, Image } from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import { Avatar } from '../ui/Avatar';
import { COLORS } from '../../constants/colors';
import { SPACING, BORDER_RADIUS, ICON_SIZES } from '../../constants/spacing';
import { scale } from '../../utils/responsive';
import { getXPProgress } from '../../constants/gamification';
import { useI18n } from '../../i18n';

const STAT_DEFS = [
  { key: 'streak', icon: 'flame', color: COLORS.secondary, labelKey: 'profile.stats.streak', unit: 'd' },
  { key: 'workouts', icon: 'barbell', color: COLORS.primary, labelKey: 'profile.stats.workouts', unit: '' },
  { key: 'time', icon: 'time-outline', color: COLORS.info, labelKey: 'profile.stats.hours', unit: 'h' },
  { key: 'favorites', icon: 'heart', color: COLORS.error, labelKey: 'profile.stats.favorites', unit: '' },
];

function StatChip({ icon, color, label, value, unit }) {
  return (
    <View style={styles.chip}>
      <View style={[styles.chipIcon, { backgroundColor: color + '22' }]}>
        <Ionicons name={icon} size={ICON_SIZES.sm} color={color} />
      </View>
      <Text style={styles.chipValue}>{value}<Text style={styles.chipUnit}>{unit}</Text></Text>
      <Text style={styles.chipLabel}>{label}</Text>
    </View>
  );
}

function ProfileHero({ name, email, memberSince, uri, onPressAvatar, onEditName, stats, xp = 0 }) {
  const { t } = useI18n();
  const { current, progress } = getXPProgress(xp);
  const fadeAnim = useMemo(() => new Animated.Value(0), []);

  useEffect(() => {
    Animated.timing(fadeAnim, { toValue: 1, duration: 400, useNativeDriver: true }).start();
  }, []);

  return (
    <Animated.View style={[styles.container, { opacity: fadeAnim }]}>
      {/* Cover image */}
      <View style={styles.coverContainer}>
        <Image
          source={{ uri: 'https://images.unsplash.com/photo-1517838277536-f5f99be501cd?q=80&w=600' }}
          style={styles.coverImage}
          resizeMode="cover"
        />
        <TouchableOpacity style={styles.editCoverBtn} onPress={() => {}}>
          <Ionicons name="camera" size={16} color={COLORS.textTitle} />
        </TouchableOpacity>
      </View>

      {/* Avatar + nome */}
      <View style={styles.profileMetaWrap}>
        <TouchableOpacity style={styles.avatarWrap} onPress={onPressAvatar} activeOpacity={0.8}>
          <Avatar name={name} uri={uri} size="xl" />
          <View style={styles.editAvatar}>
            <Ionicons name="camera" size={12} color={COLORS.background} />
          </View>
        </TouchableOpacity>

        <View style={styles.infoCentered}>
          <View style={styles.nameCenteredRow}>
            <Text style={styles.nameCentered} numberOfLines={1}>{name}</Text>
            <TouchableOpacity onPress={onEditName} style={styles.editBtn}>
              <Ionicons name="create-outline" size={16} color={COLORS.primary} />
            </TouchableOpacity>
          </View>
          <Text style={styles.emailCentered} numberOfLines={1}>{email}</Text>
          <Text style={styles.memberCentered}>{t('profile.memberSince', { date: memberSince })}</Text>

          {/* Level badge + XP bar */}
          <View style={styles.levelRow}>
            <View style={[styles.levelBadge, { backgroundColor: current.color + '22' }]}>
              <Ionicons name={current.icon} size={12} color={current.color} />
              <Text style={[styles.levelText, { color: current.color }]}>Nv.{current.level} {current.name}</Text>
            </View>
            <Text style={styles.xpText}>{xp} XP</Text>
          </View>
          <View style={styles.xpTrack}>
            <View style={[styles.xpFill, { width: `${Math.max(progress * 100, 3)}%`, backgroundColor: current.color }]} />
          </View>
        </View>
      </View>

      {/* Stats horizontais */}
      <ScrollView horizontal showsHorizontalScrollIndicator={false} style={styles.statsRow} contentContainerStyle={styles.statsContent}>
        {STAT_DEFS.map((s) => (
          <StatChip key={s.key} icon={s.icon} color={s.color} label={t(s.labelKey)} value={stats?.[s.key] ?? 0} unit={s.unit} />
        ))}
        <StatChip icon="star" color={COLORS.attention} label={t('profile.stats.xpTotal')} value={xp} unit=" pts" />
      </ScrollView>
    </Animated.View>
  );
}

export default memo(ProfileHero);

