import React, { useRef, useEffect } from 'react';
import { View, Text, TouchableOpacity, Dimensions, StyleSheet, Animated } from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import { LineChart } from 'react-native-chart-kit';
import { COLORS } from '../../constants/colors';
import { SPACING, BORDER_RADIUS } from '../../constants/spacing';
import { SHADOWS } from '../../constants/shadows';

const { width: SCREEN_WIDTH } = Dimensions.get('window');

const MEASUREMENT_TYPES = [
  { key: 'weight', label: 'Peso', icon: 'scale', unit: 'kg', color: COLORS.primary },
  { key: 'bodyFat', label: 'Gordura', icon: 'water', unit: '%', color: COLORS.secondary },
  { key: 'chest', label: 'Peito', icon: 'body', unit: 'cm', color: COLORS.success },
  { key: 'waist', label: 'Cintura', icon: 'resize', unit: 'cm', color: COLORS.attention },
  { key: 'hip', label: 'Quadril', icon: 'body', unit: 'cm', color: COLORS.info },
  { key: 'arm', label: 'Braco', icon: 'barbell', unit: 'cm', color: COLORS.purple },
];

interface MeasurementChartProps {
  selectedChart: string;
  onSelectChart: (chart: string) => void;
  chartData: { date: string; value: number }[];
}

export default function MeasurementChart({ selectedChart, onSelectChart, chartData }: MeasurementChartProps) {
  const fadeAnim = useMemo(() => new Animated.Value(0), []);
  const slideAnim = useMemo(() => new Animated.Value(10), []);

  useEffect(() => {
    Animated.parallel([
      Animated.timing(fadeAnim, { toValue: 1, duration: 300, useNativeDriver: true }),
      Animated.spring(slideAnim, { toValue: 0, friction: 8, useNativeDriver: true }),
    ]).start();
  }, [selectedChart]);

  const selectedType = MEASUREMENT_TYPES.find(m => m.key === selectedChart);
  const chartColor = selectedType?.color || COLORS.primary;

  const chartConfig = {
    backgroundColor: COLORS.surface,
    backgroundGradientFrom: COLORS.surface,
    backgroundGradientTo: COLORS.surface,
    decimalPlaces: 1,
    color: (opacity = 1) => `${chartColor}${Math.round(opacity * 255).toString(16).padStart(2, '0')}`,
    labelColor: () => COLORS.textMuted,
    style: { borderRadius: BORDER_RADIUS.md },
    propsForDots: { r: '5', strokeWidth: '2', stroke: chartColor },
    propsForBackgroundLines: { strokeDasharray: '', stroke: COLORS.border },
  };

  return (
    <Animated.View style={[styles.container, { opacity: fadeAnim, transform: [{ translateY: slideAnim }] }]}>
      {/* Seletor de tipo */}
      <View style={styles.selector}>
        {MEASUREMENT_TYPES.map((m) => {
          const isSelected = selectedChart === m.key;
          return (
            <TouchableOpacity
              key={m.key}
              style={[styles.btn, isSelected && { backgroundColor: m.color, borderColor: m.color }]}
              onPress={() => onSelectChart(m.key)}
            >
              <Ionicons name={m.icon} size={14} color={isSelected ? COLORS.background : COLORS.textMuted} />
              <Text style={[styles.btnText, isSelected && styles.btnTextActive]}>{m.label}</Text>
            </TouchableOpacity>
          );
        })}
      </View>

      {/* Grafico */}
      {chartData && chartData.length > 1 ? (
        <View style={styles.chartCard}>
          <View style={styles.chartHeader}>
            <Text style={styles.chartTitle}>{selectedType?.label || 'Medidas'}</Text>
            <Text style={styles.chartSubtitle}>Ultimos registros</Text>
          </View>
          <LineChart
            data={{
              labels: chartData.map(d => d.date),
              datasets: [{ data: chartData.map(d => d.value) }],
            }}
            width={SCREEN_WIDTH - 80}
            height={200}
            chartConfig={chartConfig}
            bezier
            fromZero
            style={styles.chart}
          />
          {/* Resumo */}
          <View style={styles.summaryRow}>
            <View style={styles.summaryItem}>
              <Text style={styles.summaryLabel}>Atual</Text>
              <Text style={[styles.summaryValue, { color: chartColor }]}>
                {chartData[chartData.length - 1]?.value || 0} {selectedType?.unit}
              </Text>
            </View>
            <View style={styles.summaryDivider} />
            <View style={styles.summaryItem}>
              <Text style={styles.summaryLabel}>Anterior</Text>
              <Text style={styles.summaryValue}>
                {chartData[chartData.length - 2]?.value || 0} {selectedType?.unit}
              </Text>
            </View>
            <View style={styles.summaryDivider} />
            <View style={styles.summaryItem}>
              <Text style={styles.summaryLabel}>Mudanca</Text>
              <Text style={[styles.summaryValue, { color: chartData[chartData.length - 1]?.value > chartData[chartData.length - 2]?.value ? COLORS.success : COLORS.error }]}>
                {((chartData[chartData.length - 1]?.value || 0) - (chartData[chartData.length - 2]?.value || 0)).toFixed(1)} {selectedType?.unit}
              </Text>
            </View>
          </View>
        </View>
      ) : (
        <View style={styles.emptyChart}>
          <Ionicons name="analytics-outline" size={48} color={COLORS.textMuted} />
          <Text style={styles.emptyTitle}>Sem dados suficientes</Text>
          <Text style={styles.emptyText}>Registre mais medidas para ver o grafico</Text>
        </View>
      )}
    </Animated.View>
  );
}

const styles = StyleSheet.create({
  container: { marginBottom: SPACING.lg },

  // Seletor
  selector: { flexDirection: 'row', flexWrap: 'wrap', gap: SPACING.xs, marginBottom: SPACING.md },
  btn: { flexDirection: 'row', alignItems: 'center', gap: 4, paddingHorizontal: SPACING.md, paddingVertical: SPACING.xs, backgroundColor: COLORS.surface, borderRadius: BORDER_RADIUS.full, borderWidth: 1, borderColor: COLORS.border },
  btnText: { fontFamily: 'Montserrat_600SemiBold', fontSize: 11, color: COLORS.textMuted },
  btnTextActive: { color: COLORS.background },

  // Grafico
  chartCard: { backgroundColor: COLORS.surface, borderRadius: BORDER_RADIUS.lg, padding: SPACING.lg, borderWidth: 1, borderColor: COLORS.border, ...SHADOWS.sm },
  chartHeader: { marginBottom: SPACING.md },
  chartTitle: { fontFamily: 'Montserrat_700Bold', fontSize: 16, color: COLORS.textTitle },
  chartSubtitle: { fontFamily: 'Inter_400Regular', fontSize: 12, color: COLORS.textMuted },
  chart: { borderRadius: BORDER_RADIUS.md },

  // Resumo
  summaryRow: { flexDirection: 'row', justifyContent: 'space-around', marginTop: SPACING.md, paddingTop: SPACING.md, borderTopWidth: 1, borderTopColor: COLORS.border },
  summaryItem: { alignItems: 'center' },
  summaryLabel: { fontFamily: 'Inter_400Regular', fontSize: 11, color: COLORS.textMuted },
  summaryValue: { fontFamily: 'Montserrat_700Bold', fontSize: 14, color: COLORS.textTitle, marginTop: 2 },

  // Empty
  emptyChart: { alignItems: 'center', paddingVertical: SPACING.xxl, backgroundColor: COLORS.surface, borderRadius: BORDER_RADIUS.lg, borderWidth: 1, borderColor: COLORS.border },
  emptyTitle: { fontFamily: 'Montserrat_600SemiBold', fontSize: 14, color: COLORS.textTitle, marginTop: SPACING.md },
  emptyText: { fontFamily: 'Inter_400Regular', fontSize: 12, color: COLORS.textMuted, marginTop: SPACING.xs },
});

