}

export default function MeasurementForm({ form, onChangeForm, onSave, saving }) {
  const { t } = useI18n();
  const fadeAnim = useMemo(() => new Animated.Value(0), []);

  useEffect(() => {
    Animated.timing(fadeAnim, { toValue: 1, duration: 300, useNativeDriver: true }).start();
