import React from 'react';
import { View, Text, ScrollView, TouchableOpacity, Image, StyleSheet, Dimensions } from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import { COLORS } from '../../constants/colors';
import { SPACING, BORDER_RADIUS } from '../../constants/spacing';
import { typography } from '../../styles';
import { useI18n } from '../../i18n';
import ProgressHero from '../progress/ProgressHero';
import ProgressStats from '../progress/ProgressStats';
import MeasurementTrends from '../progress/MeasurementTrends';

const { width: SCREEN_WIDTH } = Dimensions.get('window');
const PHOTO_THUMB = (SCREEN_WIDTH - SPACING.xl * 2 - SPACING.sm * 4) / 5;

export default function ProgressOverview({ photos, measurements, latest, previous, onNavigate }) {
  const { t } = useI18n();
  const weightChange = latest?.weight && previous?.weight ? latest.weight - previous.weight : null;
  const firstPhoto = photos.length > 0 ? photos[photos.length - 1] : null;
  const lastPhoto = photos.length > 0 ? photos[0] : null;
  const now = Date.now();
  const daysTracked = measurements.length > 0 ? Math.ceil((now - new Date(measurements[measurements.length - 1]?.recorded_at).getTime()) / 86400000) + 1 : 0;
  const recentPhotos = photos.slice(0, 5);

  return (
    <View>
      <ProgressHero beforePhoto={firstPhoto} afterPhoto={lastPhoto} weightChange={weightChange} />
      <ProgressStats weightChange={weightChange} measurementsCount={measurements.length} photosCount={photos.length} daysTracked={daysTracked} />

      <View style={styles.section}>
        <Text style={typography.label}>{t('progress.recentPhotos')}</Text>
        {recentPhotos.length > 0 ? (
          <ScrollView horizontal showsHorizontalScrollIndicator={false} style={styles.photosScroll}>
            {recentPhotos.map((photo) => (
              <TouchableOpacity key={photo.id} onPress={() => onNavigate('photos')}>
                <Image source={{ uri: photo.image_url }} style={styles.photoThumb} />
              </TouchableOpacity>
            ))}
          </ScrollView>
        ) : (
          <TouchableOpacity style={styles.emptyPhotos} onPress={() => onNavigate('photos')}>
            <Ionicons name="camera-outline" size={32} color={COLORS.textMuted} />
            <Text style={styles.emptyPhotosText}>{t('progress.noPhotosYet')}</Text>
            <Text style={styles.emptyPhotosCta}>{t('progress.addFirstPhoto')}</Text>
          </TouchableOpacity>
        )}
      </View>

      <MeasurementTrends latest={latest} previous={previous} />
    </View>
  );
}

const styles = StyleSheet.create({
  section: { marginBottom: SPACING.xl },
  photosScroll: { marginTop: SPACING.md },
  photoThumb: { width: PHOTO_THUMB, height: PHOTO_THUMB * 1.33, borderRadius: 8, marginRight: SPACING.sm, backgroundColor: COLORS.surfaceOverlay },
  emptyPhotos: { backgroundColor: COLORS.surface, borderRadius: BORDER_RADIUS.lg, padding: SPACING.xl, alignItems: 'center', borderWidth: 1, borderColor: COLORS.border, borderStyle: 'dashed', marginTop: SPACING.md, gap: SPACING.xs },
  emptyPhotosText: { fontFamily: 'Montserrat_600SemiBold', fontSize: 13, color: COLORS.textMuted },
  emptyPhotosCta: { fontFamily: 'Inter_400Regular', fontSize: 12, color: COLORS.textDescription },
});

import React, { useState, useEffect } from 'react';
import { View, Text, TouchableOpacity, Alert, StyleSheet, Dimensions } from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import { COLORS } from '../../constants/colors';
import { SPACING, BORDER_RADIUS } from '../../constants/spacing';
import { typography } from '../../styles';
import { CompareView, PhotoGrid, PhotoModal, PhotoPicker } from '../index';
import { pickImage, takePhoto, uploadProgressPhoto, getProgressPhotos, deleteProgressPhoto, PHOTO_LABELS } from '../../services/progress-photos';
import { useI18n } from '../../i18n';

const { width: SCREEN_WIDTH } = Dimensions.get('window');

export default function ProgressPhotos({ userId }) {
  const { t } = useI18n();
  const [photos, setPhotos] = useState([]);
  const [selectedLabel, setSelectedLabel] = useState('Frente');
  const [showPicker, setShowPicker] = useState(false);
  const [loading, setLoading] = useState(true);
  const [selectedPhoto, setSelectedPhoto] = useState(null);
  const [compareMode, setCompareMode] = useState(false);
  const [comparePhotos, setComparePhotos] = useState([]);

  const loadPhotos = async () => {
    if (!userId) return;
    try {
      const data = await getProgressPhotos(userId);
      setPhotos(data);
    } catch (err) {
      if (__DEV__) console.error('Erro ao carregar fotos:', err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => { loadPhotos(); }, [userId]);

  const handlePickImage = async (useCamera) => {
    try {
      const image = useCamera ? await takePhoto() : await pickImage();
      if (!image) return;
      await uploadProgressPhoto(userId, image.uri, selectedLabel);
      Alert.alert(t('common.success'), t('progress.photo.photoSaved'));
      await loadPhotos();
    } catch (err) {
      Alert.alert(t('common.error'), err.message || t('progress.photo.saveError'));
    } finally {
      setShowPicker(false);
    }
  };

  const handleDelete = (photo) => {
    Alert.alert(t('progress.photo.deleteTitle'), t('progress.photo.deleteConfirm'), [
      { text: t('common.cancel'), style: 'cancel' },
      { text: t('common.delete'), style: 'destructive', onPress: async () => {
        await deleteProgressPhoto(photo.id, userId, photo.storage_path);
        await loadPhotos();
      }},
    ]);
  };

  const toggleCompare = (photo) => {
    if (!compareMode) {
      setCompareMode(true);
      setComparePhotos([photo]);
    } else {
      setComparePhotos(comparePhotos.length >= 2 ? [photo] : [...comparePhotos, photo]);
    }
  };

  const filteredPhotos = photos.filter(p => p.label === selectedLabel);
  const labels = [...new Set(photos.map(p => p.label))];
  const allLabels = [...new Set([...PHOTO_LABELS, ...labels])];

  return (
    <View>
      <View style={styles.header}>
        <Text style={typography.label}>{t('progress.photosTitle')}</Text>
        <TouchableOpacity onPress={() => setShowPicker(true)}>
          <Ionicons name="camera" size={24} color={COLORS.primary} />
        </TouchableOpacity>
      </View>

      <ScrollView horizontal showsHorizontalScrollIndicator={false} style={styles.labelsScroll}>
        <View style={styles.labelsRow}>
          {allLabels.map((label) => (
            <TouchableOpacity
              key={label}
              style={[styles.labelChip, selectedLabel === label && styles.labelActive]}
              onPress={() => setSelectedLabel(label)}
            >
              <Text style={[styles.labelText, selectedLabel === label && styles.labelTextActive]}>{label}</Text>
            </TouchableOpacity>
          ))}
        </View>
      </ScrollView>

      {compareMode && comparePhotos.length >= 2 && (
        <CompareView photos={comparePhotos} onCancel={() => { setCompareMode(false); setComparePhotos([]); }} />
      )}

      <PhotoGrid
        photos={filteredPhotos}
        selectedIds={comparePhotos}
        onSelect={(p) => compareMode ? toggleCompare(p) : setSelectedPhoto(p)}
        onLongPress={handleDelete}
        compareMode={compareMode}
      />

      {filteredPhotos.length >= 2 && !compareMode && (
        <TouchableOpacity style={styles.compareBtn} onPress={() => setCompareMode(true)}>
          <Ionicons name="swap-horizontal" size={20} color={COLORS.primary} />
          <Text style={styles.compareText}>{t('progress.photo.compare')}</Text>
        </TouchableOpacity>
      )}

      <PhotoModal photo={selectedPhoto} onCompare={toggleCompare} onDelete={handleDelete} onClose={() => setSelectedPhoto(null)} />
      {showPicker && (
        <PhotoPicker
          selectedLabel={selectedLabel}
          onSelectLabel={setSelectedLabel}
          onCamera={() => handlePickImage(true)}
          onGallery={() => handlePickImage(false)}
          onClose={() => setShowPicker(false)}
        />
      )}
    </View>
  );
}

const ScrollView = require('react-native').ScrollView;

const styles = StyleSheet.create({
  header: { flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center', marginBottom: SPACING.md },
  labelsScroll: { marginBottom: SPACING.xl },
  labelsRow: { flexDirection: 'row', gap: SPACING.xs },
  labelChip: { paddingHorizontal: SPACING.md, paddingVertical: SPACING.xs, backgroundColor: COLORS.surface, borderRadius: 999, borderWidth: 1, borderColor: COLORS.border },
  labelActive: { backgroundColor: COLORS.primary, borderColor: COLORS.primary },
  labelText: { fontFamily: 'Inter_400Regular', fontSize: 12, color: COLORS.textMuted },
  labelTextActive: { color: COLORS.background, fontFamily: 'Montserrat_600SemiBold' },
  compareBtn: { flexDirection: 'row', alignItems: 'center', justifyContent: 'center', gap: SPACING.sm, backgroundColor: COLORS.surface, borderRadius: 8, padding: SPACING.md, borderWidth: 1, borderColor: COLORS.border, marginTop: SPACING.lg },
  compareText: { fontFamily: 'Montserrat_600SemiBold', fontSize: 14, color: COLORS.primary },
});

