export default function OfflineSettings() {
  const { t } = useI18n();
  const { isOnline } = useNetworkStatus();
  const [info, setInfo] = useState(null);
  const [lastSync, setLastSync] = useState(null);
  const [pendingCount, setPendingCount] = useState(0);
  const [syncing, setSyncing] = useState(false);

  const loadInfo = async () => {
    const [cacheData, syncTime, pending] = await Promise.all([getCacheInfo(), getLastSync(), getPendingActions()]);
    setInfo(cacheData);
    setLastSync(syncTime);
    setPendingCount(pending.length);
  };

  useEffect(() => { loadInfo(); }, []);

  const onForceSync = () => handleForceSync(isOnline, setSyncing, loadInfo);
  const onClearWorkouts = () => promptClearWorkouts(loadInfo);
  const onClearAll = () => promptClearAll(loadInfo);

  return (
    <View style={styles.container}>
      <View style={styles.header}>
        <Ionicons name="cloud-offline-outline" size={18} color={COLORS.primary} />
        <Text style={styles.title}>{t('offline.title')}</Text>
