          </View>

          {Object.entries(info.breakdown).map(([key, data]) => (
            <View key={key} style={styles.itemRow}>
              <Text style={styles.itemLabel}>{key}</Text>
              <Text style={styles.itemValue}>{formatSize(data.size)}</Text>
