          <View style={styles.actions}>
            <TouchableOpacity style={[styles.btn, styles.btnSync, (!isOnline || syncing) && styles.btnDisabled]} onPress={onForceSync} disabled={!isOnline || syncing}>
              <Ionicons name="sync" size={16} color={COLORS.primary} />
              <Text style={styles.btnTextSync}>{syncing ? t('offline.syncing') : t('offline.sync')}</Text>
            </TouchableOpacity>
            <TouchableOpacity style={styles.btn} onPress={onClearWorkouts}>
              <Ionicons name="fitness-outline" size={16} color={COLORS.attention} />
              <Text style={styles.btnText}>{t('offline.clearWorkouts')}</Text>
