              <Ionicons name="trash-outline" size={16} color={COLORS.error} />
              <Text style={[styles.btnText, styles.btnDangerText]}>{t('offline.clearAll')}</Text>
            </TouchableOpacity>
          </View>
        </>
      )}
    </View>
  );
}

