  sliderHandle: {
    position: 'absolute', top: '50%', width: 28, height: 28, borderRadius: 14,
    backgroundColor: COLORS.primary, borderWidth: 2, borderColor: COLORS.textTitle,
    marginTop: -14, marginLeft: -13,
  },
});

