            <View style={styles.statItem}>
              <Ionicons name="people" size={16} color={COLORS.textMuted} />
              <Text style={styles.statText}>{challenge.participants || 0}</Text>
            </View>
          </View>

          <View style={styles.progressSection}>
            <View style={styles.progressHeader}>
