// @ts-nocheck
import { useState, useEffect, memo } from 'react';
import { View, Text, ScrollView, StyleSheet } from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import { COLORS } from '../../constants/colors';
import { SPACING, BORDER_RADIUS } from '../../constants/spacing';
import { supabase } from '../../config/supabase';
import { getNutritionContent } from '../../services/nutritionContent';
import { useMountedRef } from '../../hooks/useMountedRef';
import { useI18n } from '../../i18n';
import * as Haptics from 'expo-haptics';
import ChallengeModal from './ChallengeModal';
import ChallengeCard from './ChallengeCard';

export default memo(function ChallengesList({ userId }: { userId: string }) {
  const { t } = useI18n();
  const [challenges, setChallenges] = useState([]);
  const [loading, setLoading] = useState(true);
  const [selectedChallenge, setSelectedChallenge] = useState(null);
  const mounted = useMountedRef();

  useEffect(() => { loadChallenges(); }, [userId]);

  const loadChallenges = async () => {
    try {
      const content = await getNutritionContent();
      const weekChallenges = (content?.challenges || []).slice(0, 5);
      if (userId) {
        const { data: logs } = await supabase
          .from('daily_challenges')
          .select('challenge_id, completed')
          .eq('user_id', userId)
          .gte('created_at', new Date(Date.now() - 7 * 86400000).toISOString());
        const logMap = {};
        (logs || []).forEach(l => { logMap[l.challenge_id] = l.completed; });
        weekChallenges = weekChallenges.map(c => ({ ...c, progress: logMap[c.id] ? 1 : 0 }));
      }
      if (!mounted.current) return;
      setChallenges(weekChallenges);
    } catch (err) { if (__DEV__) console.error('Erro ao carregar desafios:', err); }
    finally { if (mounted.current) setLoading(false); }
  };

  const handleComplete = async (challenge) => {
    if (!userId) return;
    try {
      await supabase.from('daily_challenges').insert({ user_id: userId, challenge_id: challenge.id, completed: true });
      try { Haptics.notificationAsync(Haptics.NotificationFeedbackType.Success); } catch {}
      setChallenges(prev => prev.map(c => c.id === challenge.id ? { ...c, progress: 1 } : c));
    } catch (err) { if (__DEV__) console.error('Erro ao completar desafio:', err); }
  };

  const handleShare = async (challenge) => {
    try {
      const { Share } = require('react-native');
      await Share.share({ message: t('social.challengeShareMessage', { title: challenge.title, xp: challenge.reward }) });
    } catch (e) { if (__DEV__) console.warn('ChallengesList:', e); }
  };

  if (loading || challenges.length === 0) return null;

  return (
    <View style={styles.container}>
      <View style={styles.header}>
        <Ionicons name="trophy" size={18} color={COLORS.primary} />
        <Text style={styles.title}>{t('social.weeklyChallenges')}</Text>
      </View>
      <ScrollView horizontal showsHorizontalScrollIndicator={false}>
        {challenges.map((c, i) => (
          <ChallengeCard key={c.id || i} challenge={c} index={i} onPress={setSelectedChallenge} onShare={handleShare} />
        ))}
      </ScrollView>
      <ChallengeModal visible={!!selectedChallenge} challenge={selectedChallenge} onComplete={handleComplete} onClose={() => setSelectedChallenge(null)} />
    </View>
  );
});

const styles = StyleSheet.create({
  container: { marginBottom: SPACING.lg },
  header: { flexDirection: 'row', alignItems: 'center', gap: SPACING.sm, marginBottom: SPACING.md, paddingHorizontal: SPACING.xl },
  title: { fontFamily: 'Montserrat_700Bold', fontSize: 12, color: COLORS.textMuted, letterSpacing: 1 },
});

