// @ts-nocheck
// src/components/social/CreatePostModal.js
// Modal de criação de post com suporte a tipos, filtros e before/after

import { useState } from 'react';
import { View, Text, TextInput, TouchableOpacity, Modal, Image, StyleSheet, Alert, ActivityIndicator, ScrollView } from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import * as ImagePicker from 'expo-image-picker';
import { COLORS } from '../../constants/colors';
import { supabase } from '../../config/supabase';
import { styles } from './createPostModalStyles';
import { moderateText, moderateImage } from '../../services/contentModeration';
import { Button } from '../ui/Button';
import PostTypeSelector from './PostTypeSelector';
import PhotoFilterPicker from './PhotoFilterPicker';
import ImageViewer from './ImageViewer';
import ImagePickerBar from './ImagePickerBar';
import { useI18n } from '../../i18n';

export default function CreatePostModal({ visible, onClose, onSubmit, userId }) {
  const { t } = useI18n();
  const [content, setContent] = useState('');
  const [imageUri, setImageUri] = useState(null);
  const [secondImageUri, setSecondImageUri] = useState(null);
  const [postType, setPostType] = useState('text');
  const [selectedFilter, setSelectedFilter] = useState('none');
  const [uploading, setUploading] = useState(false);
  const [loading, setLoading] = useState(false);
  const [selectedFeeling, setSelectedFeeling] = useState<string | null>(null);
  const [selectedLocation, setSelectedLocation] = useState<string | null>(null);
  const [selectedWorkout, setSelectedWorkout] = useState<string | null>(null);

  const handlePickImage = async (isSecond = false) => {
    const { status } = await ImagePicker.requestMediaLibraryPermissionsAsync();
    if (status !== 'granted') {
      Alert.alert(t('social.createPost.permissionTitle'), t('social.createPost.galleryPermission'));
      return;
    }
    const result = await ImagePicker.launchImageLibraryAsync({
      mediaTypes: ImagePicker.MediaTypeOptions.All,
      allowsEditing: true,
      aspect: postType === 'before_after' ? [4, 5] : [4, 3],
      quality: 0.8,
    });
    if (!result.canceled) {
      const asset = result.assets[0];
      const isVideo = asset.type === 'video' || asset.uri.endsWith('.mp4') || asset.uri.endsWith('.mov');
      if (isVideo) {
        setPostType('video');
      }
      if (isSecond) {
        setSecondImageUri(asset.uri);
      } else {
        setImageUri(asset.uri);
      }
    }
  };

  const handleTakePhoto = async () => {
    const { status } = await ImagePicker.requestCameraPermissionsAsync();
    if (status !== 'granted') {
      Alert.alert(t('social.createPost.permissionTitle'), t('social.createPost.cameraPermission'));
      return;
    }
    const result = await ImagePicker.launchCameraAsync({
      allowsEditing: true,
      aspect: [4, 3],
      quality: 0.8,
    });
    if (!result.canceled) {
      setImageUri(result.assets[0].uri);
    }
  };

  const uploadImage = async (uri) => {
    if (!uri) return null;
    const isVideo = uri.endsWith('.mp4') || uri.endsWith('.mov') || postType === 'video';
    const ext = isVideo ? 'mp4' : 'jpg';
    const contentType = isVideo ? 'video/mp4' : 'image/jpeg';
    const fileName = `${userId}/posts/${Date.now()}_${Math.random().toString(36).slice(2)}.${ext}`;
    const formData = new FormData();
    formData.append('file', { uri, type: contentType, name: fileName } as any);
    const { error } = await supabase.storage.from('posts').upload(fileName, formData, { contentType, upsert: false });
    if (error) throw error;
    const { data: urlData } = supabase.storage.from('posts').getPublicUrl(fileName);
    return urlData.publicUrl;
  };

  const handleSubmit = async () => {
    if (!content.trim() && !imageUri) {
      Alert.alert(t('common.error'), t('social.createPost.emptyError'));
      return;
    }

    // Moderar texto antes de publicar
    if (content.trim()) {
      const textCheck = moderateText(content, userId);
      if (textCheck.blocked) {
        Alert.alert(t('social.createPost.blockedContent'), textCheck.message);
        return;
      }
      if (textCheck.warning) {
        Alert.alert(t('social.createPost.attention'), textCheck.message);
      }
    }

    // Moderar imagem antes de publicar
    if (imageUri) {
      const imageCheck = moderateImage({ uri: imageUri, name: 'post_image.jpg' }, userId);
      if (imageCheck.blocked) {
        Alert.alert(t('social.createPost.blockedImage'), imageCheck.message);
        return;
      }
    }

    setLoading(true);
    try {
      const imageUrl = await uploadImage(imageUri);
      const secondUrl = postType === 'before_after' ? await uploadImage(secondImageUri) : null;
      onSubmit?.({
        content,
        image: imageUrl,
        secondImage: secondUrl,
        postType,
        filter: selectedFilter !== 'none' ? selectedFilter : null,
        feeling: selectedFeeling,
        location: selectedLocation,
        workout: selectedWorkout,
      });
      resetAndClose();
    } catch (err) {
      Alert.alert(t('common.error'), t('social.createPost.publishError', { error: err.message }));
    } finally {
      setLoading(false);
    }
  };

  const resetAndClose = () => {
    setContent('');
    setImageUri(null);
    setSecondImageUri(null);
    setPostType('text');
    setSelectedFilter('none');
    setSelectedFeeling(null);
    setSelectedLocation(null);
    setSelectedWorkout(null);
    onClose();
  };

  return (
    <Modal visible={visible} transparent animationType="slide" onRequestClose={resetAndClose}>
      <TouchableOpacity style={styles.overlay} activeOpacity={1} onPress={resetAndClose}>
        <View style={styles.content} onStartShouldSetResponder={() => true}>
          <View style={styles.handle} />
          <View style={styles.header}>
            <Text style={styles.title}>{t('social.createPost.title')}</Text>
            <TouchableOpacity onPress={resetAndClose}>
              <Ionicons name="close" size={24} color={COLORS.textMuted} />
            </TouchableOpacity>
          </View>

          <PostTypeSelector selected={postType} onSelect={setPostType} />

          <TextInput
            style={styles.input}
            placeholder={postType === 'before_after' ? t('social.createPost.placeholderTransform') : t('social.createPost.placeholderFeeling')}
            placeholderTextColor={COLORS.textMuted}
            value={content}
            onChangeText={setContent}
            multiline
            textAlignVertical="top"
          />

          <ImageViewer uri={imageUri} onRemove={() => setImageUri(null)} />

          {postType === 'before_after' && imageUri && (
            <TouchableOpacity style={styles.addSecondBtn} onPress={() => handlePickImage(true)}>
              <Ionicons name="add-circle-outline" size={20} color={COLORS.primary} />
              <Text style={styles.addSecondText}>{t('social.createPost.addAfterPhoto')}</Text>
            </TouchableOpacity>
          )}

          {postType === 'before_after' && secondImageUri && (
            <ImageViewer uri={secondImageUri} onRemove={() => setSecondImageUri(null)} />
          )}

          {imageUri && postType !== 'before_after' && (
            <PhotoFilterPicker selected={selectedFilter} onSelect={setSelectedFilter} />
          )}

          {/* Feeling Picker */}
          <View style={styles.composerMetaRow}>
            <Text style={styles.metaLabel}>Sentimento:</Text>
            <ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={styles.metaScroll as any}>
              {['😃 Feliz', '🏋️ Treinando', '💪 Focado', '🔥 Animado', '😴 Cansado'].map(f => (
                <TouchableOpacity
                  key={f}
                  style={[styles.metaPill, selectedFeeling === f && styles.metaPillActive]}
                  onPress={() => setSelectedFeeling(selectedFeeling === f ? null : f)}
                >
                  <Text style={[styles.metaPillText, selectedFeeling === f && styles.metaPillTextActive]}>{f}</Text>
                </TouchableOpacity>
              ))}
            </ScrollView>
          </View>

          {/* Location Picker */}
          <View style={styles.composerMetaRow}>
            <Text style={styles.metaLabel}>Localização:</Text>
            <ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={styles.metaScroll as any}>
              {['Academia Nix', 'Parque Central', 'Home Gym', 'Estúdio Funcional'].map(l => (
                <TouchableOpacity
                  key={l}
                  style={[styles.metaPill, selectedLocation === l && styles.metaPillActive]}
                  onPress={() => setSelectedLocation(selectedLocation === l ? null : l)}
                >
                  <Text style={[styles.metaPillText, selectedLocation === l && styles.metaPillTextActive]}>📍 {l}</Text>
                </TouchableOpacity>
              ))}
            </ScrollView>
          </View>

          {/* Workout Picker */}
          <View style={styles.composerMetaRow}>
            <Text style={styles.metaLabel}>Marcar:</Text>
            <ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={styles.metaScroll as any}>
              {['Treino A', 'Treino B', 'Treino C', 'Cardio 5km'].map(w => (
                <TouchableOpacity
                  key={w}
                  style={[styles.metaPill, selectedWorkout === w && styles.metaPillActive]}
                  onPress={() => setSelectedWorkout(selectedWorkout === w ? null : w)}
                >
                  <Text style={[styles.metaPillText, selectedWorkout === w && styles.metaPillTextActive]}>🏃 {w}</Text>
                </TouchableOpacity>
              ))}
            </ScrollView>
          </View>

          <ImagePickerBar
            onGallery={() => handlePickImage(false)}
            onCamera={handleTakePhoto}
            uploading={uploading}
            t={t}
          />

          <Button
            title={t('social.createPost.publish')}
            onPress={handleSubmit}
            loading={loading || uploading}
            disabled={(!content.trim() && !imageUri) || uploading}
          />
        </View>
      </TouchableOpacity>
    </Modal>
  );
}

