import { getReferralData } from '../../services/referral';
import { useI18n } from '../../i18n';
import ReferralShareCard from './ReferralShareCard';
import ReferralLeaderboard from './ReferralLeaderboard';
import ReferralMilestones from './ReferralMilestones';

function InviteFriends() {
  const { user } = useAuth();
  const { t } = useI18n();
  const [data, setData] = useState(null);

  useEffect(() => {
    if (user?.id) getReferralData(user.id).then(setData);
  }, [user?.id]);

  const handleCopy = async () => {
    if (!data?.referral_code) return;
    try {
      const Clipboard = require('expo-clipboard');
      await Clipboard.setStringAsync(data.referral_code);
      Alert.alert(t('referral.copiedTitle'), t('referral.copiedMessage'));
    } catch {
      Alert.alert(t('referral.codeLabel'), data.referral_code);
    }
  };

  if (!data) return null;

  return (
    <ScrollView style={styles.container} showsVerticalScrollIndicator={false}>
      <ReferralShareCard
        referralCode={data.referral_code}
        referralCount={data.successful_referrals || 0}
        onCopy={handleCopy}
      />

      <ReferralMilestones currentReferrals={data.successful_referrals || 0} />

      <ReferralLeaderboard currentUserId={user?.id} />
    </ScrollView>
  );
}

