  const loadLeaders = async () => {
    if (!mounted.current) return;
    setLoading(true);
    setRegionalInfo(null);
    try {
      if (period === 'regional') {
        const { data: { session } } = await supabase.auth.getSession();
        const response = await fetch(`${process.env.EXPO_PUBLIC_API_URL}/api/rankings`, {
          headers: { 'Authorization': `Bearer ${session?.access_token}` }
        });
        const data = await response.json();
        if (response.ok && mounted.current) {
          if (data.rankings) {
            setLeaders(data.rankings.map((r, i) => ({
              rank: i + 1,
              name: r.name,
              xp: r.points,
              workouts: 0,
              level: 'free',
              avatar: r.avatar_url
