          .select('user_id, count')
          .gte('completed_at', weekAgo)
          .order('count', { ascending: false });

        if (!mounted.current) return;

        const userCounts = {};
        (data || []).forEach(w => { userCounts[w.user_id] = (userCounts[w.user_id] || 0) + 1; });
        const sorted = Object.entries(userCounts).sort(([, a], [, b]) => b - a).slice(0, 50);
        const userIds = sorted.map(([id]) => id);

        const { data: profiles } = await supabase.from('profiles')
          .select('id, name, total_xp, subscription_plan')
          .in('id', userIds);

        if (!mounted.current) return;

        const profileMap = {};
        (profiles || []).forEach(p => { profileMap[p.id] = p; });

        setLeaders(sorted.map(([id, count], i) => ({
          rank: i + 1,
          name: profileMap[id]?.name || t('social.athleteFallback'),
          xp: profileMap[id]?.total_xp || 0,
          workouts: count,
          level: profileMap[id]?.subscription_plan || 'free',
        })));
      } else {
        const { data } = await supabase.from('profiles')
          .select('id, name, total_xp, total_workouts, subscription_plan')
          .order('total_xp', { ascending: false })
          .limit(50);

        if (mounted.current) {
          setLeaders((data || []).map((p, i) => ({
            rank: i + 1,
            name: p.name || t('social.athleteFallback'),
            xp: p.total_xp || 0,
            workouts: p.total_workouts || 0,
            level: p.subscription_plan || 'free',
          })));
        }
      }
    } catch (err) {
      if (__DEV__) console.error('Erro ao carregar ranking:', err);
    } finally {
      if (mounted.current) setLoading(false);
    }
  };

  const periods = [
    { key: 'all', label: t('common.all') },
    { key: 'week', label: t('social.thisWeek') },
    { key: 'regional', label: 'Regional' },
  ];

  return (
    <View style={styles.container}>
      <View style={styles.header}>
        <Ionicons name="trophy" size={18} color={COLORS.primary} />
        <Text style={styles.title}>{t('social.rankingGlobal')}</Text>
      </View>

      <View style={styles.periodRow}>
        {periods.map(p => (
          <TouchableOpacity key={p.key} style={[styles.periodBtn, period === p.key && styles.periodActive]} onPress={() => setPeriod(p.key)}>
            <Text style={[styles.periodText, period === p.key && styles.periodTextActive]}>{p.label}</Text>
          </TouchableOpacity>
        ))}
      </View>

      {regionalInfo && (
        <View style={styles.regionalBanner}>
          <Ionicons name="location-outline" size={14} color={COLORS.primary} />
          <Text style={styles.regionalText}>
            Visualizando {regionalInfo.level === 'neighborhood' ? 'Bairro' : regionalInfo.level === 'city' ? 'Cidade' : 'Estado'}: <Text style={styles.boldRegion}>{regionalInfo.region}</Text>
          </Text>
        </View>
      )}

      {loading ? (
        <View style={styles.loading}>
          <ActivityIndicator size="small" color={COLORS.primary} />
          <Text style={styles.loadingText}>{t('common.loading')}</Text>
        </View>
      ) : leaders.length === 0 ? (
        <View style={styles.empty}>
          <Ionicons name="people-outline" size={32} color={COLORS.textMuted} />
          <Text style={styles.emptyText}>{t('social.noAthletesInRanking')}</Text>
        </View>
      ) : (
        <FlatList
          removeClippedSubviews={true}
          maxToRenderPerBatch={10}
          windowSize={5}
          data={leaders}
          keyExtractor={(item, i) => `${item.rank}-${i}`}
          renderItem={({ item, index }) => (
            <RankItem item={item} index={index} isCurrentUser={item.id === userId} />
          )}
          scrollEnabled={false}
          ItemSeparatorComponent={() => <View style={styles.separator} />}
        />
      )}
    </View>
  );
}

