// Compartilhar conclusão de treino com animações e gamificação - NOVAIX FITNESS

import React, { useRef, useEffect, useState, memo } from 'react';
import { View, Text, TouchableOpacity, StyleSheet, Animated, Share, Dimensions, Alert, ActivityIndicator } from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import { COLORS } from '../../constants/colors';
import { SPACING, BORDER_RADIUS } from '../../constants/spacing';
import { useI18n } from '../../i18n';
import { useAuth } from '../../context/AuthContext';
import { supabase } from '../../config/supabase';

const { height: SCREEN_HEIGHT, width: SCREEN_WIDTH } = Dimensions.get('window');

interface WorkoutShareProps {
  workout: any;
  xp?: number;
  duration?: any;
  exercises?: number;
  onShare?: () => void;
  onClose?: () => void;
}

export default memo(function WorkoutShare({ workout, xp = 100, duration = 30, exercises = 5, onShare, onClose }: WorkoutShareProps) {
  const { t } = useI18n();
  const { user } = useAuth();
  const scaleAnim = useMemo(() => new Animated.Value(0), []);
  const fadeAnim = useMemo(() => new Animated.Value(0), []);
  const confettiAnim = useMemo(() => new Animated.Value(0), []);
  const [sharingToFeed, setSharingToFeed] = useState(false);

  // States para contadores animados
  const [xpVal, setXpVal] = useState(0);
  const [durationVal, setDurationVal] = useState(0);
  const [exercisesVal, setExercisesVal] = useState(0);

  // Geração de confetes aleatórios
  const particles = useRef(
    Array.from({ length: 20 }).map(() => ({
      left: Math.random() * SCREEN_WIDTH,
      color: ['#CCFF00', '#FF2D55', '#34C759', '#007AFF', '#FF9500'][Math.floor(Math.random() * 5)],
      size: Math.random() * 8 + 6,
      shape: Math.random() > 0.5 ? 'circle' : 'square',
    }))
  ).current;

  useEffect(() => {
    // Animações de entrada da tela e dos confetes
    Animated.parallel([
      Animated.spring(scaleAnim, { toValue: 1, tension: 30, friction: 8, useNativeDriver: true }),
      Animated.timing(fadeAnim, { toValue: 1, duration: 300, useNativeDriver: true }),
      Animated.timing(confettiAnim, { toValue: 1, duration: 3000, useNativeDriver: true })
    ]).start();

    // Contadores com efeito count-up
    let currentXp = 0;
    let currentDuration = 0;
    let currentExercises = 0;

    const targetXp = xp || 0;
    const targetDuration = parseInt(duration) || 30;
    const targetExercises = exercises || 0;

    const interval = setInterval(() => {
      let done = true;
      if (currentXp < targetXp) {
        currentXp = Math.min(targetXp, currentXp + Math.ceil(targetXp / 15));
        setXpVal(currentXp);
        done = false;
      }
      if (currentDuration < targetDuration) {
        currentDuration = Math.min(targetDuration, currentDuration + Math.ceil(targetDuration / 15));
        setDurationVal(currentDuration);
        done = false;
      }
      if (currentExercises < targetExercises) {
        currentExercises = Math.min(targetExercises, currentExercises + 1);
        setExercisesVal(currentExercises);
        done = false;
      }
      if (done) clearInterval(interval);
    }, 50);

    return () => clearInterval(interval);
  }, [xp, duration, exercises]);

  const handleShare = async () => {
    const message = t('social.share.fullShareMessage', {
      icon: '🏋️',
      name: workout?.name || 'Treino',
      duration: duration || '30',
      exercises: exercises || 0,
      xp: xp || 0,
    });

    try {
      await Share.share({ message });
      onShare?.();
    } catch (err) {
      if (__DEV__) console.error('Erro ao compartilhar:', err);
    }
  };

  const handleShareToFeed = async () => {
    if (sharingToFeed) return;
    setSharingToFeed(true);
    try {
      if (!user?.id) {
        Alert.alert('Erro', 'Usuário não autenticado.');
        return;
      }
      const postContent = `🏋️ Acabei de concluir o treino "${workout?.name || 'Treino'}" em ${durationVal} minutos e conquistei +${xpVal} XP! #novaixfitness`;

      const { error } = await supabase.from('posts').insert({
        user_id: user.id,
        content: postContent,
        post_type: 'text',
      });

      if (error) throw error;

      Alert.alert('Sucesso', 'Conclusão de treino compartilhada no seu feed!');
      onClose?.();
    } catch (err) {
      Alert.alert('Erro', 'Não foi possível compartilhar no feed.');
      if (__DEV__) console.error('Erro ao criar post de treino:', err);
    } finally {
      setSharingToFeed(false);
    }
  };

  return (
    <View style={StyleSheet.absoluteFill}>
      {/* Confetes caindo */}
      {particles.map((p, i) => {
        const translateY = confettiAnim.interpolate({
          inputRange: [0, 1],
          outputRange: [-50, SCREEN_HEIGHT + 50],
        });
        const rotate = confettiAnim.interpolate({
          inputRange: [0, 1],
          outputRange: ['0deg', `${Math.random() * 360 + 360}deg`],
        });
        return (
          <Animated.View
            key={i}
            style={{
              position: 'absolute',
              left: p.left,
              top: 0,
              width: p.size,
              height: p.shape === 'circle' ? p.size : p.size * 1.5,
              borderRadius: p.shape === 'circle' ? p.size / 2 : 2,
              backgroundColor: p.color,
              transform: [{ translateY }, { rotate }],
              zIndex: 99,
              pointerEvents: 'none',
            }}
          />
        );
      })}

      {/* Cartão de Celebração */}
      <Animated.View style={[styles.container, { opacity: fadeAnim, transform: [{ scale: scaleAnim }] }]}>
        <View style={styles.header}>
          <View style={styles.iconContainer}>
            <Ionicons name="checkmark-circle" size={56} color={COLORS.success} />
          </View>
          <Text style={styles.title}>{t('social.share.workoutCompleted')}</Text>
          <Text style={styles.subtitle}>{t('social.share.congratulations')}</Text>
        </View>

        <View style={styles.statsGrid}>
          <View style={styles.statItem}>
            <Ionicons name="flame" size={24} color={COLORS.primary} />
            <Text style={styles.statValue}>+{xpVal}</Text>
            <Text style={styles.statLabel}>XP</Text>
          </View>
          <View style={styles.statDivider} />
          <View style={styles.statItem}>
            <Ionicons name="time" size={24} color={COLORS.info} />
            <Text style={styles.statValue}>{durationVal}</Text>
            <Text style={styles.statLabel}>min</Text>
          </View>
          <View style={styles.statDivider} />
          <View style={styles.statItem}>
            <Ionicons name="barbell" size={24} color={COLORS.success} />
            <Text style={styles.statValue}>{exercisesVal}</Text>
            <Text style={styles.statLabel}>{t('workout.exercises')}</Text>
          </View>
        </View>

        <View style={styles.shareSection}>
          <Text style={styles.shareTitle}>{t('social.share.shareAchievement')}</Text>

          {/* Compartilhar na Comunidade */}
          <TouchableOpacity style={[styles.shareBtn, { backgroundColor: COLORS.primary }]} onPress={handleShareToFeed} disabled={sharingToFeed}>
            {sharingToFeed ? (
              <ActivityIndicator color={COLORS.background} size="small" />
            ) : (
              <>
                <Ionicons name="people" size={20} color={COLORS.background} />
                <Text style={styles.shareText}>COMPARTILHAR NO FEED</Text>
              </>
            )}
          </TouchableOpacity>

          <View style={styles.shareOptions}>
            <TouchableOpacity style={styles.shareOption} onPress={handleShare}>
              <Ionicons name="share-social" size={24} color={COLORS.info} />
              <Text style={styles.shareOptionText}>Outros Apps</Text>
            </TouchableOpacity>
            <TouchableOpacity style={styles.shareOption} onPress={onClose}>
              <Ionicons name="checkmark-done" size={24} color={COLORS.success} />
              <Text style={styles.shareOptionText}>Concluir</Text>
            </TouchableOpacity>
          </View>
        </View>
      </Animated.View>
    </View>
  );
});

const styles = StyleSheet.create({
  container: { flex: 1, backgroundColor: COLORS.background, justifyContent: 'center', padding: SPACING.xl },
  header: { alignItems: 'center', marginBottom: SPACING.xl },
  iconContainer: { marginBottom: SPACING.md, shadowColor: COLORS.success, shadowOffset: { width: 0, height: 4 }, shadowOpacity: 0.3, shadowRadius: 10, elevation: 5 },
  title: { fontFamily: 'Montserrat_800ExtraBold', fontSize: 24, color: COLORS.success, letterSpacing: 1, marginBottom: SPACING.xs, textAlign: 'center' },
  subtitle: { fontFamily: 'Inter_400Regular', fontSize: 14, color: COLORS.textMuted, textAlign: 'center' },
  statsGrid: { flexDirection: 'row', backgroundColor: COLORS.surface, borderRadius: BORDER_RADIUS.lg, padding: SPACING.lg, marginBottom: SPACING.xl, borderWidth: 1, borderColor: COLORS.border },
  statItem: { flex: 1, alignItems: 'center', gap: SPACING.xs },
  statValue: { fontFamily: 'Montserrat_800ExtraBold', fontSize: 24, color: COLORS.textTitle },
  statLabel: { fontFamily: 'Inter_400Regular', fontSize: 11, color: COLORS.textMuted },
  statDivider: { width: 1, height: 50, backgroundColor: COLORS.border },
  shareSection: { alignItems: 'center' },
  shareTitle: { fontFamily: 'Montserrat_600SemiBold', fontSize: 13, color: COLORS.textMuted, marginBottom: SPACING.md },
  shareBtn: { flexDirection: 'row', alignItems: 'center', justifyContent: 'center', gap: SPACING.sm, paddingVertical: SPACING.md, paddingHorizontal: SPACING.xl, borderRadius: BORDER_RADIUS.md, width: '100%', marginBottom: SPACING.xl },
  shareText: { fontFamily: 'Montserrat_700Bold', fontSize: 13, color: COLORS.background, letterSpacing: 1 },
  shareOptions: { flexDirection: 'row', gap: 60 },
  shareOption: { alignItems: 'center', gap: SPACING.xs },
  shareOptionText: { fontFamily: 'Inter_500Medium', fontSize: 11, color: COLORS.textMuted },
});

import React, { useState, useEffect } from 'react';
import { View, Text, StyleSheet } from 'react-native';
import { COLORS } from '../../constants/colors';
import { SPACING, BORDER_RADIUS } from '../../constants/spacing';
import { supabase } from '../../config/supabase';
import StreakProgress from './StreakProgress';
import { STREAK_LEVELS, FlameIcon, calculateCurrentStreak, calculateBestStreak, generateWeekDots } from './WorkoutStreakHelpers';

export default function WorkoutStreak({ userId }: any) {
  const [streak, setStreak] = useState(0);
  const [bestStreak, setBestStreak] = useState(0);
  const [weekDots, setWeekDots] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => { loadStreak(); }, [userId]);

  const loadStreak = async () => {
    if (!userId) { setLoading(false); return; }
    try {
      const { data } = await supabase
        .from('user_workouts')
        .select('completed_at')
        .eq('user_id', userId)
        .order('completed_at', { ascending: false })
        .limit(90);

      if (!data || data.length === 0) { setLoading(false); return; }

      const uniqueDays = [...new Set(data.map(l => new Date(l.completed_at).toDateString()))];

      setStreak(calculateCurrentStreak(uniqueDays));
      setBestStreak(calculateBestStreak(uniqueDays));
      setWeekDots(generateWeekDots(uniqueDays));
    } catch (e) { if (__DEV__) console.warn('WorkoutStreak:', e); }
    finally { setLoading(false); }
  };

  const config = STREAK_LEVELS.slice().reverse().find(l => streak >= l.min) || STREAK_LEVELS[0];
  const nextLevel = STREAK_LEVELS.find(l => streak < l.min);

  if (loading) return null;

  return (
    <View style={styles.container}>
      <View style={styles.header}>
        <FlameIcon level={streak} size={28} />
        <View style={styles.headerInfo}>
          <Text style={styles.streakNumber}>{streak}</Text>
          <Text style={styles.streakLabel}>dias seguidos</Text>
        </View>
        <View style={[styles.levelBadge, { backgroundColor: config.color + '20' }]}>
          <Text style={[styles.levelText, { color: config.color }]}>{config.label}</Text>
        </View>
      </View>

      <View style={styles.weekRow}>
        {weekDots.map((d, i) => (
          <View key={i} style={styles.dayCol}>
            <Text style={[styles.dayLabel, d.isToday && { color: COLORS.primary, fontFamily: 'Montserrat_600SemiBold' }]}>{d.day}</Text>
            <View style={[styles.dayDot, d.active && styles.dayDotActive, d.isToday && styles.dayDotToday]} />
          </View>
        ))}
      </View>

      {nextLevel && <StreakProgress streak={streak} nextLevel={nextLevel} config={config} />}

      <View style={styles.statsRow}>
        <View style={styles.statItem}>
          <Text style={styles.statValue}>{bestStreak}</Text>
          <Text style={styles.statLabel}>Recorde</Text>
        </View>
        <View style={styles.statDivider} />
        <View style={styles.statItem}>
          <Text style={[styles.statValue, { color: COLORS.primary }]}>{streak}</Text>
          <Text style={styles.statLabel}>Atual</Text>
        </View>
        <View style={styles.statDivider} />
        <View style={styles.statItem}>
          <Text style={styles.statValue}>{STREAK_LEVELS.length}</Text>
          <Text style={styles.statLabel}>Níveis</Text>
        </View>
      </View>
    </View>
  );
}

