import { TouchableOpacity, Text, ActivityIndicator, StyleSheet, Animated } from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import { COLORS } from '../../constants/colors';
import { SPACING, BORDER_RADIUS, ICON_SIZES } from '../../constants/spacing';
import { SHADOWS } from '../../constants/shadows';
import { scale } from '../../utils/responsive';

const SIZES = {
  sm: { height: scale(40), fontSize: scale(12), iconSize: 14, paddingV: SPACING.sm },
  md: { height: scale(50), fontSize: scale(13), iconSize: ICON_SIZES.sm, paddingV: SPACING.md },
  lg: { height: scale(58), fontSize: scale(15), iconSize: ICON_SIZES.md, paddingV: SPACING.lg },
};

interface ButtonProps {
  title: string;
  onPress: () => void;
  variant?: string;
  icon?: string;
  iconPosition?: string;
  size?: string;
  loading?: boolean;
  disabled?: boolean;
  style?: any;
}

export function Button({
  title,
  onPress,
  variant = 'primary',
  icon,
  iconPosition = 'left',
  size = 'md',
  loading = false,
  disabled = false,
  style,
}: ButtonProps) {
  const scaleAnim = useMemo(() => new Animated.Value(1), []);
  const opacityAnim = useMemo(() => new Animated.Value(1), []);
  const shimmerAnim = useMemo(() => new Animated.Value(0), []);

  const s = SIZES[size as keyof typeof SIZES] || SIZES.md;

  // Animacao de shimmer para botao primario
  useEffect(() => {
    if (variant === 'primary' && !disabled) {
      const shimmer = Animated.loop(
        Animated.sequence([
          Animated.timing(shimmerAnim, { toValue: 1, duration: 2000, useNativeDriver: true }),
          Animated.timing(shimmerAnim, { toValue: 0, duration: 2000, useNativeDriver: true }),
        ])
      );
      shimmer.start();
      return () => shimmer.stop();
    }
  }, [variant, disabled]);

  const handlePressIn = () => {
    Animated.parallel([
      Animated.spring(scaleAnim, { toValue: 0.96, friction: 5, useNativeDriver: true }),
      Animated.timing(opacityAnim, { toValue: 0.85, duration: 100, useNativeDriver: true }),
    ]).start();
  };

  const handlePressOut = () => {
    Animated.parallel([
      Animated.spring(scaleAnim, { toValue: 1, friction: 5, useNativeDriver: true }),
      Animated.timing(opacityAnim, { toValue: 1, duration: 150, useNativeDriver: true }),
    ]).start();
  };

  const variants = {
    primary: { container: styles.primary, text: styles.primaryText, iconColor: COLORS.background },
    secondary: { container: styles.secondary, text: styles.secondaryText, iconColor: COLORS.primary },
    ghost: { container: styles.ghost, text: styles.ghostText, iconColor: COLORS.textDescription },
    back: { container: styles.back, text: styles.backText, iconColor: COLORS.textTitle },
    danger: { container: styles.danger, text: styles.dangerText, iconColor: COLORS.background },
    google: { container: styles.google, text: styles.googleText, iconColor: COLORS.textTitle },
    apple: { container: styles.apple, text: styles.appleText, iconColor: COLORS.textTitle },
  };

  const current = variants[variant as keyof typeof variants] || variants.primary;

  const iconEl = icon ? (
    <Ionicons
      name={icon as any}
      size={s.iconSize}
      color={current.iconColor}
      style={iconPosition === 'right' ? { marginLeft: SPACING.xs } : { marginRight: SPACING.xs }}
    />
  ) : null;

  return (
    <Animated.View style={[{ transform: [{ scale: scaleAnim }], opacity: opacityAnim }, style]}>
      <TouchableOpacity
        style={[styles.base, { height: s.height }, current.container, disabled && styles.disabled]}
        onPress={onPress}
        onPressIn={handlePressIn}
        onPressOut={handlePressOut}
        disabled={disabled || loading}
        activeOpacity={1}
        accessibilityLabel={title}
        accessibilityRole="button"
        accessibilityState={{ disabled: disabled || loading, busy: loading }}
      >
        {loading ? (
          <ActivityIndicator color={variant === 'primary' || variant === 'danger' ? COLORS.background : COLORS.primary} size="small" />
        ) : (
          <>
            {icon && iconPosition === 'left' && iconEl}
            <Text style={[styles.text, current.text, { fontSize: s.fontSize }]}>{title}</Text>
            {icon && iconPosition === 'right' && iconEl}
          </>
        )}
      </TouchableOpacity>
    </Animated.View>
  );
}

const styles = StyleSheet.create({
  base: {
    borderRadius: BORDER_RADIUS.md,
    flexDirection: 'row',
    justifyContent: 'center',
    alignItems: 'center',
    gap: SPACING.xs,
  },
  text: {
    fontFamily: 'Montserrat_700Bold',
    textTransform: 'uppercase',
    letterSpacing: 1.2,
  },
  disabled: { opacity: 0.4 },
  primary: { backgroundColor: COLORS.primary, ...SHADOWS.md },
  primaryText: { color: COLORS.background },
  secondary: { backgroundColor: 'transparent', borderWidth: 1.5, borderColor: COLORS.primary },
  secondaryText: { color: COLORS.primary },
  ghost: { backgroundColor: 'transparent' },
  ghostText: { color: COLORS.textDescription },
  back: { backgroundColor: COLORS.surface, borderWidth: 1, borderColor: COLORS.border },
  backText: { color: COLORS.textTitle },
  danger: { backgroundColor: COLORS.error, ...SHADOWS.md },
  dangerText: { color: COLORS.background },
  google: { backgroundColor: COLORS.textTitle, borderWidth: 1, borderColor: COLORS.borderLight, ...SHADOWS.sm },
  googleText: { color: COLORS.background },
  apple: { backgroundColor: COLORS.background, borderWidth: 1, borderColor: COLORS.border, ...SHADOWS.sm },
  appleText: { color: COLORS.textTitle },
});

