import { View, Text, TextInput, TouchableOpacity, StyleSheet, Animated } from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import { COLORS } from '../../constants/colors';
import { SPACING, BORDER_RADIUS, ICON_SIZES } from '../../constants/spacing';
import { scale } from '../../utils/responsive';

interface InputProps {
  label?: string;
  value: string;
  onChangeText: (text: string) => void;
  placeholder?: string;
  error?: string;
  success?: string;
  icon?: string;
  secureTextEntry?: boolean;
  keyboardType?: any;
  autoCapitalize?: any;
  style?: any;
  disabled?: boolean;
  maxLength?: number;
  showCharCount?: boolean;
}

export function Input({
  label,
  value,
  onChangeText,
  placeholder,
  error,
  success,
  icon,
  secureTextEntry,
  keyboardType,
  autoCapitalize,
  style,
  disabled = false,
  maxLength,
  showCharCount = false,
}: InputProps) {
  const [focused, setFocused] = useState(false);
  const [showPassword, setShowPassword] = useState(false);
  const borderColorAnim = useMemo(() => new Animated.Value(0), []);
  const shakeAnim = useMemo(() => new Animated.Value(0), []);

  useEffect(() => {
    Animated.timing(borderColorAnim, {
      toValue: error ? 2 : focused ? 1 : 0,
      duration: 200,
      useNativeDriver: false,
    }).start();
  }, [focused, error]);

  // Animacao de shake quando ha erro
  useEffect(() => {
    if (error) {
      Animated.sequence([
        Animated.timing(shakeAnim, { toValue: 10, duration: 50, useNativeDriver: true }),
        Animated.timing(shakeAnim, { toValue: -10, duration: 50, useNativeDriver: true }),
        Animated.timing(shakeAnim, { toValue: 6, duration: 50, useNativeDriver: true }),
        Animated.timing(shakeAnim, { toValue: -6, duration: 50, useNativeDriver: true }),
        Animated.timing(shakeAnim, { toValue: 0, duration: 50, useNativeDriver: true }),
      ]).start();
    }
  }, [error]);

  const borderColor = borderColorAnim.interpolate({
    inputRange: [0, 1, 2],
    outputRange: [COLORS.border, COLORS.primary, COLORS.error],
  });

  const backgroundColor = borderColorAnim.interpolate({
    inputRange: [0, 1, 2],
    outputRange: [COLORS.surface, COLORS.primary + '05', COLORS.error + '05'],
  });

  const handleFocus = useCallback(() => setFocused(true), []);
  const handleBlur = useCallback(() => setFocused(false), []);

  const iconColor = focused ? COLORS.primary : COLORS.textMuted;
  const validationIcon = error ? 'close-circle' : success ? 'checkmark-circle' : null;
  const validationColor = error ? COLORS.error : COLORS.success;

  return (
    <Animated.View style={[styles.container, { transform: [{ translateX: shakeAnim }] }, style]}>
      {label && (
        <View style={styles.labelRow}>
          <Text style={[styles.label, error && styles.labelError]}>{label}</Text>
          {showCharCount && maxLength && (
            <Text style={styles.charCount}>{value.length}/{maxLength}</Text>
          )}
        </View>
      )}
      <Animated.View style={[styles.inputWrapper, { borderColor, backgroundColor }, disabled && styles.disabled]}>
        {icon && (
          <Ionicons name={icon as any} size={ICON_SIZES.sm} color={iconColor} style={styles.icon} />
        )}
        <TextInput
          style={styles.input}
          value={value}
          onChangeText={onChangeText}
          placeholder={placeholder}
          placeholderTextColor={COLORS.textMuted + '80'}
          secureTextEntry={secureTextEntry && !showPassword}
          keyboardType={keyboardType}
          autoCapitalize={autoCapitalize}
          onFocus={handleFocus}
          onBlur={handleBlur}
          maxLength={maxLength}
          accessibilityLabel={label || placeholder}
          accessibilityHint={error || success || undefined}
          editable={!disabled}
        />
        {secureTextEntry && (
          <TouchableOpacity onPress={() => setShowPassword(!showPassword)} style={styles.eyeButton}>
            <Ionicons name={showPassword ? 'eye-off-outline' : 'eye-outline'} size={ICON_SIZES.sm} color={COLORS.textMuted} />
          </TouchableOpacity>
        )}
        {validationIcon && !secureTextEntry && (
          <Ionicons name={validationIcon as any} size={18} color={validationColor} style={styles.validationIcon} />
        )}
      </Animated.View>
      {error && (
        <View style={styles.messageRow}>
          <Ionicons name="alert-circle" size={14} color={COLORS.error} />
          <Text style={styles.errorText}>{error}</Text>
        </View>
      )}
      {success && !error && (
        <View style={styles.messageRow}>
          <Ionicons name="checkmark-circle" size={14} color={COLORS.success} />
          <Text style={styles.successText}>{success}</Text>
        </View>
      )}
    </Animated.View>
  );
}

const styles = StyleSheet.create({
  container: { marginBottom: SPACING.lg },
  labelRow: { flexDirection: 'row', justifyContent: 'space-between', marginBottom: SPACING.sm },
  label: { fontFamily: 'Montserrat_600SemiBold', fontSize: scale(11), color: COLORS.textTitle, textTransform: 'uppercase', letterSpacing: 1.2 },
  labelError: { color: COLORS.error },
  charCount: { fontFamily: 'Inter_400Regular', fontSize: 11, color: COLORS.textMuted },
  inputWrapper: { flexDirection: 'row', alignItems: 'center', height: scale(56), borderRadius: BORDER_RADIUS.md, borderWidth: 1.5 },
  disabled: { opacity: 0.6 },
  icon: { marginLeft: SPACING.md, marginRight: SPACING.xs },
  input: { flex: 1, height: '100%', paddingHorizontal: SPACING.md, color: COLORS.textTitle, fontFamily: 'Inter_400Regular', fontSize: scale(15) },
  eyeButton: { paddingHorizontal: SPACING.md, height: '100%', justifyContent: 'center' },
  validationIcon: { marginRight: SPACING.md },
  messageRow: { flexDirection: 'row', alignItems: 'center', gap: 4, marginTop: SPACING.xs },
  errorText: { fontFamily: 'Inter_400Regular', fontSize: scale(12), color: COLORS.error, flex: 1 },
  successText: { fontFamily: 'Inter_400Regular', fontSize: scale(12), color: COLORS.success, flex: 1 },
});

