// Componente de carregamento animado - NOVAIX FITNESS

import React, { useEffect, useMemo } from 'react';
import { View, Text, StyleSheet, Animated, ActivityIndicator } from 'react-native';
import { COLORS } from '../../constants/colors';
import { SPACING, BORDER_RADIUS } from '../../constants/spacing';

interface LoadingProps {
  text?: string;
  size?: 'small' | 'large';
  variant?: 'spinner' | 'dots' | 'pulse' | 'overlay';
  color?: string;
}

// Loading com dots animados
function LoadingDots({ color = COLORS.primary }: { color?: string }) {
  const dots = useMemo(() => [0, 1, 2].map(() => new Animated.Value(0.3)), []);

  useEffect(() => {
    const animations = dots.map((dot, i) =>
      Animated.loop(
        Animated.sequence([
          Animated.delay(i * 200),
          Animated.timing(dot, { toValue: 1, duration: 400, useNativeDriver: true }),
          Animated.timing(dot, { toValue: 0.3, duration: 400, useNativeDriver: true }),
        ])
      )
    );
    Animated.parallel(animations).start();
  }, []);

  return (
    <View style={styles.dotsContainer}>
      {dots.map((dot, i) => (
        <Animated.View key={i} style={[styles.dot, { opacity: dot, backgroundColor: color }]} />
      ))}
    </View>
  );
}

// Loading com pulso
function LoadingPulse({ color = COLORS.primary }: { color?: string }) {
  const scale = useMemo(() => new Animated.Value(1), []);

  useEffect(() => {
    Animated.loop(
      Animated.sequence([
        Animated.timing(scale, { toValue: 1.3, duration: 600, useNativeDriver: true }),
        Animated.timing(scale, { toValue: 1, duration: 600, useNativeDriver: true }),
      ])
    ).start();
  }, []);

  return (
    <View style={styles.pulseContainer}>
      <Animated.View style={[styles.pulseRing, { transform: [{ scale }], borderColor: color }]} />
      <View style={[styles.pulseCenter, { backgroundColor: color }]} />
    </View>
  );
}

export default function Loading({
  text,
  size = 'large',
  variant = 'spinner',
  color = COLORS.primary,
}: LoadingProps) {
  if (variant === 'overlay') {
    return (
      <View style={styles.overlay}>
        <View style={styles.overlayCard}>
          <ActivityIndicator size="large" color={color} />
          {text && <Text style={styles.overlayText}>{text}</Text>}
        </View>
      </View>
    );
  }

  if (variant === 'dots') return <LoadingDots color={color} />;
  if (variant === 'pulse') return <LoadingPulse color={color} />;

  return (
    <View style={styles.container}>
      <ActivityIndicator size={size} color={color} />
      {text && <Text style={styles.text}>{text}</Text>}
    </View>
  );
}

const styles = StyleSheet.create({
  container: { alignItems: 'center', justifyContent: 'center', padding: SPACING.xl },
  text: { fontFamily: 'Inter_400Regular', fontSize: 14, color: COLORS.textMuted, marginTop: SPACING.md },
  dotsContainer: { flexDirection: 'row', alignItems: 'center', gap: 6 },
  dot: { width: 8, height: 8, borderRadius: 4 },
  pulseContainer: { width: 48, height: 48, justifyContent: 'center', alignItems: 'center' },
  pulseRing: { position: 'absolute', width: 48, height: 48, borderRadius: 24, borderWidth: 2 },
  pulseCenter: { width: 16, height: 16, borderRadius: 8 },
  overlay: { ...StyleSheet.absoluteFill, backgroundColor: COLORS.overlay, justifyContent: 'center', alignItems: 'center', zIndex: 999 },
  overlayCard: { backgroundColor: COLORS.surface, borderRadius: BORDER_RADIUS.lg, padding: SPACING.xxl, alignItems: 'center', gap: SPACING.md },
  overlayText: { fontFamily: 'Inter_500Medium', fontSize: 14, color: COLORS.textDescription },
});

import { useState, useEffect, useCallback } from 'react';
import { View, Text, TouchableOpacity, StyleSheet, ActivityIndicator } from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import { COLORS } from '../../constants/colors';
import { SPACING, BORDER_RADIUS } from '../../constants/spacing';
import { Input } from './Input';
import { ESTADOS } from './StatePickerModal';
import StatePickerModal from './StatePickerModal';

const formatCEP = (v) => {
  const clean = v.replace(/\D/g, '').slice(0, 8);
  return clean.length <= 5 ? clean : `${clean.slice(0, 5)}-${clean.slice(5)}`;
};

export default function LocationSection({ onLocationChange, initialLocation }: any) {
  const [cep, setCep] = useState('');
  const [street, setStreet] = useState('');
  const [number, setNumber] = useState('');
  const [neighborhood, setNeighborhood] = useState('');
  const [selectedState, setSelectedState] = useState('');
  const [city, setCity] = useState('');
  const [showStateModal, setShowStateModal] = useState(false);
  const [loadingCep, setLoadingCep] = useState(false);

  const fetchCEP = useCallback(async (cepValue) => {
    const clean = cepValue.replace(/\D/g, '');
    if (clean.length !== 8) return;
    setLoadingCep(true);
    try {
      const res = await fetch(`https://viacep.com.br/ws/${clean}/json/`);
      const data = await res.json();
      if (!data.erro) {
        setStreet(data.logradouro || '');
        setNeighborhood(data.bairro || '');
        setCity(data.localidade || '');
        const stateObj = ESTADOS.find(e => e.sigla === data.uf);
        if (stateObj) setSelectedState(stateObj.sigla);
      }
    } catch (e) { if (__DEV__) console.warn('LocationSection:', e); }
    setLoadingCep(false);
  }, []);

  useEffect(() => {
    const clean = cep.replace(/\D/g, '');
    if (clean.length === 8) fetchCEP(cep);
  }, [cep, fetchCEP]);

  useEffect(() => {
    const location = `${street}${number ? ', ' + number : ''}${neighborhood ? ' - ' + neighborhood : ''}${city ? ', ' + city : ''}${selectedState ? ' - ' + selectedState : ''}`;
    onLocationChange?.({ street, number, neighborhood, city, state: selectedState, cep, full: location });
  }, [street, number, neighborhood, city, selectedState, cep]);

  return (
    <View>
      <Text style={styles.sectionLabel}>LOCALIZAÇÃO</Text>
      <View style={styles.cepRow}>
        <View style={{ flex: 1 }}>
          <Input label="CEP" placeholder="00000-000" value={cep} onChangeText={(v) => setCep(formatCEP(v))} keyboardType="numeric" icon="map-outline" />
        </View>
        {loadingCep && <ActivityIndicator size="small" color={COLORS.primary} style={{ marginLeft: SPACING.sm }} />}
      </View>

      {street.length > 0 && (
        <>
          <Input label="RUA" value={street} onChangeText={setStreet} icon="location-outline" />
          <View style={styles.row}>
            <View style={{ width: 60 }}>
              <Input label="NÚMERO" placeholder="Nº" value={number} onChangeText={setNumber} keyboardType="numeric" icon="hash" />
            </View>
            <View style={{ flex: 1 }}>
              <Input label="BAIRRO" value={neighborhood} onChangeText={setNeighborhood} icon="location-outline" />
            </View>
          </View>
        </>
      )}

      <View style={styles.row}>
        <TouchableOpacity style={styles.stateBtn} onPress={() => setShowStateModal(true)} accessibilityLabel={`Estado: ${selectedState || 'Selecionar'}`} accessibilityRole="button" accessibilityHint="Abrir lista de estados">
          <Text style={styles.stateLabel}>ESTADO</Text>
          <View style={styles.stateBox}>
            <Text style={styles.stateText}>{selectedState || 'UF'}</Text>
            <Ionicons name="chevron-down" size={14} color={COLORS.textTitle} />
          </View>
        </TouchableOpacity>
        <View style={{ flex: 1 }}>
          <Input label="CIDADE" placeholder={selectedState ? "Buscar cidade" : "CEP primeiro"} value={city} onChangeText={setCity} disabled={!selectedState} icon="location-outline" />
        </View>
      </View>

      <TouchableOpacity style={styles.gpsBtn} onPress={() => {}} accessibilityLabel="Usar minha localização" accessibilityRole="button" accessibilityHint="Detectar localização automaticamente">
        <Ionicons name="locate" size={16} color={COLORS.primary} />
        <Text style={styles.gpsText}>Usar minha localização</Text>
      </TouchableOpacity>

      <StatePickerModal
        visible={showStateModal}
        selectedState={selectedState}
        onSelect={(sigla) => { setSelectedState(sigla); setCity(''); setShowStateModal(false); }}
        onClose={() => setShowStateModal(false)}
      />
    </View>
  );
}

const styles = StyleSheet.create({
