          </View>
          {onFavorite && (
            <TouchableOpacity onPress={onFavorite} style={styles.favoriteBtn}>
              <Ionicons
                name={isFavorite ? 'heart' : 'heart-outline'}
                size={20}
                color={isFavorite ? COLORS.error : COLORS.textMuted}
