import React, { useState, useRef, useEffect } from 'react';
import { View, Text, TouchableOpacity, Modal, TextInput, StyleSheet, Animated } from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import * as Haptics from 'expo-haptics';
import { COLORS } from '../../constants/colors';
import { SPACING, BORDER_RADIUS } from '../../constants/spacing';
import { RATING_CONFIG, QUICK_TAGS } from '../../data/ratingModal';
import { useI18n } from '../../i18n';

function StarRating({ rating, onSelect, t }: any) {
  return (
    <View style={styles.starsContainer}>
      {[1, 2, 3, 4, 5].map(star => (
        <TouchableOpacity key={star} onPress={() => { onSelect(star); try { Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light); } catch {} }} style={styles.starBtn} accessibilityLabel={t('workout.rating.rateStars', { count: star })} accessibilityRole="button">
          <Ionicons name={star <= rating ? 'star' : 'star-outline'} size={44} color={star <= rating ? COLORS.attention : COLORS.surfaceOverlay} />
        </TouchableOpacity>
      ))}
    </View>
  );
}

export default function RatingModal({ visible, onClose, onSubmit }: any) {
  const { t } = useI18n();
  const [rating, setRating] = useState(0);
  const [comment, setComment] = useState('');
  const [selectedTags, setSelectedTags] = useState<any[]>([]);
  const slideAnim = useMemo(() => new Animated.Value(300), []);
  const fadeAnim = useMemo(() => new Animated.Value(0), []);

  useEffect(() => {
    if (visible) {
      Animated.parallel([
        Animated.spring(slideAnim, { toValue: 0, tension: 30, friction: 8, useNativeDriver: true }),
        Animated.timing(fadeAnim, { toValue: 1, duration: 200, useNativeDriver: true }),
      ]).start();
    }
  }, [visible]);

  const toggleTag = (tag: any) => {
    setSelectedTags(prev => prev.includes(tag) ? prev.filter(t => t !== tag) : [...prev, tag]);
  };

  const handleSubmit = () => {
    const fullComment = selectedTags.length > 0
      ? `[${selectedTags.join(', ')}] ${comment}`.trim()
      : comment;
    onSubmit({ rating, comment: fullComment });
    setRating(0);
    setComment('');
    setSelectedTags([]);
    onClose();
  };

  const config = RATING_CONFIG.find(r => r.stars === rating);

  return (
    <Modal visible={visible} transparent animationType="fade" onRequestClose={onClose}>
      <TouchableOpacity style={styles.overlay} activeOpacity={1} onPress={onClose}>
        <Animated.View style={[styles.content, { opacity: fadeAnim, transform: [{ translateY: slideAnim }] }]} onStartShouldSetResponder={() => true}>
          <View style={styles.handle} />

          <View style={styles.header}>
            <Text style={styles.title}>{t('workout.rating.title')}</Text>
            <Text style={styles.subtitle}>{t('workout.rating.subtitle')}</Text>
          </View>

          <StarRating rating={rating} onSelect={setRating} t={t} />

          {rating > 0 && config && (
            <View style={[styles.feedbackBadge, { backgroundColor: config.color + '15' }]}>
              <Ionicons name={config.icon as any} size={16} color={config.color} />
              <Text style={[styles.feedbackText, { color: config.color }]}>{config.label}</Text>
            </View>
          )}

          <View style={styles.tagsSection}>
            <Text style={styles.tagsLabel}>{t('workout.rating.howWas')}</Text>
            <View style={styles.tagsRow}>
              {QUICK_TAGS.map(tag => (
                <TouchableOpacity
                  key={tag}
                  style={[styles.tag, selectedTags.includes(tag) && styles.tagActive]}
                  onPress={() => toggleTag(tag)}
                >
                  <Text style={[styles.tagText, selectedTags.includes(tag) && styles.tagTextActive]}>{tag}</Text>
                </TouchableOpacity>
              ))}
            </View>
          </View>

          <TextInput
            style={styles.input}
            placeholder={t('workout.rating.optionalComment')}
            placeholderTextColor={COLORS.textMuted}
            value={comment}
            onChangeText={setComment}
            multiline
            textAlignVertical="top"
          />

          <TouchableOpacity
            style={[styles.submitBtn, rating === 0 && styles.submitBtnDisabled]}
            onPress={handleSubmit}
            disabled={rating === 0}
          >
            <Ionicons name="send" size={18} color={COLORS.background} />
            <Text style={styles.submitText}>{t('workout.rating.submit')}</Text>
          </TouchableOpacity>

          <TouchableOpacity style={styles.cancelBtn} onPress={onClose}>
            <Text style={styles.cancelText}>{t('workout.rating.skipForNow')}</Text>
          </TouchableOpacity>
        </Animated.View>
      </TouchableOpacity>
    </Modal>
  );
}

const styles = StyleSheet.create({
  overlay: { flex: 1, backgroundColor: 'rgba(0,0,0,0.5)', justifyContent: 'flex-end' },
  content: { backgroundColor: COLORS.surface, borderTopLeftRadius: BORDER_RADIUS.xl, borderTopRightRadius: BORDER_RADIUS.xl, padding: SPACING.xl, paddingBottom: 40 },
