import { View, Text, TouchableOpacity, StyleSheet, Animated } from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import * as Haptics from 'expo-haptics';
import { Audio } from 'expo-av';
import { COLORS } from '../../constants/colors';
import { SPACING, BORDER_RADIUS } from '../../constants/spacing';
import { SHADOWS } from '../../constants/shadows';

const PRESETS = [
  { label: '15s', seconds: 15 },
  { label: '30s', seconds: 30 },
  { label: '45s', seconds: 45 },
  { label: '60s', seconds: 60 },
  { label: '90s', seconds: 90 },
  { label: '120s', seconds: 120 },
];

export default function RestTimer({ onComplete, defaultSeconds = 60 }) {
  const [selectedTime, setSelectedTime] = useState(defaultSeconds);
  const [remaining, setRemaining] = useState(0);
  const [isRunning, setIsRunning] = useState(false);
  const [isFinished, setIsFinished] = useState(false);
  const scaleAnim = useMemo(() => new Animated.Value(1), []);
  const intervalRef = useRef(null);

  useEffect(() => {
    return () => clearInterval(intervalRef.current);
  }, []);

  useEffect(() => {
    if (isRunning && remaining > 0) {
      intervalRef.current = setInterval(() => {
        setRemaining(prev => {
          if (prev <= 1) {
            clearInterval(intervalRef.current);
            handleFinish();
            return 0;
          }
          if (prev <= 4) {
            Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Medium);
            Animated.sequence([
              Animated.timing(scaleAnim, { toValue: 1.2, duration: 100, useNativeDriver: true }),
              Animated.timing(scaleAnim, { toValue: 1, duration: 100, useNativeDriver: true }),
            ]).start();
          }
          return prev - 1;
        });
      }, 1000);
    }
    return () => clearInterval(intervalRef.current);
  }, [isRunning]);

  const handleStart = () => {
    setRemaining(selectedTime);
    setIsRunning(true);
    setIsFinished(false);
  };

  const handlePause = () => {
    setIsRunning(false);
    clearInterval(intervalRef.current);
  };

  const handleResume = () => {
    setIsRunning(true);
  };

  const handleReset = () => {
    clearInterval(intervalRef.current);
    setRemaining(0);
    setIsRunning(false);
    setIsFinished(false);
  };

  const handleFinish = async () => {
    setIsRunning(false);
    setIsFinished(true);
    Haptics.notificationAsync(Haptics.NotificationFeedbackType.Success);
    try {
      const { sound } = await Audio.Sound.createAsync(require('../../../assets/sounds/bell.mp3'));
      await sound.playAsync();
    } catch {}
    onComplete?.();
  };

  const formatTime = (seconds) => {
    const m = Math.floor(seconds / 60);
    const s = seconds % 60;
    return `${m}:${s.toString().padStart(2, '0')}`;
  };

  const progress = remaining > 0 ? remaining / selectedTime : 1;

  return (
    <View style={styles.container}>
      {!isRunning && !isFinished ? (
        <>
          <Text style={styles.label}>TEMPO DE DESCANSO</Text>
          <View style={styles.presets}>
            {PRESETS.map(preset => (
              <TouchableOpacity
                key={preset.seconds}
                style={[styles.presetBtn, selectedTime === preset.seconds && styles.presetActive]}
                onPress={() => setSelectedTime(preset.seconds)}
              >
                <Text style={[styles.presetText, selectedTime === preset.seconds && styles.presetTextActive]}>
                  {preset.label}
                </Text>
              </TouchableOpacity>
            ))}
          </View>
          <TouchableOpacity style={styles.startBtn} onPress={handleStart}>
            <Ionicons name="play" size={24} color={COLORS.background} />
            <Text style={styles.startBtnText}>INICIAR DESCANSO</Text>
          </TouchableOpacity>
        </>
      ) : (
        <>
          <Animated.View style={[styles.timerContainer, { transform: [{ scale: scaleAnim }] }]}>
            <View style={[styles.progressRing, { borderColor: progress > 0.3 ? COLORS.primary : COLORS.error }]}>
              <Text style={[styles.timerText, remaining <= 4 && styles.timerWarning]}>
                {formatTime(remaining)}
              </Text>
              <Text style={styles.timerLabel}>
                {isFinished ? 'PRONTO!' : 'DESCANSO'}
              </Text>
            </View>
          </Animated.View>

          <View style={styles.controls}>
            {!isFinished ? (
              <>
                <TouchableOpacity style={styles.controlBtn} onPress={isRunning ? handlePause : handleResume}>
                  <Ionicons name={isRunning ? 'pause' : 'play'} size={20} color={COLORS.textTitle} />
                  <Text style={styles.controlText}>{isRunning ? 'PAUSAR' : 'CONTINUAR'}</Text>
                </TouchableOpacity>
                <TouchableOpacity style={[styles.controlBtn, styles.resetBtn]} onPress={handleReset}>
                  <Ionicons name="refresh" size={20} color={COLORS.textMuted} />
                </TouchableOpacity>
              </>
            ) : (
              <TouchableOpacity style={styles.controlBtn} onPress={handleReset}>
                <Ionicons name="checkmark-circle" size={20} color={COLORS.textTitle} />
                <Text style={styles.controlText}>CONTINUAR TREINO</Text>
              </TouchableOpacity>
            )}
          </View>
        </>
      )}
    </View>
  );
}

const styles = StyleSheet.create({
  container: { alignItems: 'center', paddingVertical: SPACING.xl },
  label: { fontFamily: 'Montserrat_600SemiBold', fontSize: 12, color: COLORS.textMuted, letterSpacing: 1, marginBottom: SPACING.lg },
  presets: { flexDirection: 'row', gap: SPACING.sm, marginBottom: SPACING.xl },
