  progressRing: { width: 160, height: 160, borderRadius: 80, borderWidth: 6, justifyContent: 'center', alignItems: 'center', backgroundColor: COLORS.surface },
  timerText: { fontFamily: 'Montserrat_800ExtraBold', fontSize: 48, color: COLORS.textTitle, fontVariant: ['tabular-nums'] },
  timerWarning: { color: COLORS.error },
  timerLabel: { fontFamily: 'Montserrat_600SemiBold', fontSize: 12, color: COLORS.textMuted, letterSpacing: 2 },
  controls: { flexDirection: 'row', gap: SPACING.md },
  controlBtn: { flexDirection: 'row', alignItems: 'center', gap: SPACING.xs, backgroundColor: COLORS.primary, paddingHorizontal: SPACING.xl, paddingVertical: SPACING.md, borderRadius: BORDER_RADIUS.full },
  controlText: { fontFamily: 'Montserrat_600SemiBold', fontSize: 13, color: COLORS.background },
