    : {
        shadowColor: '#000',
        shadowOffset: { width: 0, height: 4 },
        shadowOpacity: 0.2,
        shadowRadius: 8,
      },
  large: isAndroid
    ? { elevation: 8 }
    : isWeb
    ? ({ boxShadow: '0px 4px 8px rgba(0, 0, 0, 0.2)' } as any)
    : {
        shadowColor: '#000',
        shadowOffset: { width: 0, height: 4 },
        shadowOpacity: 0.2,
