  signUpWithEmail: (email: string, password: string, metadata?: { name?: string; [key: string]: unknown }) => Promise<{ user: User | null; session: Session | null }>;
  signInWithGoogle: () => Promise<{ provider: string; url: string }>;
  signInWithApple: () => Promise<{ provider: string; url: string }>;
  resetPassword: (email: string) => Promise<void>;
  signOut: () => Promise<void>;
  saveOnboarding: (data: Record<string, unknown>) => Promise<void>;
  loadProfile: (userId: string) => Promise<void>;
  updateProfile: (updates: Partial<Profile>) => Promise<void>;
}

import { createContext, useContext, useState, useEffect, useCallback, useMemo } from 'react';
import type { ReactNode } from 'react';
import { useColorScheme } from 'react-native';
import { COLORS, THEMES } from '../constants/colors';
import type { ThemeColors } from '../constants/colors';
import { useAuth } from './AuthContext';
import { supabase } from '../config/supabase';
import { updateWebStyles } from '../components';

export type ThemeMode = 'dark' | 'light' | 'system';

export interface ThemeContextType {
  colors: ThemeColors;
  isDark: boolean;
  themeMode: ThemeMode;
  setThemeMode: (mode: ThemeMode) => Promise<void>;
}

const ThemeContext = createContext<ThemeContextType>({
  colors: COLORS,
  isDark: true,
  themeMode: 'dark',
  setThemeMode: async () => {},
});

export function ThemeProvider({ children }: { children: ReactNode }) {
  const { user, profile } = useAuth();
  const systemScheme = useColorScheme();
  const [themeMode, setThemeModeState] = useState<ThemeMode>('dark');
  const [colors, setColors] = useState({ ...COLORS });

  const resolvedTheme = useMemo(() => {
    if (themeMode === 'system') return systemScheme || 'dark';
    return themeMode;
  }, [themeMode, systemScheme]);

  useEffect(() => {
    const source = THEMES[resolvedTheme] || THEMES.dark;
    setColors({ ...source });
    // Only update global COLORS for backward compatibility with code that doesn't use Context
    Object.keys(source).forEach(key => {
      if (key in COLORS) COLORS[key as keyof ThemeColors] = source[key as keyof ThemeColors];
    });
    updateWebStyles();
  }, [resolvedTheme]);

  useEffect(() => {
    if (profile?.app_settings?.themeMode) {
      setThemeModeState(profile.app_settings.themeMode as ThemeMode);
    } else if (profile?.app_settings?.darkMode === false) {
      setThemeModeState('light');
    }
  }, [profile?.app_settings]);

  const setThemeMode = useCallback(async (mode: ThemeMode) => {
    setThemeModeState(mode);
    if (user?.id) {
      await supabase
        .from('profiles')
        .update({ app_settings: { ...profile?.app_settings, themeMode: mode, darkMode: mode === 'dark' } })
        .eq('id', user.id);
    }
  }, [user?.id, profile?.app_settings]);

  const value = useMemo(() => ({
    colors,
    isDark: resolvedTheme === 'dark',
    themeMode,
    setThemeMode,
  }), [colors, resolvedTheme, themeMode, setThemeMode]);

  return (
    <ThemeContext.Provider value={value}>
      {children}
    </ThemeContext.Provider>
  );
}

export function useTheme(): ThemeContextType {
  return useContext(ThemeContext);
}

