// Funções e lógicas de catálogo de exercícios - NOVAIX FITNESS

import {
  CatalogExercise,
  DifficultyLevel,
  MuscleGroup,
  EXERCISE_CATALOG,
} from './exerciseData';

export {
  CatalogExercise,
  DifficultyLevel,
  MuscleGroup,
  EXERCISE_CATALOG,
};

export interface ExerciseWithMuscle extends CatalogExercise {
  muscleGroup: string;
}

export interface GetAvailableExercisesParams {
  level?: DifficultyLevel;
  injuries?: string[];
  gymType?: string;
}

export function filterByInjuries(exercises: CatalogExercise[], injuries: string[]): CatalogExercise[] {
  if (!injuries || injuries.length === 0) return exercises;
  return exercises.filter(ex =>
    !ex.injuries_avoid.some(injury => injuries.includes(injury))
  );
}

export function filterByEquipment(exercises: CatalogExercise[], availableEquipment: string[]): CatalogExercise[] {
  if (!availableEquipment || availableEquipment.length === 0) return exercises;
  return exercises.filter(ex =>
    ex.equipment === 'none' || availableEquipment.includes(ex.equipment)
  );
}

export function getExercisesByMuscle(muscle: MuscleGroup, level: DifficultyLevel): CatalogExercise[] {
  return EXERCISE_CATALOG[muscle]?.[level] || [];
}

export function getAvailableExercises({ level = 'intermediate', injuries = [], gymType = 'gym' }: GetAvailableExercisesParams): ExerciseWithMuscle[] {
  const equipment = gymType === 'home' ? ['none', 'dumbbells'] :
    gymType === 'park' ? ['none'] :
    ['barbell', 'dumbbells', 'machine', 'cable', 'bench', 'none'];

  const allExercises: ExerciseWithMuscle[] = [];
  const muscles = Object.keys(EXERCISE_CATALOG);

  for (const muscle of muscles) {
    const levelExercises = EXERCISE_CATALOG[muscle][level as DifficultyLevel] || [];
    const filtered = filterByInjuries(levelExercises, injuries);
    const withEquipment = filterByEquipment(filtered, equipment);
    allExercises.push(...withEquipment.map(ex => ({ ...ex, muscleGroup: muscle })));
  }

  return allExercises;
}

export function getAlternativeExercises(exerciseName: string, availableEquipment: string[] = []): CatalogExercise[] {
  let muscleGroup: MuscleGroup | null = null;
  let originalExercise: CatalogExercise | null = null;

  for (const [group, levels] of Object.entries(EXERCISE_CATALOG)) {
    for (const [level, exercises] of Object.entries(levels)) {
      const found = exercises.find(ex => ex.name.toLowerCase() === exerciseName.toLowerCase());
      if (found) {
        muscleGroup = group as MuscleGroup;
        originalExercise = found;
        break;
      }
    }
    if (muscleGroup) break;
  }

  if (!muscleGroup || !originalExercise) return [];

  const allForMuscle: CatalogExercise[] = [];
  const levels = EXERCISE_CATALOG[muscleGroup];
  for (const exercises of Object.values(levels)) {
    allForMuscle.push(...exercises);
  }

  const uniqueExercises = allForMuscle.filter((ex, index, self) =>
    self.findIndex(e => e.name.toLowerCase() === ex.name.toLowerCase()) === index &&
    ex.name.toLowerCase() !== exerciseName.toLowerCase()
  );

  if (availableEquipment.length > 0) {
    return uniqueExercises.filter(ex =>
      ex.equipment === 'none' || availableEquipment.includes(ex.equipment)
    );
  }

  return uniqueExercises;
}

