  handleClearChat: () => void;
}

export function useChatCoach(user: SupabaseUser | null, router: Router): UseChatCoachReturn {
  const [messages, setMessages] = useState<any[]>([]);
  const [inputText, setInputText] = useState<string>('');
  const [profile, setProfile] = useState<Profile | null>(null);
  const [loading, setLoading] = useState<boolean>(false);
  const [historyLoaded, setHistoryLoaded] = useState<boolean>(false);
  const flatListRef = useRef<unknown>(null);

  useEffect(() => {
    async function init(): Promise<void> {
      if (!user?.id) return;
      try {
        const { data } = await supabase.from('profiles').select('*').eq('id', user.id).single();
        if (data) {
          setProfile(data as Profile);
          const isAllowedPlan = ['intermediate', 'premium', 'ultra'].includes(data.subscription_plan);
          const hasActiveSub = data.subscription_status === 'active';
          if (!isAllowedPlan || !hasActiveSub) {
            Alert.alert(
              'Acesso Restrito',
              'O Coach IA esta disponivel apenas para assinantes dos planos Intermediario, Premium e Ultra Premium com assinatura ativa.',
              [
                { text: 'Voltar', onPress: () => router.back() },
                { text: 'Ver Planos', onPress: () => { router.back(); router.push('/paywall'); } },
              ],
              { cancelable: false },
            );
            return;
          }
        }
        const history = await getChatHistory(user.id);
        if (history.length > 0) {
          setMessages(history);
        } else {
          const welcome = createWelcomeMessage(data?.name || 'Atleta');
          setMessages([welcome]);
          await saveChatMessage(user.id, welcome.text, false);
        }
      } catch (err) {
        if (__DEV__) console.error('Erro ao carregar chat:', err);
      } finally {
        setHistoryLoaded(true);
      }
    }
    init();
  }, [user?.id]);

  const handleSend = useCallback(async (text?: string): Promise<void> => {
    const msg = (text || inputText).trim();
    if (!msg || loading) return;
    setInputText('');
    const userMsg = createUserMessage(msg);
    setMessages(prev => [...prev, userMsg]);
    setLoading(true);
    await saveChatMessage(user.id, msg, true);

    if (detectMealLog(msg)) {
      try {
        const context = buildChatContext(profile);
        (context as any).userId = user.id;
        const mealData = await analyzeMealText(msg, context);
        if (mealData) {
          await saveMealLog(user.id, mealData);
          const summary = formatMealSummary(mealData);
          const coachMsg = createCoachMessage(summary, { isMealCard: true, mealData });
          setMessages(prev => [...prev, coachMsg]);
          await saveChatMessage(user.id, summary, false);
          setLoading(false);
          return;
        }
      } catch (e) { if (__DEV__) console.warn('useChatCoach mealLog:', e); }
    }

    try {
      const context = buildChatContext(profile);
      (context as any).userId = user.id;
      const reply = await askGeminiCoach(msg, context, messages);
      setMessages(prev => [...prev, createCoachMessage(reply)]);
      await saveChatMessage(user.id, reply, false);
    } catch (err) {
      if ((err as Error).message === 'LIMIT_EXCEEDED') {
        setMessages(prev => prev.filter(m => m.id !== userMsg.id));
        await cleanupLimitExceededMessage(user, msg, supabase);
        Alert.alert('Limite Excedido', 'Voce atingiu seu limite diario de mensagens do Coach IA. Faca um upgrade para enviar mais mensagens!', [
          { text: 'OK' },
          { text: 'Ver Planos', onPress: () => router.push('/paywall') },
        ]);
      } else if ((err as Error).message === 'API_KEY_MISSING') {
        setMessages(prev => [...prev, createCoachMessage('Configure a chave de API do Google para usar o Coach IA.')]);
      } else {
        setMessages(prev => [...prev, createCoachMessage('Erro ao conectar com o assistente. Verifique sua conexao e tente novamente.')]);
        if (__DEV__) console.error('Erro ao enviar mensagem:', err);
      }
    } finally {
      setLoading(false);
    }
  }, [user?.id, inputText, loading, profile, messages, router]);

  const handleClearChat = useCallback((): void => {
    Alert.alert('Limpar historico', 'Apagar todas as mensagens?', [
      { text: 'Cancelar', style: 'cancel' },
      {
        text: 'Limpar', style: 'destructive',
        onPress: async () => {
          await clearChatHistory(user.id);
          const welcome = createWelcomeMessage('Historico limpo!');
          welcome.text = 'Historico limpo! Em como posso ajudar?';
          setMessages([welcome]);
          await saveChatMessage(user.id, welcome.text, false);
        },
      },
    ]);
  }, [user?.id]);

  return { messages, inputText, setInputText, loading, historyLoaded, flatListRef, handleSend, handleClearChat };
}

// Hook para debounce de valores - NOVAIX FITNESS

import { useState, useEffect } from 'react';

export function useDebounce<T>(value: T, delay: number = 300): T {
  const [debounced, setDebounced] = useState<T>(value);

  useEffect(() => {
    const timer = setTimeout(() => setDebounced(value), delay);
    return () => clearTimeout(timer);
  }, [value, delay]);

  return debounced;
}

export function useDebouncedCallback<T extends (...args: unknown[]) => void>(
  callback: T,
  delay: number = 300,
): (...args: Parameters<T>) => void {
  const [timer, setTimer] = useState<ReturnType<typeof setTimeout> | null>(null);

  return (...args: Parameters<T>): void => {
    if (timer) clearTimeout(timer);
    const newTimer = setTimeout(() => callback(...args), delay);
    setTimer(newTimer);
  };
}

// src/hooks/useErrorBoundary.ts
// Hook para Error Boundary customizado - NOVAIX FITNESS

import { useState, useCallback, type ComponentType, type ReactNode } from 'react';
import React from 'react';
import { errorTracker, ERROR_SEVERITY } from '../services/errorTracker';

interface ErrorInfo {
  componentStack?: string | null;
}

export function useErrorBoundary() {
  const [error, setError] = useState<Error | null>(null);
  const [errorInfo, setErrorInfo] = useState<ErrorInfo | null>(null);

  const captureError = useCallback((err: Error, info: ErrorInfo | null = null) => {
    setError(err);
    setErrorInfo(info);

    errorTracker.trackError(err, {
      componentStack: info?.componentStack,
      type: 'react_error_boundary',
    }, ERROR_SEVERITY.HIGH);
  }, []);

  const resetError = useCallback(() => {
    setError(null);
    setErrorInfo(null);
  }, []);

  const capturePromiseError = useCallback((promise: Promise<unknown>, context: Record<string, unknown> = {}) => {
    return promise.catch((err) => {
      errorTracker.trackError(err instanceof Error ? err : new Error(String(err)), {
        ...context,
        type: 'unhandled_promise',
      }, ERROR_SEVERITY.HIGH);
      throw err;
    });
  }, []);

  return {
    error,
    errorInfo,
    captureError,
    resetError,
    capturePromiseError,
    hasError: error !== null,
  };
}

interface FallbackProps {
  error: Error;
  resetError: () => void;
}

export function withErrorBoundary<P extends Record<string, unknown>>(
  Component: ComponentType<P & { onError: (err: Error) => void }>,
  FallbackComponent?: ComponentType<FallbackProps>
) {
  return function ErrorBoundaryWrapper(props: P) {
    const { error, captureError, resetError } = useErrorBoundary();

    if (error) {
      return FallbackComponent ? (
        React.createElement(FallbackComponent, { error, resetError })
      ) : null;
    }

    return React.createElement(Component, { ...props, onError: captureError });
  };
}

// Hook de gerenciamento de dados e interações do Feed - NOVAIX FITNESS

import { useState, useEffect, useCallback, useMemo } from 'react';
import { Alert } from 'react-native';
import { supabase } from '../config/supabase';
import { useAuth } from '../context/AuthContext';
import { useRealtimePosts } from './useRealtimePosts';
import { formatRelativeDate } from '../helpers/dates';
import { mapDbPostToFeed, buildNewPostEntry, computePopularThreshold, filterFeedPosts } from './helpers/feedHelpers';

const PAGE_SIZE = 10;

export interface FeedPost {
  id: string;
  userId: string;
  user: { name: string; avatar: string | null };
  content: string;
  image: string | null;
  createdAt: string;
  likes: number;
  comments: number;
  isLiked: boolean;
  [key: string]: unknown;
}

interface NewPostData {
  content: string;
  image?: string;
}

interface UseFeedDataReturn {
  user: ReturnType<typeof useAuth>['user'];
  loading: boolean;
  loadingMore: boolean;
  refreshing: boolean;
  onRefresh: () => Promise<void>;
  loadMore: () => Promise<void>;
  hasMore: boolean;
  selectedFilter: string;
  setSelectedFilter: (filter: string) => void;
  showCreatePost: boolean;
  setShowCreatePost: (val: boolean) => void;
  hasNotif: boolean;
  setHasNotif: (val: boolean) => void;
  showNotifications: boolean;
  setShowNotifications: (val: boolean) => void;
  filteredPosts: FeedPost[];
  showEmpty: boolean;
  handleLike: (postId: string) => Promise<void>;
  handleNewPost: (postData: NewPostData) => Promise<void>;
  handleComment: (postId: string, text: string) => Promise<void>;
}

export function useFeedData(): UseFeedDataReturn {
  const { user } = useAuth();
  const [posts, setPosts] = useState<FeedPost[]>([]);
  const [likedPostIds, setLikedPostIds] = useState<Set<string>>(new Set());
  const [selectedFilter, setSelectedFilter] = useState<string>('Todos');
  const [showCreatePost, setShowCreatePost] = useState<boolean>(false);
  const [refreshing, setRefreshing] = useState<boolean>(false);
  const [loading, setLoading] = useState<boolean>(true);
  const [loadingMore, setLoadingMore] = useState<boolean>(false);
  const [hasMore, setHasMore] = useState<boolean>(true);
  const [page, setPage] = useState<number>(0);
  const [hasNotif, setHasNotif] = useState<boolean>(true);
  const [showNotifications, setShowNotifications] = useState<boolean>(false);

  const fetchPosts = useCallback(async (pageNum: number = 0, append: boolean = false): Promise<void> => {
    try {
      const from = pageNum * PAGE_SIZE;
      const to = from + PAGE_SIZE - 1;

      const { data, error } = await supabase
        .from('posts')
        .select('*, profiles:user_id(name, avatar_url)')
        .order('created_at', { ascending: false })
        .range(from, to);

      if (error) throw error;

      const mapped: FeedPost[] = (data || []).map((p: Record<string, unknown>) => ({
        ...mapDbPostToFeed(p as any, likedPostIds),
        createdAt: formatRelativeDate(p.created_at as string),
      })) as FeedPost[];

      if (append) {
        setPosts(prev => [...prev, ...mapped]);
      } else {
        setPosts(mapped);
      }

      setHasMore(data?.length === PAGE_SIZE);
    } catch (err) {
      if (__DEV__) console.error('Erro ao buscar posts:', err);
    }
  }, [likedPostIds]);

  useEffect(() => {
    async function loadInitialPosts() {
      setLoading(true);
      try {
        await fetchPosts(0, false);
      } catch {}
      setLoading(false);
    }
    loadInitialPosts();
  }, [fetchPosts]);

  useEffect(() => {
    if (!user?.id) return;
    async function loadLikes() {
      try {
        const { data } = await supabase.from('post_likes').select('post_id').eq('user_id', user.id!);
        if (data) setLikedPostIds(new Set(data.map((l: { post_id: string }) => l.post_id)));
      } catch {}
    }
    loadLikes();
  }, [user?.id]);

  const loadMore = useCallback(async (): Promise<void> => {
    if (loadingMore || !hasMore) return;
    setLoadingMore(true);
    const nextPage = page + 1;
    setPage(nextPage);
    await fetchPosts(nextPage, true);
    setLoadingMore(false);
  }, [page, loadingMore, hasMore, fetchPosts]);

  const handleRealtimeInsert = useCallback((newPost: FeedPost): void => {
    setPosts(prev => prev.some(p => p.id === newPost.id) ? prev : [newPost, ...prev]);
  }, []);
  const handleRealtimeUpdate = useCallback((update: { id: string; likes: number; comments: number }): void => {
    setPosts(prev => prev.map(p => p.id === update.id ? { ...p, likes: update.likes, comments: update.comments } : p));
  }, []);
  const handleRealtimeDelete = useCallback((postId: string): void => {
    setPosts(prev => prev.filter(p => p.id !== postId));
  }, []);
  useRealtimePosts(handleRealtimeInsert, handleRealtimeUpdate, handleRealtimeDelete);

  const onRefresh = async (): Promise<void> => {
    setRefreshing(true);
    setPage(0);
    await fetchPosts(0, false);
    setRefreshing(false);
  };

  const handleLike = async (postId: string): Promise<void> => {
    if (!user) return;
    try {
      const { data: ext } = await supabase.from('post_likes').select('id').eq('post_id', postId).eq('user_id', user.id).single();
      if (ext) {
        await supabase.from('post_likes').delete().eq('id', ext.id);
        setLikedPostIds(prev => { const s = new Set(prev); s.delete(postId); return s; });
        setPosts(prev => prev.map(p => p.id === postId ? { ...p, isLiked: false, likes: Math.max(0, p.likes - 1) } : p));
      } else {
        await supabase.from('post_likes').insert({ post_id: postId, user_id: user.id });
        setLikedPostIds(prev => new Set([...prev, postId]));
        setPosts(prev => prev.map(p => p.id === postId ? { ...p, isLiked: true, likes: p.likes + 1 } : p));
      }
    } catch (err) { if (__DEV__) console.error(err); }
  };

  const handleNewPost = async (postData: any): Promise<void> => {
    if (!user) return;
    try {
      const dbContent = (postData.feeling || postData.location || postData.workout)
        ? JSON.stringify({ text: postData.content, feeling: postData.feeling, location: postData.location, workout: postData.workout })
        : postData.content;
      const { data, error } = await supabase.from('posts')
        .insert({ user_id: user.id, content: dbContent, image_url: postData.image })
        .select('*, profiles:user_id(name, avatar_url)').single();
      if (error) throw error;
      setPosts(prev => [buildNewPostEntry(data) as any, ...prev]);
    } catch (err) {
      Alert.alert('Erro', 'Não foi possível publicar seu post: ' + (err as Error).message);
    }
  };

  const handleComment = async (postId: string, text: string): Promise<void> => {
    if (!user) return;
    try {
      const { error } = await supabase.from('post_comments').insert({ post_id: postId, user_id: user.id, content: text });
      if (error) throw error;
      setPosts(prev => prev.map(p => p.id === postId ? { ...p, comments: p.comments + 1 } : p));
    } catch (err) {
      Alert.alert('Erro', 'Não foi possível enviar o comentário: ' + (err as Error).message);
    }
  };

  const popularThreshold: number = useMemo(() => computePopularThreshold(posts), [posts]);
  const filteredPosts: FeedPost[] = useMemo(() => filterFeedPosts(posts, selectedFilter, popularThreshold, user?.id) as FeedPost[], [posts, selectedFilter, popularThreshold, user?.id]);
  const showEmpty: boolean = !loading && filteredPosts.length === 0;

  return {
    user, loading, loadingMore, refreshing, onRefresh, loadMore, hasMore,
    selectedFilter, setSelectedFilter,
    showCreatePost, setShowCreatePost,
    hasNotif, setHasNotif,
    showNotifications, setShowNotifications,
    filteredPosts, showEmpty,
    handleLike, handleNewPost, handleComment,
  };
}

// Hook de gamificação - NOVAIX FITNESS

import { useState, useEffect, useCallback } from 'react';
import { useAuth } from '../context/AuthContext';
import {
  awardXP,
  checkAchievements,
  getRankings,
  getUserRank,
  getUserAchievements,
  calculateLevel,
  getXPForNextLevel,
  getLevelProgress,
  getUserGamificationProfile,
} from '../services/gamification';
import { Achievement } from '../types';

interface GamificationProfile {
  xp: number;
  [key: string]: unknown;
}

interface UserRank {
  rank: number;
  [key: string]: unknown;
}

interface AwardResult {
  xpGained?: number;
  [key: string]: unknown;
}

interface UseGamificationReturn {
  profile: GamificationProfile | null;
  achievements: Achievement[];
  rankings: unknown[];
  userRank: UserRank | null;
  loading: boolean;
  award: (eventType: string, metadata?: Record<string, unknown>) => Promise<AwardResult | null>;
  refresh: () => void;
  level: number;
  xpForNext: number;
  levelProgress: number;
  data?: GamificationProfile | null;
  refreshing?: boolean;
  error?: string | null;
  onRefresh?: () => void;
}

interface UseAchievementsReturn {
  achievements: Achievement[];
  loading: boolean;
}

interface UseRankingsReturn {
  rankings: unknown[];
  loading: boolean;
}

export function useGamification(): UseGamificationReturn {
  const { user } = useAuth();
  const [profile, setProfile] = useState<GamificationProfile | null>(null);
  const [achievements, setAchievements] = useState<Achievement[]>([]);
  const [rankings, setRankings] = useState<unknown[]>([]);
  const [userRank, setUserRank] = useState<UserRank | null>(null);
  const [loading, setLoading] = useState<boolean>(true);

  useEffect(() => {
    if (!user?.id) return;
    loadData();
  }, [user?.id]);

  async function loadData(): Promise<void> {
    setLoading(true);
    try {
      const [rankData, achievementsData, rank, profileData] = await Promise.all([
        getRankings('weekly'),
        getUserAchievements(user.id),
        getUserRank(user.id),
        getUserGamificationProfile(user.id),
      ]);
      setRankings(rankData);
      setAchievements(achievementsData as any);
      setUserRank(rank);
      setProfile(profileData);
    } catch (err) {
      if (__DEV__) console.warn('Erro ao carregar gamificacao:', err);
    }
    setLoading(false);
  }

  const award = useCallback(async (eventType: string, metadata: Record<string, unknown> = {}): Promise<AwardResult | null> => {
    if (!user?.id) return null;
    const result = await awardXP(user.id, eventType, metadata);
    const newAchievements = await checkAchievements(user.id);
    if (newAchievements.length > 0) {
      setAchievements(prev => [...prev, ...newAchievements.map((a: any) => ({ ...a, unlocked: true }))]);
    }
    return result;
  }, [user?.id]);

  const refresh = useCallback((): void => { loadData(); }, [user?.id]);

  return {
    profile,
    achievements,
    rankings,
    userRank,
    loading,
    award,
    refresh,
    level: calculateLevel(profile?.xp || 0),
    xpForNext: getXPForNextLevel(profile?.xp || 0),
    levelProgress: getLevelProgress(profile?.xp || 0),
  };
}

export function useAchievements(): UseAchievementsReturn {
  const { user } = useAuth();
  const [achievements, setAchievements] = useState<Achievement[]>([]);
  const [loading, setLoading] = useState<boolean>(true);

  useEffect(() => {
    if (!user?.id) return;
    getUserAchievements(user.id)
      .then(data => setAchievements(data as any))
      .catch((err) => { if (__DEV__) console.error('Erro ao carregar conquistas:', err); })
      .finally(() => setLoading(false));
  }, [user?.id]);

  return { achievements, loading };
}

export function useRankings(period: string = 'weekly'): UseRankingsReturn {
  const [rankings, setRankings] = useState<unknown[]>([]);
  const [loading, setLoading] = useState<boolean>(true);

  useEffect(() => {
    setLoading(true);
    getRankings(period)
      .then(setRankings)
      .catch(() => {})
      .finally(() => setLoading(false));
  }, [period]);

  return { rankings, loading };
}

// src/hooks/useGoals.ts
// Hook de metas de curto prazo - NOVAIX FITNESS

import { useState, useEffect, useCallback } from 'react';
import { supabase } from '../config/supabase';
import { useAuth } from '../context/AuthContext';
import { GOAL_TYPES, getUnlockedAchievements } from '../data/achievements';
import type { Achievement } from '../types';

interface Goal {
  id: string;
  user_id: string;
  goal_type: string;
  target_value: number;
  target_unit: string;
  target_days: number;
  completed: boolean;
  created_at: string;
  [key: string]: unknown;
}

interface GoalStats {
  totalWorkouts: number;
  streak: number;
  totalMeals: number;
  waterStreak: number;
  totalXp: number;
}

export function useGoals() {
  const { user } = useAuth();
  const [goals, setGoals] = useState<Goal[]>([]);
  const [unlocked, setUnlocked] = useState<string[]>([]);
  const [stats, setStats] = useState<GoalStats>({
    totalWorkouts: 0, streak: 0, totalMeals: 0, waterStreak: 0, totalXp: 0,
  });
  const [showAddModal, setShowAddModal] = useState(false);
  const [newGoalType, setNewGoalType] = useState<string | null>(null);
  const [newGoalTarget, setNewGoalTarget] = useState('');

  const loadData = useCallback(async () => {
    if (!user?.id) return;
    const { data: goalsData } = await supabase.from('short_term_goals')
      .select('*').eq('user_id', user.id).eq('completed', false)
      .order('created_at', { ascending: false });
    setGoals((goalsData || []) as Goal[]);

    const { data: unlockedData } = await supabase.from('user_achievements')
      .select('achievement_id').eq('user_id', user.id);
    setUnlocked(unlockedData?.map(a => a.achievement_id as string) || []);

    const { data: workouts } = await supabase.from('user_workouts')
      .select('id, completed_at').eq('user_id', user.id).eq('completed', true);
    const { data: profile } = await supabase.from('profiles')
      .select('total_xp').eq('id', user.id).single();
    setStats({
      totalWorkouts: workouts?.length || 0,
      streak: 0, totalMeals: 0, waterStreak: 0,
      totalXp: profile?.total_xp || 0,
    });
  }, [user?.id]);

  useEffect(() => { loadData(); }, [loadData]);

  const addGoal = useCallback(async () => {
    if (!newGoalType || !newGoalTarget) return;
    const goalType = GOAL_TYPES.find(g => g.id === newGoalType);
    await supabase.from('short_term_goals').insert({
      user_id: user.id, goal_type: newGoalType,
      target_value: parseFloat(newGoalTarget),
      target_unit: goalType?.unit, target_days: 30,
    });
    setNewGoalType(null);
    setNewGoalTarget('');
    setShowAddModal(false);
    loadData();
  }, [newGoalType, newGoalTarget, user?.id, loadData]);

  const unlockedNow = getUnlockedAchievements(stats);
  const newAchievements = unlockedNow.filter((a: any) => !unlocked.includes(a.id));

  return {
    goals, unlocked, stats, newAchievements, showAddModal,
    setShowAddModal, newGoalType, setNewGoalType,
    newGoalTarget, setNewGoalTarget, addGoal,
  };
}

