// Realtime subscription para comentários de um post - NOVAIX FITNESS

import { useEffect, useRef } from 'react';
import { supabase } from '../config/supabase';
import { PostComment } from '../types';

type OnNewCommentFn = (comment: PostComment) => void;

export function useRealtimeComments(postId: string, onNewComment?: OnNewCommentFn): void {
  const callbackRef = useRef<OnNewCommentFn | undefined>(onNewComment);
  callbackRef.current = onNewComment;

  useEffect(() => {
    if (!postId) return;

    const channel = supabase
      .channel(`comments-${postId}`)
      .on('postgres_changes', {
        event: 'INSERT',
        schema: 'public',
        table: 'post_comments',
        filter: `post_id=eq.${postId}`,
      }, async (payload) => {
        const { data } = await supabase
          .from('post_comments')
          .select('*, profiles:user_id(name, avatar_url)')
          .eq('id', payload.new.id)
          .single();
        if (data) callbackRef.current?.(data as PostComment);
      })
      .subscribe();

    return () => { supabase.removeChannel(channel); };
  }, [postId]);
}

