// Realtime subscription para likes de um post - NOVAIX FITNESS

import { useEffect, useRef } from 'react';
import { supabase } from '../config/supabase';

type OnLikeAddedFn = (postId: string, isOwn: boolean) => void;
type OnLikeRemovedFn = (postId: string) => void;

interface UseRealtimeLikesOptions {
  onLikeAdded?: OnLikeAddedFn;
  onLikeRemoved?: OnLikeRemovedFn;
  currentUserId?: string;
}

export function useRealtimeLikes(postId: string, { onLikeAdded, onLikeRemoved, currentUserId }: UseRealtimeLikesOptions): void {
  const callbacksRef = useRef<{ onLikeAdded?: OnLikeAddedFn; onLikeRemoved?: OnLikeRemovedFn; currentUserId?: string }>({ onLikeAdded, onLikeRemoved, currentUserId });
  callbacksRef.current = { onLikeAdded, onLikeRemoved, currentUserId };

  useEffect(() => {
    if (!postId) return;

    const channel = supabase
      .channel(`likes-${postId}`)
      .on('postgres_changes', {
        event: 'INSERT',
        schema: 'public',
        table: 'post_likes',
        filter: `post_id=eq.${postId}`,
      }, (payload) => {
        const isOwn = payload.new.user_id === callbacksRef.current.currentUserId;
        callbacksRef.current.onLikeAdded?.(postId, isOwn);
      })
      .on('postgres_changes', {
        event: 'DELETE',
        schema: 'public',
        table: 'post_likes',
        filter: `post_id=eq.${postId}`,
      }, () => {
        callbacksRef.current.onLikeRemoved?.(postId);
      })
      .subscribe();

    return () => { supabase.removeChannel(channel); };
  }, [postId]);
}

