// Realtime subscription para tabela posts - NOVAIX FITNESS

import { useEffect, useRef, useCallback } from 'react';
import { supabase } from '../config/supabase';

const SELECT = '*, profiles:user_id(name, avatar_url)';

interface RealtimePostUser {
  name: string;
  avatar: string | null;
}

interface FeedPost {
  id: string;
  userId: string;
  user: RealtimePostUser;
  content: string;
  image: string | null;
  createdAt: string;
  likes: number;
  comments: number;
  isLiked: boolean;
}

interface PostUpdate {
  id: string;
  likes: number;
  comments: number;
}

type OnInsertFn = (post: FeedPost) => void;
type OnUpdateFn = (update: PostUpdate) => void;
type OnDeleteFn = (postId: string) => void;

interface UseRealtimePostsReturn {
  refreshPost: (postId: string) => Promise<FeedPost | null>;
}

function formatPost(p: Record<string, unknown>): FeedPost {
  const profiles = p.profiles as { name?: string; avatar_url?: string } | null;
  return {
    id: p.id as string,
    userId: p.user_id as string,
    user: { name: profiles?.name || 'Atleta', avatar: profiles?.avatar_url || null },
    content: p.content as string,
    image: p.image_url as string | null,
    createdAt: 'Agora',
    likes: (p.likes_count as number) || 0,
    comments: (p.comments_count as number) || 0,
    isLiked: false,
  };
}

export function useRealtimePosts(
  onInsert?: OnInsertFn,
  onUpdate?: OnUpdateFn,
  onDelete?: OnDeleteFn,
): UseRealtimePostsReturn {
  const callbacksRef = useRef<{ onInsert?: OnInsertFn; onUpdate?: OnUpdateFn; onDelete?: OnDeleteFn }>({ onInsert, onUpdate, onDelete });
  callbacksRef.current = { onInsert, onUpdate, onDelete };

  useEffect(() => {
    const channel = supabase
      .channel('posts-realtime')
      .on('postgres_changes', { event: 'INSERT', schema: 'public', table: 'posts' }, async (payload) => {
        const { data } = await supabase.from('posts').select(SELECT).eq('id', payload.new.id).single();
        if (data) callbacksRef.current.onInsert?.(formatPost(data as Record<string, unknown>));
      })
      .on('postgres_changes', { event: 'UPDATE', schema: 'public', table: 'posts' }, (payload) => {
        callbacksRef.current.onUpdate?.({
          id: payload.new.id,
          likes: (payload.new.likes_count as number) || 0,
          comments: (payload.new.comments_count as number) || 0,
        });
      })
      .on('postgres_changes', { event: 'DELETE', schema: 'public', table: 'posts' }, (payload) => {
        callbacksRef.current.onDelete?.(payload.old.id);
      })
      .subscribe();

    return () => { supabase.removeChannel(channel); };
  }, []);

  return { refreshPost: useCallback(async (postId: string): Promise<FeedPost | null> => {
    const { data } = await supabase.from('posts').select(SELECT).eq('id', postId).single();
    return data ? formatPost(data as Record<string, unknown>) : null;
  }, []) };
}

