import { useWindowDimensions, Platform } from 'react-native';

export function useResponsive() {
  const { width, height } = useWindowDimensions();

  return {
    width,
    height,
    isSmall: width < 380,
    isMedium: width >= 380 && width < 768,
    isLarge: width >= 768,
    isPortrait: height > width,

    // Espacamento responsivo
    horizontalPadding: width < 380 ? 16 : 20,
    sectionGap: width < 380 ? 12 : 16,

    // Dimensoes de cards
    cardWidth: (width - 40) / 2 - 8,
    categoryCardWidth: (width - 48) / 2,

    // FAB responsivo
    fabBottom: Math.min(height * 0.12, 100),
    fabRight: width < 380 ? 12 : 20,
    fabSize: width < 380 ? 48 : 56,

    // Icones responsivos
    iconSize: width < 380 ? 18 : 22,
    headerIconSize: width < 380 ? 20 : 24,

    // Fontes responsivas
    titleSize: width < 380 ? 20 : 24,
    bodySize: width < 380 ? 13 : 14,
  };
}

// Hook de segurança completo: bloqueios, moderação, conteúdo

import { useState, useCallback } from 'react';
import { Alert } from 'react-native';
import { canPerformAction, logAction, ACTIONS, isBlocked } from '../services/security';
import { moderateText, moderateImage, moderateUsername, preModerateContent } from '../services/contentModeration';
import { useAuth } from '../context/AuthContext';

interface BlockInfo {
  blocked: boolean;
  blockSeverity?: string;
  blockReason?: string;
  rateLimited?: boolean;
  [key: string]: unknown;
}

interface ModerationResult {
  allowed: boolean;
  blocked?: boolean;
  warning?: boolean;
  message?: string;
  clean?: boolean;
  warned?: boolean;
  [key: string]: unknown;
}

interface SecurityCheck {
  blocked: boolean;
  rateLimited: boolean;
  blockSeverity?: string;
  blockReason?: string;
  [key: string]: unknown;
}

interface UseSecurityReturn {
  checkAndPerform: (_actionType: string, _blockType: string, _actionFn: () => Promise<void>, _errorMessage?: string) => Promise<boolean>;
  checkBlock: (_blockType: string) => Promise<BlockInfo | null>;
  log: (_action: string, _entityType: string, _entityId: string, _details?: Record<string, unknown>) => Promise<void>;
  checkText: (_text: string) => ModerationResult;
  checkImage: (_file: unknown) => ModerationResult;
  checkUsername: (_username: string) => ModerationResult;
  checkContent: (_contentType: string, _content: string) => Promise<ModerationResult>;
  getCensoredText: (_text: string) => string;
  blocked: BlockInfo | null;
  clearBlocked: () => void;
  ACTIONS: typeof ACTIONS;
}

export function useSecurity(): UseSecurityReturn {
  const { user } = useAuth();
  const [blocked, setBlocked] = useState<BlockInfo | null>(null);

  const checkAndPerform = useCallback(async (
    actionType: string,
    blockType: string,
    actionFn: () => Promise<void>,
    errorMessage?: string,
  ): Promise<boolean> => {
    if (!user?.id) return false;

    const check: SecurityCheck = await canPerformAction(user.id, actionType, blockType) as any;

    if (check.blocked) {
      setBlocked(check as BlockInfo);
      Alert.alert(
        'Conta Bloqueada',
        check.blockSeverity === 'permanent'
          ? `Sua conta foi bloqueada permanentemente.\n\nMotivo: ${check.blockReason}`
          : `Sua conta está bloqueada temporariamente.\n\nMotivo: ${check.blockReason}\n\nTente novamente mais tarde.`,
        [{ text: 'OK' }]
      );
      return false;
    }

    if (check.rateLimited) {
      Alert.alert(
        'Muitas ações',
        'Você está fazendo muitas ações rapidamente. Aguarde alguns minutos.',
        [{ text: 'OK' }]
      );
      return false;
    }

    try {
      await actionFn();
      return true;
    } catch (_err) {
      if (errorMessage) {
        Alert.alert('Erro', errorMessage);
      }
      return false;
    }
  }, [user?.id]);

  const checkBlock = useCallback(async (blockType: string): Promise<BlockInfo | null> => {
    if (!user?.id) return null;
    const result = await isBlocked(user.id, blockType);
    setBlocked(result.blocked ? (result as any) : null);
    return result as any;
  }, [user?.id]);

  const log = useCallback(async (action: string, entityType: string, entityId: string, details?: Record<string, unknown>): Promise<void> => {
    if (!user?.id) return;
    await logAction(user.id, action, entityType, entityId, details);
  }, [user?.id]);

  const checkText = useCallback((text: string): ModerationResult => {
    const result = moderateText(text, user?.id);

    if (result.blocked) {
      Alert.alert('Conteúdo Bloqueado', result.message, [{ text: 'OK' }]);
      return { allowed: false, ...result };
    }

    if (result.warning) {
      Alert.alert('Atenção', result.message, [
        { text: 'Cancelar', style: 'cancel' },
        { text: 'Publicar Mesmo Assim', onPress: () => {} },
      ]);
      return { allowed: true, warned: true, ...result };
    }

    return { allowed: true, clean: true };
  }, [user?.id]);

  const checkImage = useCallback((file: unknown): ModerationResult => {
    const result = moderateImage(file, user?.id);

    if (result.blocked) {
      Alert.alert('Imagem Bloqueada', result.message, [{ text: 'OK' }]);
      return { allowed: false, ...result };
    }

    return { allowed: true, clean: true };
  }, [user?.id]);

  const checkUsername = useCallback((username: string): ModerationResult => {
    const result = moderateUsername(username);

    if (!result.allowed) {
      Alert.alert('Nome Inválido', result.message, [{ text: 'OK' }]);
      return { allowed: false, ...result };
    }

    return { allowed: true };
  }, []);

  const checkContent = useCallback(async (contentType: string, content: string): Promise<ModerationResult> => {
    if (!user?.id) return { allowed: true };
    return preModerateContent(user.id, contentType as any, content) as any;
  }, [user?.id]);

  const getCensoredText = useCallback((text: string): string => {
    const { censorText } = require('../data/bannedWords');
    return censorText(text);
  }, []);

  return {
    checkAndPerform,
    checkBlock,
    log,
    checkText,
    checkImage,
    checkUsername,
    checkContent,
    getCensoredText,
    blocked,
    clearBlocked: () => setBlocked(null),
    ACTIONS,
  };
}

export default useSecurity;

// src/hooks/useSocial.ts
// Hook de features sociais - NOVAIX FITNESS

import { useState, useEffect, useCallback } from 'react';
import { useAuth } from '../context/AuthContext';
import type { Post, PostComment } from '../types';
import {
  getFeed,
  createPost,
  deletePost,
  toggleLike,
  getComments,
  addComment,
  followUser,
  unfollowUser,
  isFollowing,
  getFollowers,
  shareWorkout,
  getTrendingPosts,
  searchUsers,
} from '../services/social';

interface UserSearchResult {
  id: string;
  name: string;
  avatar_url: string | null;
  level: number;
}

export function useSocialFeed() {
  const { user } = useAuth();
  const [posts, setPosts] = useState<Post[]>([]);
  const [loading, setLoading] = useState(true);
  const [refreshing, setRefreshing] = useState(false);
  const [page, setPage] = useState(0);
  const [hasMore, setHasMore] = useState(true);

  const fetchPosts = useCallback(async (pageNum: number = 0, append: boolean = false) => {
    try {
      const data = await getFeed(user?.id, pageNum);
      if (append) {
        setPosts(prev => [...prev, ...data]);
      } else {
        setPosts(data);
      }
      setHasMore(data.length === 20);
    } catch (err) {
      if (__DEV__) console.warn('Erro ao buscar feed:', err);
    }
  }, [user?.id]);

  useEffect(() => {
    setLoading(true);
    fetchPosts(0).finally(() => setLoading(false));
  }, [fetchPosts]);

  const refresh = useCallback(async () => {
    setRefreshing(true);
    setPage(0);
    await fetchPosts(0);
    setRefreshing(false);
  }, [fetchPosts]);

  const loadMore = useCallback(async () => {
    if (!hasMore || loading) return;
    const nextPage = page + 1;
    setPage(nextPage);
    await fetchPosts(nextPage, true);
  }, [page, hasMore, loading, fetchPosts]);

  const handlePost = useCallback(async (content: string, imageUrl: string | null) => {
    const newPost = await createPost(user.id, content, imageUrl);
    setPosts(prev => [newPost, ...prev]);
    return newPost;
  }, [user?.id]);

  const handleDelete = useCallback(async (postId: string) => {
    await deletePost(postId, user.id);
    setPosts(prev => prev.filter(p => p.id !== postId));
  }, [user?.id]);

  const handleLike = useCallback(async (postId: string) => {
    const isLiked = await toggleLike(postId, user.id);
    setPosts(prev => prev.map(p =>
      p.id === postId
        ? { ...p, isLiked, likesCount: (p.likesCount || 0) + (isLiked ? 1 : -1) }
        : p
    ));
    return isLiked;
  }, [user?.id]);

  return {
    posts,
    loading,
    refreshing,
    refresh,
    loadMore,
    hasMore,
    handlePost,
    handleDelete,
    handleLike,
  };
}

export function usePostComments(postId: string | null) {
  const { user } = useAuth();
  const [comments, setComments] = useState<PostComment[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    if (!postId) return;
    getComments(postId)
      .then(setComments)
      .catch((err) => { if (__DEV__) console.error('Erro ao carregar comentários:', err); })
      .finally(() => setLoading(false));
  }, [postId]);

  const handleAddComment = useCallback(async (content: string) => {
    const newComment = await addComment(postId!, user.id, content);
    setComments(prev => [...prev, newComment]);
    return newComment;
  }, [postId, user?.id]);

  return { comments, loading, handleAddComment };
}

export function useFollow(userId: string | null) {
  const { user } = useAuth();
  const [isFollowingUser, setIsFollowing] = useState(false);
  const [followersCount, setFollowersCount] = useState(0);

  useEffect(() => {
    if (!user?.id || !userId) return;
    isFollowing(user.id, userId).then(setIsFollowing);
    getFollowers(userId).then(f => setFollowersCount(f.length));
  }, [user?.id, userId]);

  const toggleFollow = useCallback(async () => {
    if (isFollowingUser) {
      await unfollowUser(user.id, userId);
      setIsFollowing(false);
      setFollowersCount(prev => prev - 1);
    } else {
      await followUser(user.id, userId);
      setIsFollowing(true);
      setFollowersCount(prev => prev + 1);
    }
  }, [isFollowingUser, user?.id, userId]);

  return { isFollowing: isFollowingUser, followersCount, toggleFollow };
}

export function useUserSearch() {
  const [results, setResults] = useState<UserSearchResult[]>([]);
  const [loading, setLoading] = useState(false);

  const search = useCallback(async (query: string) => {
    if (!query || query.length < 2) {
      setResults([]);
      return;
    }
    setLoading(true);
    try {
      const data = await searchUsers(query);
      setResults(data);
    } catch (e) { if (__DEV__) console.warn('useUserSearch:', e); }
    setLoading(false);
  }, []);

  return { results, loading, search };
}

// Hook de monetização - NOVAIX FITNESS

import { useState, useEffect, useCallback } from 'react';
import { useAuth } from '../context/AuthContext';
import {
  getPlans,
  getUserPlan,
  checkFeatureAccess,
  getUsageStats,
  createSubscription,
  cancelSubscription,
  applyCoupon,
  createReferral,
  getReferralStats,
  applyReferral,
} from '../services/monetization';
import { Plan } from '../types';

interface UsageStats {
  [key: string]: unknown;
}

interface Discount {
  [key: string]: unknown;
}

interface ReferralStats {
  code?: string;
  [key: string]: unknown;
}

interface UseSubscriptionReturn {
  plan: Plan | null;
  plans: Plan[];
  usage: UsageStats | null;
  loading: boolean;
  subscribe: (planId: string, paymentMethod: string) => Promise<unknown>;
  cancel: () => Promise<void>;
  checkAccess: (feature: string) => Promise<boolean>;
  refresh: () => void;
  isPremium: boolean;
  isBasic: boolean;
  isFree: boolean;
}

interface UseCouponReturn {
  discount: Discount | null;
  loading: boolean;
  error: string | null;
  validate: (code: string, planId: string) => Promise<Discount | null>;
  clear: () => void;
}

interface UseReferralReturn {
  stats: ReferralStats | null;
  loading: boolean;
  generateCode: () => Promise<string>;
  refresh: () => Promise<void>;
}

export function useSubscription(): UseSubscriptionReturn {
  const { user } = useAuth();
  const [plan, setPlan] = useState<Plan | null>(null);
  const [plans, setPlans] = useState<Plan[]>([]);
  const [usage, setUsage] = useState<UsageStats | null>(null);
  const [loading, setLoading] = useState<boolean>(true);

  useEffect(() => {
    setPlans(getPlans() as any);
    if (user?.id) loadPlan();
  }, [user?.id]);

  async function loadPlan(): Promise<void> {
    setLoading(true);
    try {
      const [userPlan, usageStats] = await Promise.all([
        getUserPlan(user.id),
        getUsageStats(user.id),
      ]);
      setPlan(userPlan as any);
      setUsage(usageStats);
    } catch (err) {
      if (__DEV__) console.error('Erro ao carregar plano:', err);
    }
    setLoading(false);
  }

  const subscribe = useCallback(async (planId: string, paymentMethod: string): Promise<unknown> => {
    const sub = await createSubscription(user.id, planId, paymentMethod);
    await loadPlan();
    return sub;
  }, [user?.id]);

  const cancel = useCallback(async (): Promise<void> => {
    await cancelSubscription(user.id);
    await loadPlan();
  }, [user?.id]);

  const checkAccess = useCallback(async (feature: string): Promise<boolean> => {
    return checkFeatureAccess(user.id, feature);
  }, [user?.id]);

  const refresh = useCallback((): void => { loadPlan(); }, [user?.id]);

  return {
    plan,
    plans,
    usage,
    loading,
    subscribe,
    cancel,
    checkAccess,
    refresh,
    isPremium: plan?.id === 'premium',
    isBasic: plan?.id === 'basic',
    isFree: plan?.id === 'free' || !plan,
  };
}

export function useCoupon(): UseCouponReturn {
  const [discount, setDiscount] = useState<Discount | null>(null);
  const [loading, setLoading] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);

  const validate = useCallback(async (code: string, planId: string): Promise<Discount | null> => {
    setLoading(true);
    setError(null);
    try {
      const result = await applyCoupon(code, planId);
      if (result) {
        setDiscount(result as any);
      } else {
        setError('Cupom invalido ou expirado');
      }
      return result as any;
    } catch (err: unknown) {
      const msg = err instanceof Error ? err.message : 'Erro ao validar cupom';
      setError(msg);
      return null;
    } finally {
      setLoading(false);
    }
  }, []);

  const clear = useCallback((): void => {
    setDiscount(null);
    setError(null);
  }, []);

  return { discount, loading, error, validate, clear };
}

export function useReferral(): UseReferralReturn {
  const { user } = useAuth();
  const [stats, setStats] = useState<ReferralStats | null>(null);
  const [loading, setLoading] = useState<boolean>(true);

  useEffect(() => {
    if (user?.id) loadStats();
  }, [user?.id]);

  async function loadStats(): Promise<void> {
    setLoading(true);
    try {
      const data = await getReferralStats(user.id);
      setStats(data);
    } catch (err) {
      if (__DEV__) console.error('Erro ao carregar stats referral:', err);
    }
    setLoading(false);
  }

  const generateCode = useCallback(async (): Promise<string> => {
    const code = await createReferral(user.id);
    setStats(prev => prev ? { ...prev, code } : { code });
    return code;
  }, [user?.id]);

  return { stats, loading, generateCode, refresh: loadStats };
}

// src/hooks/useSupabaseData.ts
// Hook com fallback para dados mock - NOVAIX FITNESS

import { useState, useEffect, useCallback } from 'react';
import { supabase } from '../config/supabase';

interface Filter {
  column: string;
  value: string | number | boolean;
  op?: 'eq' | 'ilike';
}

interface OrderBy {
  column: string;
  ascending?: boolean;
}

interface SupabaseDataOptions {
  select?: string;
  filters?: Filter[];
  orderBy?: OrderBy | null;
  limit?: number | null;
  mockData?: Record<string, unknown>[];
}

export function useSupabaseData<T extends Record<string, unknown>>(
  tableName: string,
  options: SupabaseDataOptions = {}
) {
  const { select = '*', filters = [], orderBy = null, limit = null, mockData = [] } = options;
  const [data, setData] = useState<T[]>(mockData as T[]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [isConnected, setIsConnected] = useState(false);

  const filtersKey = JSON.stringify(filters);
  const orderByKey = JSON.stringify(orderBy);

  const fetchData = useCallback(async () => {
    try {
      setLoading(true);
      setError(null);

      const { error: pingError } = await supabase.from(tableName).select('id').limit(1);

      if (pingError) {
        setIsConnected(false);
        setData(mockData as T[]);
        return;
      }

      setIsConnected(true);

      let query = supabase.from(tableName).select(select);

      filters.forEach(({ column, value, op = 'eq' }) => {
        query = op === 'eq' ? query.eq(column, value) : query.ilike(column, `%${value}%`);
      });

      if (orderBy) query = query.order(orderBy.column, { ascending: orderBy.ascending ?? false });
      if (limit) query = query.limit(limit);

      const { data: result, error: fetchError } = await query;

      if (fetchError) throw fetchError;
      setData((result || []) as unknown as T[]);
    } catch (err) {
      if (__DEV__) console.error(`Erro ao buscar ${tableName}:`, err);
      setError(err instanceof Error ? err.message : 'Erro desconhecido');
      setData(mockData as T[]);
    } finally {
      setLoading(false);
    }
  }, [tableName, select, filtersKey, orderByKey, limit]);

  useEffect(() => {
    fetchData();
  }, [fetchData]);

  const insert = async (record: Record<string, unknown>) => {
    if (!isConnected) return { error: 'Sem conexão' };

    try {
      const { data: result, error } = await supabase
        .from(tableName)
        .insert(record)
        .select()
        .single();

      if (error) throw error;
      fetchData();
      return { data: result };
    } catch (err) {
      return { error: err instanceof Error ? err.message : 'Erro ao inserir' };
    }
  };

  const update = async (id: string, updates: Record<string, unknown>) => {
    if (!isConnected) return { error: 'Sem conexão' };

    try {
      const { data: result, error } = await supabase
        .from(tableName)
        .update(updates)
        .eq('id', id)
        .select()
        .single();

      if (error) throw error;
      fetchData();
      return { data: result };
    } catch (err) {
      return { error: err instanceof Error ? err.message : 'Erro ao atualizar' };
    }
  };

  const remove = async (id: string) => {
    if (!isConnected) return { error: 'Sem conexão' };

    try {
      const { error } = await supabase
        .from(tableName)
        .delete()
        .eq('id', id);

      if (error) throw error;
      fetchData();
      return { success: true };
    } catch (err) {
      return { error: err instanceof Error ? err.message : 'Erro ao deletar' };
    }
  };

  return { data, loading, error, isConnected, refetch: fetchData, insert, update, remove };
}

