import { useState, useEffect, useCallback, useMemo } from 'react';
import { Alert } from 'react-native';
import { supabase } from '../config/supabase';
import { useAuth } from '../context/AuthContext';
import { shareWorkout } from '../services/share';
import { cacheWorkoutDetail, getCachedWorkoutDetail, isWorkoutCached } from '../services/offline';
import { queueFavoriteAction } from '../services/offlineManager';
import useNetworkStatus from './useNetworkStatus';
import { fallbackWorkout } from '../data/workouts';
import { Workout, Exercise, Profile } from '../types';

interface Router {
  push: (url: { pathname: string; params?: Record<string, string> }) => void;
  back: () => void;
  [key: string]: unknown;
}

interface UseWorkoutDetailReturn {
  workout: Workout | null;
  profile: Profile | null;
  loading: boolean;
  expanded: number | null;
  setExpanded: (val: number | null) => void;
  showVideo: boolean;
  setShowVideo: (val: boolean) => void;
  isFavorite: boolean;
  showOptions: boolean;
  setShowOptions: (val: boolean) => void;
  showRating: boolean;
  setShowRating: (val: boolean) => void;
  isOffline: boolean;
  isOnline: boolean;
  exercises: Exercise[];
  totalSets: number;
  toggleFavorite: () => Promise<void>;
  handleOption: (opt: string) => Promise<void>;
  handleStart: (router: Router) => Promise<void>;
  handleRating: (data: { rating: number; comment: string }) => Promise<void>;
}

export function useWorkoutDetail(id: string): UseWorkoutDetailReturn {
  const { user } = useAuth();
  const [workout, setWorkout] = useState<Workout | null>(null);
  const [profile, setProfile] = useState<Profile | null>(null);
  const [loading, setLoading] = useState<boolean>(true);
  const [expanded, setExpanded] = useState<number | null>(null);
  const [showVideo, setShowVideo] = useState<boolean>(false);
  const [isFavorite, setIsFavorite] = useState<boolean>(false);
  const [showOptions, setShowOptions] = useState<boolean>(false);
  const [showRating, setShowRating] = useState<boolean>(false);
  const [isOffline, setIsOffline] = useState<boolean>(false);
  const { isOnline } = useNetworkStatus();

  useEffect(() => {
    if (!id) return;
    async function loadWorkoutDetail() {
      try {
        const { data, error } = await supabase.from('workouts').select('*').eq('id', id).single();
        const w = error || !data ? null : (data as Workout);
        if (w) {
          setWorkout(w);
          await cacheWorkoutDetail(w);
        } else {
          const cached = await getCachedWorkoutDetail(id);
          if (cached) setWorkout(cached as Workout);
        }
      } catch {
        const cached = await getCachedWorkoutDetail(id);
        if (cached) setWorkout(cached as Workout);
      } finally {
        setLoading(false);
      }
    }
    loadWorkoutDetail();
    isWorkoutCached(id).then(setIsOffline);
  }, [id]);

  useEffect(() => {
    if (!user?.id) return;
    async function loadUserData() {
      try {
        const { data } = await supabase.from('profiles').select('subscription_status').eq('id', user.id!).single();
        if (data) setProfile(data as Profile);
      } catch {}

      if (id) {
        try {
          const { data } = await supabase.from('favorites').select('id').eq('user_id', user.id!).eq('workout_id', id).single();
          setIsFavorite(!!data);
        } catch {}
      }
    }
    loadUserData();
  }, [user?.id, id]);

  const toggleFavorite = useCallback(async (): Promise<void> => {
    if (!user?.id || !id) return;
    try {
      if (isOnline) {
        if (isFavorite) await supabase.from('favorites').delete().eq('user_id', user.id).eq('workout_id', id);
        else await supabase.from('favorites').insert({ user_id: user.id, workout_id: id });
      } else {
        await queueFavoriteAction(user.id, id, !isFavorite);
      }
      setIsFavorite(!isFavorite);
    } catch { Alert.alert('Erro', 'Falha ao atualizar favorito'); }
  }, [user?.id, id, isFavorite, isOnline]);

  const handleOption = useCallback(async (opt: string): Promise<void> => {
    setShowOptions(false);
    if (opt === 'share') shareWorkout(workout);
    if (opt === 'rate') return setShowRating(true);
    if (opt === 'save') {
      await cacheWorkoutDetail(workout);
      setIsOffline(true);
      Alert.alert('Salvo', 'Treino disponível offline');
    }
  }, [workout]);

  const handleStart = useCallback(async (router: Router): Promise<void> => {
    if (!user?.id || !id) return;
    const isSubscribed = profile?.subscription_status === 'premium' || profile?.subscription_status === 'active';
    const isLocked = ((workout as any)?.is_premium || false) && !isSubscribed;
    if (isLocked) {
      Alert.alert('Conteúdo Premium 🔒', 'Este treino é exclusivo para assinantes Premium.',
        [{ text: 'Mais tarde', style: 'cancel' }, { text: 'Ver Planos', onPress: () => router.push({ pathname: '/paywall' }) }]);
      return;
    }
    try {
      const { data } = await supabase.from('user_workouts').insert({
        user_id: user.id, workout_id: id, completed: false,
        duration: workout?.duration_minutes || workout?.duration || 0,
      }).select('id').single();
      router.push({ pathname: '/player', params: { id, user_workout_id: data?.id } });
    } catch { router.push({ pathname: '/player', params: { id } }); }
  }, [user?.id, id, workout, profile]);

  const handleRating = useCallback(async ({ rating, comment }: { rating: number; comment: string }): Promise<void> => {
    if (!user?.id || !id) return;
    try {
      await supabase.from('user_workouts').upsert(
        { user_id: user.id, workout_id: id, rating, notes: comment },
        { onConflict: 'user_id,workout_id' }
      );
      Alert.alert('Obrigado!', 'Avaliação registrada.');
    } catch { Alert.alert('Erro', 'Falha ao salvar.'); }
  }, [user?.id, id]);

  const exercises: Exercise[] = workout?.exercises || [];
  const totalSets: number = useMemo(() => exercises.reduce((sum, ex) => sum + (ex.sets || 0), 0), [exercises]);

  return {
    workout, profile, loading, expanded, setExpanded,
    showVideo, setShowVideo, isFavorite, showOptions, setShowOptions,
    showRating, setShowRating, isOffline, isOnline, exercises, totalSets,
    toggleFavorite, handleOption, handleStart, handleRating,
  };
}

// Hook para gerenciar formulário de treino - NOVAIX FITNESS

import { useState, useCallback } from 'react';
import { Alert } from 'react-native';
import * as Haptics from 'expo-haptics';
import { Workout, Exercise } from '../types';

const CATEGORIES: string[] = ['Musculação', 'HIIT', 'Cardio', 'Yoga', 'Calistenia', 'Natação', 'Outro'];
const LEVELS: string[] = ['Iniciante', 'Intermediário', 'Avançado'];

interface WorkoutFormData {
  name: string;
  description: string;
  category: string;
  level: string;
  duration: number;
  isPremium: boolean;
  exercises: Exercise[];
  totalSets: number;
  exerciseCount: number;
}

interface UseWorkoutFormReturn {
  name: string;
  setName: (val: string) => void;
  description: string;
  setDescription: (val: string) => void;
  category: string;
  setCategory: (val: string) => void;
  level: string;
  setLevel: (val: string) => void;
  duration: string;
  setDuration: (val: string) => void;
  isPremium: boolean;
  setIsPremium: (val: boolean) => void;
  exercises: Exercise[];
  showExerciseForm: boolean;
  editingExercise: number | null;
  totalSets: number;
  addExercise: (exercise: Exercise) => void;
  removeExercise: (i: number) => void;
  moveExercise: (from: number, to: number) => void;
  openExerciseForm: (index?: number | null) => void;
  closeExerciseForm: () => void;
  validate: () => boolean;
  getFormData: () => WorkoutFormData;
  CATEGORIES: string[];
  LEVELS: string[];
}

export function useWorkoutForm(existingWorkout: Workout | null = null): UseWorkoutFormReturn {
  const [name, setName] = useState<string>(existingWorkout?.name || '');
  const [description, setDescription] = useState<string>(existingWorkout?.description || '');
  const [category, setCategory] = useState<string>(existingWorkout?.category || '');
  const [level, setLevel] = useState<string>(existingWorkout?.level || 'Intermediário');
  const [duration, setDuration] = useState<string>(String(existingWorkout?.duration || 45));
  const [isPremium, setIsPremium] = useState<boolean>((existingWorkout as any)?.is_premium || false);
  const [exercises, setExercises] = useState<Exercise[]>(existingWorkout?.exercises || []);
  const [showExerciseForm, setShowExerciseForm] = useState<boolean>(false);
  const [editingExercise, setEditingExercise] = useState<number | null>(null);

  const totalSets: number = exercises.reduce((s, e) => s + (e.sets || 0), 0);

  const addExercise = useCallback((exercise: Exercise): void => {
    try { Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light); } catch {}
    setExercises(prev => editingExercise !== null
      ? prev.map((e, i) => i === editingExercise ? exercise : e)
      : [...prev, exercise]
    );
    setEditingExercise(null);
    setShowExerciseForm(false);
  }, [editingExercise]);

  const removeExercise = useCallback((i: number): void => {
    Alert.alert('Remover', 'Remover este exercício?', [
      { text: 'Cancelar', style: 'cancel' },
      { text: 'Remover', style: 'destructive', onPress: () => setExercises(prev => prev.filter((_, idx) => idx !== i)) },
    ]);
  }, []);

  const moveExercise = useCallback((from: number, to: number): void => {
    if (to < 0 || to >= exercises.length) return;
    setExercises(prev => {
      const arr = [...prev];
      const [item] = arr.splice(from, 1);
      arr.splice(to, 0, item);
      return arr;
    });
  }, [exercises.length]);

  const openExerciseForm = useCallback((index: number | null = null): void => {
    setEditingExercise(index);
    setShowExerciseForm(true);
  }, []);

  const closeExerciseForm = useCallback((): void => {
    setEditingExercise(null);
    setShowExerciseForm(false);
  }, []);

  const validate = useCallback((): boolean => {
    if (!name.trim()) { Alert.alert('Aviso', 'Nome é obrigatório.'); return false; }
    if (!category) { Alert.alert('Aviso', 'Selecione uma categoria.'); return false; }
    if (exercises.length === 0) { Alert.alert('Aviso', 'Adicione pelo menos um exercício.'); return false; }
    return true;
  }, [name, category, exercises.length]);

  const getFormData = useCallback((): WorkoutFormData => ({
    name: name.trim(),
    description: description.trim(),
    category,
    level,
    duration: parseInt(duration) || 45,
    isPremium,
    exercises,
    totalSets,
    exerciseCount: exercises.length,
  }), [name, description, category, level, duration, isPremium, exercises, totalSets]);

  return {
    name, setName,
    description, setDescription,
    category, setCategory,
    level, setLevel,
    duration, setDuration,
    isPremium, setIsPremium,
    exercises,
    showExerciseForm,
    editingExercise,
    totalSets,
    addExercise,
    removeExercise,
    moveExercise,
    openExerciseForm,
    closeExerciseForm,
    validate,
    getFormData,
    CATEGORIES,
    LEVELS,
  };
}

