// Hook de timer de treino - re-exportacao

import { useState, useEffect, useRef, useCallback } from 'react';
import { countdownTick, phaseChange, workoutComplete } from '../services/hapticService';
import { playCountdownTick, playPhaseEnd, playWorkoutComplete } from '../services/audioService';
import { speakWelcome, speakNextExercise, speakHalfway, speakWorkoutComplete, stopSpeaking } from '../services/voiceCoach';
import { computeProgress, computeXP, buildSetLog, resolveAfterSetComplete, resolveAfterSkip } from './helpers/timerHelpers';
import { Workout, Exercise } from '../types';
import type { TimerPhase, SetLog, ProgressResult, SetCompleteResult, SkipResult, UseWorkoutTimerReturn } from './useWorkoutTimerTypes';

export type { TimerPhase, SetLog, UseWorkoutTimerReturn } from './useWorkoutTimerTypes';

export default function useWorkoutTimer(workout: Workout | null): UseWorkoutTimerReturn {
  const [phase, setPhase] = useState<TimerPhase>('idle');
  const [currentExerciseIndex, setCurrentExerciseIndex] = useState<number>(0);
  const [currentSet, setCurrentSet] = useState<number>(1);
  const [timeRemaining, setTimeRemaining] = useState<number>(0);
  const [totalTime, setTotalTime] = useState<number>(0);
  const [elapsed, setElapsed] = useState<number>(0);
  const [logs, setLogs] = useState<SetLog[]>([]);

  const intervalRef = useRef<ReturnType<typeof setInterval> | null>(null);
  const phaseRef = useRef<TimerPhase>('idle');
  const exerciseRef = useRef<number>(0);
  const setRef = useRef<number>(1);

  const exercises: Exercise[] = workout?.exercises || [];
  const currentExercise: Exercise | undefined = exercises[currentExerciseIndex];
  const totalExercises: number = exercises.length;
  const totalSets: number = currentExercise?.sets || 4;

  useEffect(() => {
    phaseRef.current = phase;
    exerciseRef.current = currentExerciseIndex;
    setRef.current = currentSet;
  }, [phase, currentExerciseIndex, currentSet]);

  const clearTimer = useCallback((): void => {
    if (intervalRef.current) { clearInterval(intervalRef.current); intervalRef.current = null; }
  }, []);

  const completeWorkout = useCallback(async (): Promise<void> => {
    clearTimer();
    await playWorkoutComplete();
    await workoutComplete();
    speakWorkoutComplete(workout?.name);
    setPhase('completed');
  }, [workout, clearTimer]);

  const startExercise = useCallback((): void => {
    const idx = exerciseRef.current;
    const exs: Exercise[] = workout?.exercises || [];
    const exercise = exs[idx];
    if (!exercise) { completeWorkout(); return; }
    setTimeRemaining(0);
    setTotalTime(0);
    setPhase('exercising');
    speakNextExercise(exercise.name, exercise.reps, (exercise as any).weight, idx + 1, exs.length);
  }, [workout, completeWorkout]);

  const handlePhaseComplete = useCallback((): void => {
    clearTimer();
    if (phaseRef.current === 'resting') { playPhaseEnd(); phaseChange(); startExercise(); }
    else if (phaseRef.current === 'exercising') { playPhaseEnd(); phaseChange(); }
  }, [startExercise, clearTimer]);

  const startWorkout = useCallback((): void => {
    clearTimer();
    setCurrentExerciseIndex(0);
    setCurrentSet(1);
    setElapsed(0);
    setLogs([]);
    setPhase('exercising');
    setTimeRemaining(0);
    setTotalTime(0);
    speakWelcome(workout?.name);
  }, [workout, clearTimer]);

  const pauseWorkout = useCallback((): void => { clearTimer(); setPhase('paused'); }, [clearTimer]);
  const resumeWorkout = useCallback((): void => { setPhase(phaseRef.current === 'paused' ? 'exercising' : phaseRef.current); }, []);

  const markSetComplete = useCallback((setLog: SetLog): void => {
    const exercise = exercises[exerciseRef.current];
    setLogs(prev => [...prev, buildSetLog(exerciseRef.current, exercise, setRef.current, setLog) as any]);
    clearTimer();
    const result: SetCompleteResult = resolveAfterSetComplete(setRef.current, exerciseRef.current, exercises);
    if (result.isDone) { completeWorkout(); return; }
    setCurrentSet(result.nextSet);
    if (result.nextIndex !== exerciseRef.current) {
      if (result.nextIndex === Math.floor(exercises.length / 2)) speakHalfway();
      setCurrentExerciseIndex(result.nextIndex);
    }
    setTimeRemaining(result.restTime);
    setTotalTime(result.restTime);
    setPhase('resting');
  }, [exercises, completeWorkout, clearTimer]);

  const skipRest = useCallback((): void => { clearTimer(); startExercise(); }, [startExercise, clearTimer]);

  const skipExercise = useCallback((): void => {
    clearTimer();
    const result: SkipResult = resolveAfterSkip(exerciseRef.current, exercises);
    if (result.isDone) { completeWorkout(); return; }
    setCurrentExerciseIndex(result.nextIndex);
    setCurrentSet(1);
    setTimeRemaining(result.restTime);
    setTotalTime(result.restTime);
    setPhase('resting');
  }, [exercises, completeWorkout, clearTimer]);

  const stopWorkout = useCallback((): void => {
    clearTimer();
    stopSpeaking();
    setPhase('idle');
    setCurrentExerciseIndex(0);
    setCurrentSet(1);
    setTimeRemaining(0);
    setTotalTime(0);
  }, [clearTimer]);

  useEffect(() => {
    if (phase === 'exercising' || phase === 'resting') {
      intervalRef.current = setInterval(() => {
        setTimeRemaining(prev => {
          if (prev <= 1) { handlePhaseComplete(); return 0; }
          if (phaseRef.current === 'resting' && prev <= 4 && prev > 1) { countdownTick(prev - 1); playCountdownTick(); }
          return prev - 1;
        });
        setElapsed(prev => prev + 1);
      }, 1000);
    }
    return () => { clearTimer(); };
  }, [phase, handlePhaseComplete, clearTimer]);

  const { exerciseProgress, setProgress, timerProgress }: ProgressResult = computeProgress(currentExerciseIndex, totalExercises, currentSet, totalSets, totalTime, timeRemaining);
  const totalXP: number = computeXP(logs.length, currentExerciseIndex, elapsed);

  return {
    phase, currentExercise, currentExerciseIndex, currentSet, totalSets, totalExercises,
    timeRemaining, totalTime, elapsed, logs, exerciseProgress, setProgress, timerProgress, totalXP,
    startWorkout, pauseWorkout, resumeWorkout, markSetComplete, skipRest, skipExercise, stopWorkout, completeWorkout,
  };
}

