// src/middleware/validation.js
// Middleware de validação de dados

const VALIDATORS: Record<string, (v: string | number) => boolean> = {
  email: (v) => /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v as string),
  password: (v) => v && (v as string).length >= 8,
  name: (v) => v && (v as string).length >= 2 && (v as string).length <= 100,
  weight: (v) => (v as number) >= 30 && (v as number) <= 200,
  height: (v) => (v as number) >= 120 && (v as number) <= 220,
  cep: (v) => /^\d{5}-?\d{3}$/.test(v as string),
  phone: (v) => /^\d{10,11}$/.test((v as string).replace(/\D/g, '')),
};

const ERROR_MESSAGES = {
  email: 'E-mail inválido',
  password: 'Senha deve ter no mínimo 8 caracteres',
  name: 'Nome deve ter entre 2 e 100 caracteres',
  weight: 'Peso deve ser entre 30 e 200 kg',
  height: 'Altura deve ser entre 120 e 220 cm',
  cep: 'CEP inválido',
  phone: 'Telefone inválido',
};

export function validate(field: string, value: string | number): { valid: boolean; error?: string | null } {
  const validator = VALIDATORS[field];
  if (!validator) return { valid: true };
  const valid = validator(value);
  return { valid, error: valid ? null : ERROR_MESSAGES[field] };
}

export function validateAll(data: Record<string, string | number>): { valid: boolean; errors: Record<string, string | null> } {
  const errors: Record<string, string | null> = {};
  for (const [field, value] of Object.entries(data)) {
    const result = validate(field, value);
    if (!result.valid) errors[field] = result.error;
  }
  return { valid: Object.keys(errors).length === 0, errors };
}

export function sanitizeString(str: string | unknown): string {
  if (typeof str !== 'string') return str as string;
  return str.replace(/<[^>]*>/g, '').trim();
}

export function sanitizeObject(obj: Record<string, unknown>): Record<string, unknown> {
  const sanitized: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(obj)) {
    sanitized[key] = typeof value === 'string' ? sanitizeString(value) : value;
  }
  return sanitized;
}

