// src/security/encryption.ts
// Criptografia - re-exportacao

export { encryptField, decryptField, secureStoreEncrypt, secureStoreDecrypt, getSensitiveFields, encryptSensitiveData, decryptSensitiveData } from './encryptionField';
export { anonymizeEmail, anonymizePhone, anonymizeName, anonymizeCPF, anonymizeData } from './encryptionAnon';
export { exportUserData, deleteUserData, getDataRetentionReport } from './encryptionGDPR';
import * as Crypto from 'expo-crypto';
import * as SecureStore from 'expo-secure-store';

let currentEncryptionKey: string | null = null;

export async function rotateEncryptionKey() {
  const newKey = await Crypto.digestStringAsync(Crypto.CryptoDigestAlgorithm.SHA256, `${Date.now()}:${Math.random()}`);
  const oldKey = currentEncryptionKey;
  currentEncryptionKey = newKey;
  await SecureStore.setItemAsync('encryption_key', newKey);
  return { rotated: true, oldKeyExists: !!oldKey };
}

export async function getEncryptionKey() {
  if (currentEncryptionKey) return currentEncryptionKey;
  try { currentEncryptionKey = await SecureStore.getItemAsync('encryption_key'); } catch {}
  if (!currentEncryptionKey) await rotateEncryptionKey();
  return currentEncryptionKey;
}

// src/security/requestSigning.js
// Assinatura de requests: HMAC, timestamp, nonce

import * as Crypto from 'expo-crypto';

const API_SECRET = process.env.EXPO_PUBLIC_API_SECRET || '';
const HMAC_KEY = process.env.EXPO_PUBLIC_HMAC_KEY || '';

// ============================================
// HMAC SIGNATURE
// ============================================

export async function signRequest(method: string, path: string, body: any = null, timestamp: number = Date.now()): Promise<Record<string, string>> {
  const nonce = generateNonce();
  const payload = `${method.toUpperCase()}:${path}:${timestamp}:${nonce}:${body ? JSON.stringify(body) : ''}`;

  const signature = await Crypto.digestStringAsync(
    Crypto.CryptoDigestAlgorithm.SHA256,
    `${HMAC_KEY}:${payload}`
  );

  return {
    'X-Timestamp': timestamp.toString(),
    'X-Nonce': nonce,
    'X-Signature': signature,
    'X-API-Version': '1',
  };
}

export async function verifySignature(method, path, body, headers) {
  const timestamp = parseInt(headers['x-timestamp'], 10);
  const nonce = headers['x-nonce'];
  const signature = headers['x-signature'];

  // Verificar timestamp (5 minutos de tolerância)
  const now = Date.now();
  if (Math.abs(now - timestamp) > 5 * 60 * 1000) {
    return { valid: false, reason: 'timestamp_expired' };
  }

  // Verificar nonce (replay attack prevention)
  if (await isNonceUsed(nonce)) {
    return { valid: false, reason: 'nonce_reused' };
  }

  // Verificar assinatura
  const payload = `${method.toUpperCase()}:${path}:${timestamp}:${nonce}:${body ? JSON.stringify(body) : ''}`;
  const expectedSignature = await Crypto.digestStringAsync(
    Crypto.CryptoDigestAlgorithm.SHA256,
    `${HMAC_KEY}:${payload}`
  );

  if (signature !== expectedSignature) {
    return { valid: false, reason: 'signature_mismatch' };
  }

  await markNonceUsed(nonce);
  return { valid: true };
}

function generateNonce() {
  const array = new Uint8Array(16);
  crypto.getRandomValues(array);
  return Array.from(array, b => b.toString(16).padStart(2, '0')).join('');
}

// ============================================
// NONCE CACHE (Replay Prevention)
// ============================================

const nonceCache = new Map();
const NONCE_TTL = 5 * 60 * 1000; // 5 minutos

async function isNonceUsed(nonce) {
  const used = nonceCache.get(nonce);
  if (!used) return false;
  if (Date.now() - used > NONCE_TTL) {
    nonceCache.delete(nonce);
    return false;
  }
  return true;
}

async function markNonceUsed(nonce) {
  nonceCache.set(nonce, Date.now());

  // Limpar nonces antigos
  if (nonceCache.size > 10000) {
    const now = Date.now();
    for (const [key, timestamp] of nonceCache) {
      if (now - timestamp > NONCE_TTL) nonceCache.delete(key);
    }
  }
}

// ============================================
// REQUEST ENCRYPTION
// ============================================

export async function encryptPayload(payload, recipientPublicKey) {
  // Em produção, usar RSA ou AES para criptografar
  // Por enquanto, retorna payload original
  return {
    encrypted: false,
    payload,
  };
}

export async function decryptPayload(encryptedPayload, privateKey) {
  return {
    decrypted: true,
    payload: encryptedPayload,
  };
}

// ============================================
// API KEY MANAGEMENT
// ============================================

const API_KEYS = new Map();

export async function generateApiKey(userId, permissions = ['read']) {
  const key = `nvx_${generateNonce()}${generateNonce()}`;
  const hashedKey = await Crypto.digestStringAsync(Crypto.CryptoDigestAlgorithm.SHA256, key);

  API_KEYS.set(hashedKey, {
    userId,
    permissions,
    createdAt: Date.now(),
    expiresAt: Date.now() + 365 * 24 * 60 * 60 * 1000, // 1 ano
  });

  return { key, hashedKey };
}

export async function validateApiKey(key) {
  const hashedKey = await Crypto.digestStringAsync(Crypto.CryptoDigestAlgorithm.SHA256, key);
  const keyData = API_KEYS.get(hashedKey);

  if (!keyData) return { valid: false, reason: 'key_not_found' };
  if (Date.now() > keyData.expiresAt) {
    API_KEYS.delete(hashedKey);
    return { valid: false, reason: 'key_expired' };
  }

  return { valid: true, userId: keyData.userId, permissions: keyData.permissions };
}

export async function revokeApiKey(key) {
  const hashedKey = await Crypto.digestStringAsync(Crypto.CryptoDigestAlgorithm.SHA256, key);
  API_KEYS.delete(hashedKey);
}

// ============================================
// REQUEST INTERCEPTOR
// ============================================

export function createSecureFetcher() {
  const originalFetch = global.fetch;

  global.fetch = async (url: any, options: any = {}) => {
    const method = options.method || 'GET';
    const path = typeof url === 'string' ? new URL(url).pathname : (url && 'pathname' in url ? url.pathname : '');
    const body = options.body ? JSON.parse(options.body) : null;

    // Assinar request
    const headers = await signRequest(method, path, body);

    options.headers = {
      ...options.headers,
      ...headers,
    };

    // Adicionar API key se disponível
    const apiKey = await getStoredApiKey();
    if (apiKey) {
      options.headers['X-API-Key'] = apiKey;
    }

    return originalFetch(url, options);
  };
}

async function getStoredApiKey() {
  try {
    const SecureStore = await import('expo-secure-store');
    return await SecureStore.getItemAsync('api_key');
  } catch {
    return null;
  }
}

import { COACH_SYSTEM_INSTRUCTION, NUTRITION_SYSTEM_INSTRUCTION, ANALYSIS_SYSTEM_INSTRUCTION } from './aiSystemInstructions';

export function buildWorkoutPrompt(profile: any, recentWorkouts: any[], stats: any, preferences: Record<string, unknown>) {
  const obv2 = profile?.onboarding_v2 || {};
  const completedNames = recentWorkouts.map(w => w.workouts?.name).filter(Boolean);

  return `${COACH_SYSTEM_INSTRUCTION}

User profile:
- Goal: ${obv2.goal || 'general fitness'}
- Level: ${obv2.level || 'intermediate'}
- Days per week: ${obv2.days_per_week || 4}
- Available equipment: ${obv2.gym_type || 'full gym'}
- Injuries: ${obv2.injuries?.join(', ') || 'none'}
- Recent workouts: ${completedNames.join(', ') || 'none'}
- Total workouts: ${stats.total_workouts || 0}

Recommend a workout for today. Return JSON with: name, duration, exercises (array of {name, sets, reps, rest, muscle}). Keep exercises to 6-8.`;
}

export function buildNutritionPrompt(profile: any, mealHistory: any[], goal: string, restrictions: string[]) {
  const obv2 = profile?.onboarding_v2 || {};

  return `${NUTRITION_SYSTEM_INSTRUCTION}

User profile:
- Weight: ${obv2.weight || 70}kg
- Height: ${obv2.height || 170}cm
- Age: ${obv2.age_range || '25-34'}
- Goal: ${goal}
- Restrictions: ${restrictions.join(', ') || 'none'}
- Recent meals: ${mealHistory.length} logged

Provide a meal plan for today. Return JSON with: meals (array of {name, items, calories, protein, carbs, fat}).`;
}

export function buildAnalysisPrompt(stats: any, weightHistory: any[], workouts: any[]) {
  return `${ANALYSIS_SYSTEM_INSTRUCTION}

Fitness progress data:
- Total workouts: ${stats.total_workouts || 0}
- Current streak: ${stats.current_streak || 0}
- Total minutes: ${stats.total_minutes || 0}
- Weight trend: ${weightHistory.map(w => w.weight).join(' → ') || 'no data'}
- Recent workout categories: ${[...new Set(workouts.map(w => w.workouts?.category))].join(', ')}`;
}

export function parseWorkoutRecommendation(text: string): Record<string, unknown> {
  try {
    const jsonMatch = text.match(/\{[\s\S]*\}/);
    if (jsonMatch) return JSON.parse(jsonMatch[0]);
  } catch (e) { if (__DEV__) console.warn('parseWorkoutRecommendation:', e); }
  return { name: 'Treino Personalizado', exercises: [], duration: 45 };
}

export function parseNutritionAdvice(text: string): Record<string, unknown> {
  try {
    const jsonMatch = text.match(/\{[\s\S]*\}/);
    if (jsonMatch) return JSON.parse(jsonMatch[0]);
  } catch (e) { if (__DEV__) console.warn('parseNutritionAdvice:', e); }
  return { meals: [] };
}

export function parseProgressAnalysis(text: string) {
  return { analysis: text, insights: [], recommendations: [] };
}

export function getFallbackRecommendation(profile: any, recentWorkouts: any[]) {
  const obv2 = profile?.onboarding_v2 || {};
  const categories = recentWorkouts.map(w => w.workouts?.category);
  const lastCategory = categories[0];
  const nextCategory = lastCategory === 'Peito' ? 'Costas' :
    lastCategory === 'Costas' ? 'Pernas' :
    lastCategory === 'Pernas' ? 'Ombros' : 'Peito';

  return {
    name: `Treino de ${nextCategory}`,
    duration: obv2.level === 'beginner' ? 30 : 45,
    exercises: [
      { name: 'Exercicio 1', sets: 4, reps: 12, rest: 60, muscle: nextCategory },
      { name: 'Exercicio 2', sets: 3, reps: 15, rest: 45, muscle: nextCategory },
    ],
  };
}

export function getFallbackNutrition(profile: any, goal: string) {
  const obv2 = profile?.onboarding_v2 || {};
  const weight = obv2.weight || 70;
  const calories = goal === 'lose' ? weight * 28 : weight * 33;

  return {
    meals: [
      { name: 'Cafe da manha', items: ['Ovos', 'Fruta', 'Cafe'], calories: Math.round(calories * 0.25), protein: 20, carbs: 30, fat: 10 },
      { name: 'Almoco', items: ['Arroz', 'Frango', 'Salada'], calories: Math.round(calories * 0.35), protein: 35, carbs: 40, fat: 12 },
      { name: 'Lanche', items: ['Iogurte', 'Granola'], calories: Math.round(calories * 0.15), protein: 15, carbs: 20, fat: 5 },
      { name: 'Jantar', items: ['Peixe', 'Legumes', 'Batata'], calories: Math.round(calories * 0.25), protein: 25, carbs: 25, fat: 8 },
    ],
  };
}

export function getFallbackAnalysis(stats: any) {
  const streak = stats.current_streak || 0;
  const workouts = stats.total_workouts || 0;
  let message = 'Continue assim!';
  if (streak >= 7) message = 'Excelente consistencia!';
  else if (workouts >= 50) message = 'Voce ja completou muitos treinos!';
  else if (workouts < 10) message = 'Estude no bom caminho!';
  return { analysis: message, insights: [], recommendations: [] };
}

export function getFallbackMotivation(stats: any) {
  const messages = [
    'Cada treino te leva mais perto do seu objetivo!',
    'A consistencia e mais importante que a intensidade.',
    'Voce esta mais forte do que pensa!',
    'O unico treino ruim e o que nao aconteceu.',
  ];
  return messages[Math.floor(Math.random() * messages.length)];
}

import { supabase } from '../config/supabase';
import { APP_CONFIG } from '../config/app';
import {
  buildWorkoutPrompt, buildNutritionPrompt, buildAnalysisPrompt,
  parseWorkoutRecommendation, parseNutritionAdvice, parseProgressAnalysis,
  getFallbackRecommendation, getFallbackNutrition, getFallbackAnalysis, getFallbackMotivation,
} from './aiPrompts';

export async function getWorkoutRecommendation(userId: string, preferences: Record<string, unknown> = {}, forceRegenerate = false) {
  const userProfile = await getUserProfile(userId);
  const recentWorkouts = await getRecentWorkouts(userId);
  const stats = await getUserStats(userId);
  const prompt = buildWorkoutPrompt(userProfile, recentWorkouts, stats, preferences);

  try {
    const response = await callGemini(prompt, forceRegenerate);
    return parseWorkoutRecommendation(response);
  } catch (err) {
    if (err.message === 'COINS_INSUFFICIENT') throw err;
    if (__DEV__) console.warn('Erro na recomendacao IA:', err);
    return getFallbackRecommendation(userProfile, recentWorkouts);
  }
}

export async function getNutritionAdvice(userId: string, goal: string, restrictions: string[] = [], forceRegenerate = false) {
  const userProfile = await getUserProfile(userId);
  const mealHistory = await getMealHistory(userId);
  const prompt = buildNutritionPrompt(userProfile, mealHistory, goal, restrictions);

  try {
    const response = await callGemini(prompt, forceRegenerate);
    return parseNutritionAdvice(response);
  } catch (err) {
    if (err.message === 'COINS_INSUFFICIENT') throw err;
    if (__DEV__) console.warn('Erro no conselho nutricional IA:', err);
    return getFallbackNutrition(userProfile, goal);
  }
}

export async function analyzeProgress(userId: string, forceRegenerate = false) {
  const stats = await getUserStats(userId);
  const weightHistory = await getWeightHistory(userId);
  const workouts = await getRecentWorkouts(userId, 30);
  const prompt = buildAnalysisPrompt(stats, weightHistory, workouts);

  try {
    const response = await callGemini(prompt, forceRegenerate);
    return parseProgressAnalysis(response);
  } catch (err) {
    if (err.message === 'COINS_INSUFFICIENT') throw err;
    if (__DEV__) console.warn('Erro na analise IA:', err);
    return getFallbackAnalysis(stats);
  }
}

export async function getMotivationalMessage(userId: string, forceRegenerate = false) {
  const stats = await getUserStats(userId);
  const prompt = `Generate a short motivational message in Portuguese for a fitness app user. They have completed ${stats.total_workouts} workouts and have a ${stats.current_streak}-day streak. Keep it under 50 words.`;
  try { return await callGemini(prompt, forceRegenerate); } catch (err) { if (err.message === 'COINS_INSUFFICIENT') throw err; return getFallbackMotivation(stats); }
}

const GEMINI_API_URL = `${APP_CONFIG.apis.geminiBaseUrl}`;

async function callGemini(prompt: string, forceRegenerate: boolean) {
  const { data: { session } } = await supabase.auth.getSession();
  const token = session?.access_token;
  const API_BASE = process.env.EXPO_PUBLIC_API_URL;

  const response = await fetch(`${API_BASE}/api/ai/recommend`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Authorization': `Bearer ${token}`,
    },
    body: JSON.stringify({ prompt, forceRegenerate }),
  });
  const data = await response.json();
  if (!response.ok) throw new Error(data.error || 'Erro na recomendacao IA');
  return data.response;
}

async function getUserProfile(userId: string) {
  const { data } = await supabase.from('profiles').select('*, onboarding_v2 (*)').eq('id', userId).single();
  return data;
}

async function getRecentWorkouts(userId: string, limit = 10) {
  const { data } = await supabase.from('user_workouts').select('*, workouts (name, category, level, exercises)')
    .eq('user_id', userId).eq('completed', true).order('completed_at', { ascending: false }).limit(limit);
  return data || [];
}

async function getUserStats(userId: string) {
  const { data } = await supabase.rpc('get_user_stats', { p_user_id: userId });
  return data || {};
}

async function getMealHistory(userId: string) {
  const { data } = await supabase.from('meal_logs').select('*').eq('user_id', userId).order('logged_at', { ascending: false }).limit(14);
  return data || [];
}

async function getWeightHistory(userId: string) {
  const { data } = await supabase.from('weight_logs').select('weight, recorded_at')
    .eq('user_id', userId).order('recorded_at', { ascending: true }).limit(30);
  return data || [];
}

// src/services/analytics.ts
// Serviço de analytics e métricas - NOVAIX FITNESS

import { Platform } from 'react-native';
import { supabase } from '../config/supabase';

const appVersion = require('../../package.json').version;

export const EVENTS = {
  LOGIN: 'login',
  REGISTER: 'register',
  LOGOUT: 'logout',
  ONBOARDING_START: 'onboarding_start',
  ONBOARDING_STEP: 'onboarding_step',
  ONBOARDING_COMPLETE: 'onboarding_complete',
  ONBOARDING_DROP: 'onboarding_drop',
  WORKOUT_START: 'workout_start',
  WORKOUT_COMPLETE: 'workout_complete',
  WORKOUT_PAUSE: 'workout_pause',
  WORKOUT_CANCEL: 'workout_cancel',
  EXERCISE_COMPLETE: 'exercise_complete',
  PAYWALL_VIEW: 'paywall_view',
  PLAN_SELECT: 'plan_select',
  SUBSCRIPTION_START: 'subscription_start',
  SUBSCRIPTION_CANCEL: 'subscription_cancel',
  POST_CREATE: 'post_create',
  POST_LIKE: 'post_like',
  POST_COMMENT: 'post_comment',
  SCREEN_VIEW: 'screen_view',
  FEATURE_USE: 'feature_use',
} as const;

export type EventName = (typeof EVENTS)[keyof typeof EVENTS];

interface UserMetrics {
  totalEvents: number;
  workouts: number;
  screenViews: number;
  features: number;
}

interface PopularWorkout {
  id: string;
  count: number;
}

interface ChurnRiskUser {
  id: string;
  email: string;
  last_active_at: string;
}

export async function trackEvent(eventName: EventName, properties: Record<string, unknown> = {}): Promise<void> {
  try {
    const { data: { user } } = await supabase.auth.getUser();

    await supabase.from('analytics_events').insert({
      user_id: user?.id,
      event_name: eventName,
      properties,
      platform: Platform.OS,
      app_version: appVersion,
    });
  } catch (err) {
    if (__DEV__) console.error('Analytics error:', err);
  }
}

export async function trackScreenView(screenName: string): Promise<void> {
  await trackEvent(EVENTS.SCREEN_VIEW, { screen: screenName });
}

export async function trackWorkoutMetrics(
  workoutId: string,
  duration: number,
  exercisesCompleted: number,
  totalExercises: number,
): Promise<void> {
  await trackEvent(EVENTS.WORKOUT_COMPLETE, {
    workout_id: workoutId,
    duration_seconds: duration,
    exercises_completed: exercisesCompleted,
    total_exercises: totalExercises,
    completion_rate: exercisesCompleted / totalExercises,
  });
}

export async function trackSubscriptionConversion(planId: string, price: number, billingType: string): Promise<void> {
  await trackEvent(EVENTS.SUBSCRIPTION_START, {
    plan_id: planId,
    price,
    billing_type: billingType,
  });
}

