export async function getWeightHistory(userId: string) {
  try {
    const { data } = await supabase.from('body_measurements').select('weight, created_at').eq('user_id', userId).order('created_at', { ascending: true });
    return (data || []).map(d => ({ date: new Date(d.created_at).toLocaleDateString('pt-BR'), weight: d.weight }));
  } catch { return []; }
