import NetInfo from '@react-native-community/netinfo';
import { syncPendingActions, getPendingActionsCount } from './sync';
import { updateLastSync } from './offline';

let unsubscribe: (() => void) | null = null;
let lastConnected = true;
let syncTimeout: ReturnType<typeof setTimeout> | null = null;
let onSyncStateChange: ((state: string) => void) | null = null;

const DEBOUNCE_MS = 300;

async function handleNetworkChange(state: { isConnected: boolean | null; isInternetReachable: boolean | null }) {
  const isNowOnline = state.isConnected && state.isInternetReachable;

  if (isNowOnline && !lastConnected) {
    onSyncStateChange?.('syncing');

    if (syncTimeout) clearTimeout(syncTimeout);
    syncTimeout = setTimeout(async () => {
      const pendingCount = await getPendingActionsCount();
      if (pendingCount > 0) {
        try {
          await syncPendingActions();
          await updateLastSync();
          onSyncStateChange?.('synced');
        } catch (err) {
          onSyncStateChange?.('error');
        }
      } else {
        onSyncStateChange?.('idle');
      }
    }, DEBOUNCE_MS);
  }

  lastConnected = isNowOnline;
}

export function startAutoSync(stateCallback?: (state: string) => void) {
  onSyncStateChange = stateCallback || null;
  if (unsubscribe) return;
  unsubscribe = NetInfo.addEventListener(handleNetworkChange);
}

export function stopAutoSync() {
  if (unsubscribe) { unsubscribe(); unsubscribe = null; }
  if (syncTimeout) { clearTimeout(syncTimeout); syncTimeout = null; }
  onSyncStateChange = null;
}

export async function forceSyncNow() {
  const pendingCount = await getPendingActionsCount();
  if (pendingCount === 0) return { synced: 0, failed: 0 };

  onSyncStateChange?.('syncing');
  const result = await syncPendingActions();
  await updateLastSync();
  onSyncStateChange?.(result.failed > 0 ? 'error' : 'synced');
  return result;
}

// src/services/chatConversations.ts
// Gerenciamento de conversas

import { supabase } from '../config/supabase';
import type { Conversation, ChatMessage, ConversationMember } from '../types';

type RealtimePayload = { new: Record<string, unknown> };

interface PresenceState {
  [key: string]: { user_id: string; online_at: string }[];
}

interface ConversationCallbacks {
  onNewMessage: (payload: RealtimePayload) => void;
  onMessageUpdate: (payload: RealtimePayload) => void;
  onPresenceSync: () => void;
  onPresenceJoin: (key: string, presence: PresenceState[string]) => void;
  onPresenceLeave: (key: string, presence: PresenceState[string]) => void;
}

export interface ConversationResult extends Conversation {
  members: ConversationMember[];
  lastMessage: ChatMessage | null;
  unreadCount: number;
}

export async function getOrCreateDirectConversation(userId1: string, userId2: string): Promise<string> {
  const { data: members1 } = await supabase
    .from('conversation_members')
    .select('conversation_id')
    .eq('user_id', userId1);

  const convIds = (members1 || []).map(m => m.conversation_id);
  if (convIds.length > 0) {
    const { data: existingMember } = await supabase
      .from('conversation_members')
      .select('conversation_id, conversations!inner(type)')
      .in('conversation_id', convIds)
      .eq('user_id', userId2)
      .eq('conversations.type', 'direct')
      .maybeSingle();

    if (existingMember) return existingMember.conversation_id;
  }

  const { data: conv, error } = await supabase.from('conversations')
    .insert({ type: 'direct' }).select().single();
  if (error) throw error;

  await supabase.from('conversation_members').insert([
    { conversation_id: conv.id, user_id: userId1 },
    { conversation_id: conv.id, user_id: userId2 },
  ]);
  return conv.id;
}

export async function createGroupConversation(name: string, userId: string, memberIds: string[]): Promise<string> {
  const { data: conv, error } = await supabase.from('conversations')
    .insert({ type: 'group', name }).select().single();
  if (error) throw error;

  const members = [
    { conversation_id: conv.id, user_id: userId, role: 'admin' },
    ...memberIds.map(id => ({ conversation_id: conv.id, user_id: id })),
  ];
  await supabase.from('conversation_members').insert(members);
  return conv.id;
}

export async function getUserConversations(userId: string): Promise<ConversationResult[]> {
  const { data: memberships } = await supabase
    .from('conversation_members')
    .select('conversation_id, last_read_at')
    .eq('user_id', userId);

  if (!memberships?.length) return [];
  const convIds = memberships.map(m => m.conversation_id);

  const { data: conversations } = await supabase
    .from('conversations')
    .select('*')
    .in('id', convIds)
    .order('updated_at', { ascending: false });

  const results = await Promise.all((conversations || []).map(async (conv) => {
    const { data: members } = await supabase
      .from('conversation_members')
      .select('conversation_id, user_id, profiles:user_id(name, avatar_url)')
      .eq('conversation_id', conv.id);

    const { data: lastMsg } = await supabase
      .from('messages')
      .select('id, conversation_id, user_id, content, type, reply_to, edited, deleted, created_at, profiles:user_id(name, avatar_url)')
      .eq('conversation_id', conv.id)
      .order('created_at', { ascending: false })
      .limit(1)
      .single();

    const membership = memberships.find(m => m.conversation_id === conv.id);
    const { count: unread } = await supabase
      .from('messages')
      .select('id', { count: 'exact', head: true })
      .eq('conversation_id', conv.id)
      .gt('created_at', membership?.last_read_at || '1970-01-01')
      .neq('user_id', userId);

    const membersList = (members || []).map((m: any) => ({
      conversation_id: conv.id,
      user_id: m.user_id,
      profiles: Array.isArray(m.profiles) ? m.profiles[0] : m.profiles,
    })) as ConversationMember[];

    const mappedLastMsg = lastMsg ? {
      ...lastMsg,
      profiles: Array.isArray((lastMsg as any).profiles) ? (lastMsg as any).profiles[0] : (lastMsg as any).profiles,
    } as unknown as ChatMessage : null;

    return {
      ...conv,
      members: membersList,
      lastMessage: mappedLastMsg,
      unreadCount: unread || 0,
    };
  }));

  return results;
}

export async function markAsRead(conversationId: string, userId: string): Promise<void> {
  await supabase.from('conversation_members')
    .update({ last_read_at: new Date().toISOString() })
    .eq('conversation_id', conversationId)
    .eq('user_id', userId);
}

export function subscribeToConversation(conversationId: string, callbacks: ConversationCallbacks): () => void {
  const channel = supabase.channel(`chat-${conversationId}`);
  const anyChannel = channel as any;
  anyChannel
    .on('postgres_changes', { event: 'INSERT', schema: 'public', table: 'messages', filter: `conversation_id=eq.${conversationId}` }, callbacks.onNewMessage)
    .on('postgres_changes', { event: 'UPDATE', schema: 'public', table: 'messages', filter: `conversation_id=eq.${conversationId}` }, callbacks.onMessageUpdate)
    .on('presence', { event: 'sync' }, callbacks.onPresenceSync)
    .on('presence', { event: 'join' }, callbacks.onPresenceJoin)
    .on('presence', { event: 'leave' }, callbacks.onPresenceLeave)
    .subscribe(async (status: string) => {
      if (status === 'SUBSCRIBED') {
        await anyChannel.track({ user_id: '', online_at: new Date().toISOString() });
      }
    });
  return () => supabase.removeChannel(channel);
}

// src/services/coupon.ts
// Serviço de cupons de desconto - NOVAIX FITNESS

import { supabase } from '../config/supabase';

interface DemoCoupon {
  code: string;
  discount: number;
  type: 'percent' | 'fixed' | 'days';
  validUntil: string;
  maxUses: number;
}

const demoCoupons: DemoCoupon[] = [
  { code: 'NOVAIX10', discount: 10, type: 'percent', validUntil: '2026-12-31', maxUses: 100 },
  { code: 'BEMVINDO20', discount: 20, type: 'percent', validUntil: '2026-12-31', maxUses: 50 },
  { code: 'TREINO30', discount: 30, type: 'fixed', validUntil: '2026-12-31', maxUses: 30 },
  { code: 'GRATIS7', discount: 7, type: 'days', validUntil: '2026-12-31', maxUses: 200 },
];

interface CouponData {
  code: string;
  discount: number;
  type: string;
  valid_until?: string;
  max_uses?: number;
  current_uses?: number;
}

interface ValidateResult {
  valid: boolean;
  error?: string;
  code?: string;
  discount?: number;
  type?: string;
  description?: string;
}

export async function validateCoupon(code: string): Promise<ValidateResult> {
  if (!code || code.length < 3) return { valid: false, error: 'Código inválido' };

  const upperCode = code.toUpperCase().trim();

  const demoCoupon = demoCoupons.find(c => c.code === upperCode);
  if (demoCoupon) {
    if (new Date(demoCoupon.validUntil) < new Date()) {
      return { valid: false, error: 'Cupom expirado' };
    }
    return {
      valid: true,
      code: demoCoupon.code,
      discount: demoCoupon.discount,
      type: demoCoupon.type,
      description: getDiscountDescription(demoCoupon),
    };
  }

  try {
    const { data, error } = await supabase
      .from('coupons')
      .select('*')
      .eq('code', upperCode)
      .eq('active', true)
      .single();

    if (error || !data) {
      return { valid: false, error: 'Cupom não encontrado' };
    }

    const couponData = data as CouponData;

    if (couponData.valid_until && new Date(couponData.valid_until) < new Date()) {
      return { valid: false, error: 'Cupom expirado' };
    }

    if (couponData.max_uses && couponData.current_uses && couponData.current_uses >= couponData.max_uses) {
      return { valid: false, error: 'Cupom atingiu limite de uso' };
    }

    return {
      valid: true,
      code: couponData.code,
      discount: couponData.discount,
      type: couponData.type,
      description: getDiscountDescription(couponData),
    };
  } catch (err) {
    return { valid: false, error: 'Erro ao validar cupom' };
  }
}

export function applyCouponToPrice(price: number, coupon: ValidateResult): number {
  if (!coupon || !coupon.valid) return price;

  let finalPrice = price;

  if (coupon.type === 'percent') {
    finalPrice = price * (1 - (coupon.discount || 0) / 100);
  } else if (coupon.type === 'fixed') {
    finalPrice = Math.max(0, price - (coupon.discount || 0));
  } else if (coupon.type === 'days') {
    finalPrice = 0;
  }

  return Math.round(finalPrice * 100) / 100;
}

function getDiscountDescription(coupon: { type: string; discount: number }): string {
  if (coupon.type === 'percent') return `${coupon.discount}% de desconto`;
  if (coupon.type === 'fixed') return `R$ ${coupon.discount} de desconto`;
  if (coupon.type === 'days') return `${coupon.discount} dias grátis`;
  return 'Desconto aplicado';
}

export async function recordCouponUse(code: string, userId: string): Promise<void> {
  if (!code || !userId) return;

  try {
    await supabase
      .from('coupons')
      .update({ current_uses: supabase.rpc('increment_coupon_uses', { coupon_code: code.toUpperCase() }) })
      .eq('code', code.toUpperCase());

    await supabase
      .from('coupon_usage')
      .insert({
        coupon_code: code.toUpperCase(),
        user_id: userId,
        used_at: new Date().toISOString(),
      });
  } catch (err) {
    if (__DEV__) console.error('Erro ao registrar uso do cupom:', err);
  }
}

export async function listCoupons(): Promise<CouponData[]> {
  try {
    const { data, error } = await supabase
      .from('coupons')
      .select('*')
      .order('created_at', { ascending: false });

    if (error) throw error;
    return (data || []) as CouponData[];
  } catch (err) {
    if (__DEV__) console.error('Erro ao listar cupons:', err);
    return demoCoupons as unknown as CouponData[];
  }
}

