import { Platform } from 'react-native';

export function convertToCSV(data, headers) {
  const rows = [headers.join(',')];
  data.forEach(row => {
    const values = headers.map(h => {
      const val = row[h] ?? '';
      const str = String(val);
      return str.includes(',') || str.includes('"') || str.includes('\n')
        ? `"${str.replace(/"/g, '""')}"` : str;
    });
    rows.push(values.join(','));
  });
  return rows.join('\n');
}

export async function saveAndShareCSV(csv, filename) {
  if (Platform.OS === 'web') {
    downloadFile(csv, filename, 'text/csv');
    return;
  }
  const FileSystem = require('expo-file-system');
  const Sharing = require('expo-sharing');
  const fileUri = FileSystem.documentDirectory + filename;
  await FileSystem.writeAsStringAsync(fileUri, csv, { encoding: FileSystem.EncodingType.UTF8 });
  if (await Sharing.isAvailableAsync()) {
    await Sharing.shareAsync(fileUri, { mimeType: 'text/csv', dialogTitle: `Exportar ${filename}` });
  }
  return fileUri;
}

export async function saveAndShareJSON(data, filename) {
  const json = JSON.stringify(data, null, 2);
  if (Platform.OS === 'web') {
    downloadFile(json, filename, 'application/json');
    return;
  }
  const FileSystem = require('expo-file-system');
  const Sharing = require('expo-sharing');
  const fileUri = FileSystem.documentDirectory + filename;
  await FileSystem.writeAsStringAsync(fileUri, json, { encoding: FileSystem.EncodingType.UTF8 });
  if (await Sharing.isAvailableAsync()) {
    await Sharing.shareAsync(fileUri, { mimeType: 'application/json', dialogTitle: `Exportar ${filename}` });
  }
  return fileUri;
}

function downloadFile(content, filename, mimeType) {
  const blob = new Blob([content], { type: mimeType });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = filename;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  URL.revokeObjectURL(url);
}

// src/services/errorTracker.ts
// Servico de rastreamento de erros - NOVAIX FITNESS

import { Platform } from 'react-native';
import { captureError, captureMessage, addBreadcrumb, setTag, setUser } from '../config/sentry';
import { supabase } from '../config/supabase';

export const ERROR_SEVERITY = {
  LOW: 'low',
  MEDIUM: 'warning',
  HIGH: 'error',
  CRITICAL: 'fatal',
} as const;

type SeverityLevel = (typeof ERROR_SEVERITY)[keyof typeof ERROR_SEVERITY];

interface ErrorEntry {
  id: string;
  message: string;
  stack?: string;
  severity: SeverityLevel;
  context: Record<string, unknown>;
  timestamp: string;
  handled: boolean;
  type?: string;
}

interface UserContext {
  id: string;
  subscriptionPlan?: string;
}

class ErrorTracker {
  private errors: ErrorEntry[] = [];
  private maxErrors = 100;

  trackError(error: Error & { handled?: boolean }, context: Record<string, unknown> = {}, severity: SeverityLevel = ERROR_SEVERITY.HIGH): string {
    const errorEntry: ErrorEntry = {
      id: Date.now().toString(36) + Math.random().toString(36).slice(2),
      message: error.message || String(error),
      stack: error.stack,
      severity,
      context,
      timestamp: new Date().toISOString(),
      handled: error.handled || false,
    };

    this.errors.push(errorEntry);
    if (this.errors.length > this.maxErrors) {
      this.errors.shift();
    }

    captureError(error, {
      ...context,
      severity,
      errorId: errorEntry.id,
    });

    this.logToConsole(error, severity, context);
    this.saveToSupabase(errorEntry).catch(() => {});

    return errorEntry.id;
  }

  trackMessage(message: string, severity: SeverityLevel = ERROR_SEVERITY.MEDIUM, context: Record<string, unknown> = {}): string {
    captureMessage(message, severity, context);

    this.logToConsole(new Error(message), severity, context);

    this.saveToSupabase({
      id: Date.now().toString(36),
      message,
      severity,
      context,
      timestamp: new Date().toISOString(),
      type: 'message',
    } as ErrorEntry).catch(() => {});

    return message;
  }

  trackUserError(error: Error, userId: string, screen: string): string {
    return this.trackError(error, {
      userId,
      screen,
      type: 'user_error',
    }, ERROR_SEVERITY.MEDIUM);
  }

  trackAPIError(error: Error, endpoint: string, method: string, statusCode: number): string {
    return this.trackError(error, {
      endpoint,
      method,
      statusCode,
      type: 'api_error',
    }, ERROR_SEVERITY.HIGH);
  }

  trackNetworkError(error: Error, url: string): string {
    return this.trackError(error, {
      url,
      type: 'network_error',
    }, ERROR_SEVERITY.MEDIUM);
  }

  trackPerformance(metric: string, value: number, context: Record<string, unknown> = {}): void {
    addBreadcrumb('performance', `${metric}: ${value}`, context);

    if (value > 1000) {
      this.trackMessage(`Slow ${metric}: ${value}ms`, ERROR_SEVERITY.LOW, {
        metric,
        value,
        ...context,
      });
    }
  }

  trackCrash(error: Error): string {
    return this.trackError(error, {
      type: 'crash',
      fatal: true,
    }, ERROR_SEVERITY.CRITICAL);
  }

  setUserContext(user: UserContext | null): void {
    if (user) {
      setUser(user);
      setTag('userId', user.id);
      setTag('userPlan', user.subscriptionPlan || 'free');
    } else {
      setUser(null);
    }
  }

  setScreenContext(screenName: string): void {
    setTag('currentScreen', screenName);
    addBreadcrumb('navigation', `Screen: ${screenName}`);
  }

  setFeatureContext(feature: string): void {
    setTag('activeFeature', feature);
  }

  addBreadcrumb(category: string, message: string, data: Record<string, unknown> = {}): void {
    addBreadcrumb(category, message, data);
  }

  getRecentErrors(count: number = 10): ErrorEntry[] {
    return this.errors.slice(-count);
  }

  clearErrors(): void {
    this.errors = [];
  }

  private logToConsole(error: Error, severity: SeverityLevel, context: Record<string, unknown>): void {
    if (!__DEV__) return;

    const prefix = `[ErrorTracker:${severity}]`;
    switch (severity) {
      case ERROR_SEVERITY.CRITICAL:
      case ERROR_SEVERITY.HIGH:
        console.error(prefix, error.message, context);
        break;
      case ERROR_SEVERITY.MEDIUM:
        console.warn(prefix, error.message, context);
        break;
      default:
        if (__DEV__) console.info(prefix, error.message, context);
    }
  }

  private async saveToSupabase(errorEntry: ErrorEntry): Promise<void> {
    try {
      await supabase.from('error_logs').insert({
        error_id: errorEntry.id,
        message: errorEntry.message,
        stack: errorEntry.stack,
        severity: errorEntry.severity,
        context: errorEntry.context,
        platform: Platform.OS,
        app_version: '1.0.0',
      });
    } catch {}
  }
}

export const errorTracker = new ErrorTracker();
export default errorTracker;

// src/services/gemini.ts
// Integracao com Gemini API + Historico - NOVAIX FITNESS

import { supabase } from '../config/supabase';
import { APP_CONFIG } from '../config/app';
import { GOOGLE_API_KEY } from '../config/api';
import { sanitizeAIOutput } from '../utils/aiSanitize';

interface ProfileContext {
  userId?: string;
  subscriptionPlan?: string;
  weight?: number;
  goal?: string;
  gymType?: string;
  level?: string;
}

interface ChatMessage {
  id: string;
  text: string;
  isUser: boolean;
}

interface MealMacros {
  calories: number;
  protein: number;
  carbs: number;
  fat: number;
}

export async function askGeminiCoach(
  message: string,
  profileContext: ProfileContext = {},
  conversationHistory: unknown[] = [],
): Promise<string> {
  const plan = profileContext.subscriptionPlan || 'free';
  const limit = (APP_CONFIG.plans as Record<string, { maxMessages?: number }>)[plan]?.maxMessages ?? 0;

  if (profileContext.userId) {
    const today = new Date();
    today.setHours(0, 0, 0, 0);

    const { count, error } = await supabase
      .from('coach_chat_messages')
      .select('id', { count: 'exact', head: true })
      .eq('user_id', profileContext.userId)
      .eq('is_user', true)
      .gte('created_at', today.toISOString());

    if (error) {
      if (__DEV__) console.error('Erro ao verificar limite:', error);
    } else if (count && count > limit) {
      throw new Error('LIMIT_EXCEEDED');
    }
  }

  try {
    const { data: { session } } = await supabase.auth.getSession();
    const token = session?.access_token;
    const API_BASE = process.env.EXPO_PUBLIC_API_URL;

    const response = await fetch(`${API_BASE}/api/ai/coach`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${token}`,
      },
      body: JSON.stringify({
        message,
        weight: profileContext.weight,
        goal: profileContext.goal,
        gymType: profileContext.gymType,
        level: profileContext.level,
      }),
    });

    const data = await response.json();
    if (!response.ok) {
      throw new Error(data.error || 'Erro no chat de IA');
    }
    return sanitizeAIOutput(data.response);
  } catch (error) {
    if (__DEV__) console.error('Erro Gemini API:', error);
    return 'Erro ao conectar com o assistente. Verifique sua conexão e tente novamente.';
  }
}


