// src/services/liveWorkouts.ts
// Serviço de lives de treino

import { supabase } from '../config/supabase';
import type { LiveWorkout, LiveParticipant, LiveMessage, LiveWorkoutState, LiveStatus } from '../types';

type RealtimePayload = { new: Record<string, unknown> };

interface LiveCallbacks {
  onMessage: (payload: RealtimePayload) => void;
  onParticipant: (payload: RealtimePayload) => void;
  onState: (payload: RealtimePayload) => void;
  onLiveUpdate: (payload: RealtimePayload) => void;
}

interface CreateLiveParams {
  title: string;
  description?: string;
  workoutType?: string;
  isPublic?: boolean;
}

export async function createLive(hostId: string, { title, description, workoutType, isPublic }: CreateLiveParams): Promise<LiveWorkout> {
  const { data, error } = await supabase
    .from('live_workouts')
    .insert({
      host_id: hostId,
      title,
      description: description || null,
      workout_type: workoutType || 'general',
      is_public: isPublic !== false,
    })
    .select()
    .single();

  if (error) throw error;

  await supabase.from('live_participants').insert({
    live_id: data.id,
    user_id: hostId,
    role: 'host',
  });

  await supabase.from('live_workout_state').insert({
    live_id: data.id,
    timer_seconds: 0,
  });

  return data as LiveWorkout;
}

export async function startLive(liveId: string): Promise<void> {
  const { error } = await supabase
    .from('live_workouts')
    .update({ status: 'live', started_at: new Date().toISOString() })
    .eq('id', liveId);

  if (error) throw error;
}

export async function endLive(liveId: string): Promise<void> {
  const { error } = await supabase
    .from('live_workouts')
    .update({ status: 'ended', ended_at: new Date().toISOString() })
    .eq('id', liveId);

  if (error) throw error;
}

export async function joinLive(liveId: string, userId: string): Promise<LiveParticipant> {
  const { data: existing } = await supabase
    .from('live_participants')
    .select('id')
    .eq('live_id', liveId)
    .eq('user_id', userId)
    .single();

  if (existing) return existing as LiveParticipant;

  const { data, error } = await supabase
    .from('live_participants')
    .insert({ live_id: liveId, user_id: userId, role: 'participant' })
    .select()
    .single();

  if (error) throw error;

  await supabase.rpc('increment_column', {
    table_name: 'live_workouts',
    column_name: 'participant_count',
    row_id: liveId,
  });

  return data as LiveParticipant;
}

export async function leaveLive(liveId: string, userId: string): Promise<void> {
  await supabase
    .from('live_participants')
    .update({ left_at: new Date().toISOString() })
    .eq('live_id', liveId)
    .eq('user_id', userId);

  await supabase.rpc('decrement_column', {
    table_name: 'live_workouts',
    column_name: 'participant_count',
    row_id: liveId,
  });
}

export async function getActiveLives(): Promise<LiveWorkout[]> {
  const { data } = await supabase
    .from('live_workouts')
    .select('*, profiles:host_id(name, avatar_url), live_participants(count)')
    .in('status', ['live', 'scheduled'])
    .order('created_at', { ascending: false });

  return (data || []) as LiveWorkout[];
}

export async function getLiveById(liveId: string): Promise<LiveWorkout | null> {
  const { data } = await supabase
    .from('live_workouts')
    .select('*, profiles:host_id(name, avatar_url)')
    .eq('id', liveId)
    .single();

  return data as LiveWorkout | null;
}

export async function getLiveParticipants(liveId: string): Promise<LiveParticipant[]> {
  const { data } = await supabase
    .from('live_participants')
    .select('*, profiles:user_id(name, avatar_url)')
    .eq('live_id', liveId)
    .is('left_at', null)
    .order('joined_at', { ascending: true });

  return (data || []) as LiveParticipant[];
}

export async function sendMessage(liveId: string, userId: string, message: string, type: string = 'chat'): Promise<LiveMessage> {
  const { data, error } = await supabase
    .from('live_messages')
    .insert({ live_id: liveId, user_id: userId, message, type })
    .select('*, profiles:user_id(name, avatar_url)')
    .single();

  if (error) throw error;
  return data as LiveMessage;
}

export async function getLiveMessages(liveId: string, limit: number = 50): Promise<LiveMessage[]> {
  const { data } = await supabase
    .from('live_messages')
    .select('*, profiles:user_id(name, avatar_url)')
    .eq('live_id', liveId)
    .order('created_at', { ascending: true })
    .limit(limit);

  return (data || []) as LiveMessage[];
}

export async function updateWorkoutState(liveId: string, state: Partial<LiveWorkoutState>): Promise<void> {
  const { error } = await supabase
    .from('live_workout_state')
    .update({ ...state, updated_at: new Date().toISOString() })
    .eq('live_id', liveId);

  if (error) throw error;
}

export async function getWorkoutState(liveId: string): Promise<LiveWorkoutState | null> {
  const { data } = await supabase
    .from('live_workout_state')
    .select('*')
    .eq('live_id', liveId)
    .single();

  return data as LiveWorkoutState | null;
}

export function subscribeToLive(liveId: string, callbacks: LiveCallbacks): () => void {
  const channel = supabase
    .channel(`live-${liveId}`)
    .on('postgres_changes', { event: '*', schema: 'public', table: 'live_messages', filter: `live_id=eq.${liveId}` }, callbacks.onMessage)
    .on('postgres_changes', { event: '*', schema: 'public', table: 'live_participants', filter: `live_id=eq.${liveId}` }, callbacks.onParticipant)
    .on('postgres_changes', { event: 'UPDATE', schema: 'public', table: 'live_workout_state', filter: `live_id=eq.${liveId}` }, callbacks.onState)
    .on('postgres_changes', { event: 'UPDATE', schema: 'public', table: 'live_workouts', filter: `id=eq.${liveId}` }, callbacks.onLiveUpdate)
    .subscribe();

  return () => supabase.removeChannel(channel);
}

// src/services/notificationScheduler.js
// Servico de agendamento de notificacoes - NOVAIX FITNESS

import * as Notifications from 'expo-notifications';
import { supabase } from '../config/supabase';
import type { NotificationTriggerInput } from 'expo-notifications';

const SCHEDULED_IDENTIFIERS = new Map<string, string[]>();

export async function scheduleWorkoutReminder(userId: string, hour: number, minute: number, days: number[]) {
  await cancelSchedByType(userId, 'workout_reminder');

  const identifiers: string[] = [];
  for (const day of days) {
    const id = await Notifications.scheduleNotificationAsync({
      content: {
        title: 'Hora de treinar!',
        body: 'Seu treino de hoje esta esperando. Bora!',
        data: { type: 'workout_reminder' },
      },
      trigger: {
        weekday: day,
        hour,
        minute,
        repeats: true,
      } as NotificationTriggerInput,
    });
    identifiers.push(id);
  }

  SCHEDULED_IDENTIFIERS.set(`workout_reminder_${userId}`, identifiers);
  return identifiers;
}

export async function scheduleWeeklyPlanReminder(userId: string) {
  const id = await Notifications.scheduleNotificationAsync({
    content: {
      title: 'Novo plano da semana!',
      body: 'Seus treinos da semana estao prontos. Confira agora.',
      data: { type: 'weekly_plan' },
    },
    trigger: {
      weekday: 1,
      hour: 8,
      minute: 0,
      repeats: true,
    } as NotificationTriggerInput,
  });

  SCHEDULED_IDENTIFIERS.set(`weekly_plan_${userId}`, [id]);
  return id;
}

export async function scheduleStreakProtection(userId: string, streakDays: number) {
  if (streakDays < 3) return null;

  const id = await Notifications.scheduleNotificationAsync({
    content: {
      title: `${streakDays} dias seguidos!`,
      body: 'Nao perca seu streak! Treine hoje para manter a sequencia.',
      data: { type: 'streak_reminder' },
    },
    trigger: {
      hour: 18,
      minute: 0,
      repeats: true,
    } as NotificationTriggerInput,
  });

  SCHEDULED_IDENTIFIERS.set(`streak_${userId}`, [id]);
  return id;
}

export async function scheduleWeeklySummary(userId: string) {
  const id = await Notifications.scheduleNotificationAsync({
    content: {
      title: 'Resumo da semana',
      body: 'Veja como foi seu desempenho esta semana.',
      data: { type: 'weekly_summary' },
    },
    trigger: {
      weekday: 0,
      hour: 20,
      minute: 0,
      repeats: true,
    } as NotificationTriggerInput,
  });

  SCHEDULED_IDENTIFIERS.set(`weekly_summary_${userId}`, [id]);
  return id;
}

export async function scheduleMotivational(userId: string, hour = 19, minute = 30) {
  const messages = [
    'Voce esta indo muito bem! Continue assim!',
    'Cada treino te leva mais perto do seu objetivo.',
    'A consistencia e a chave do sucesso.',
    'Seu corpo agradece cada esforco!',
  ];

  const id = await Notifications.scheduleNotificationAsync({
    content: {
      title: 'Mensagem do dia',
      body: messages[Math.floor(Math.random() * messages.length)],
      data: { type: 'motivational' },
    },
    trigger: {
      weekday: 2,
      hour,
      minute,
      repeats: true,
    } as NotificationTriggerInput,
  });

  SCHEDULED_IDENTIFIERS.set(`motivational_${userId}`, [id]);
  return id;
}

export async function cancelAllScheduled(userId: string) {
  const types = ['workout_reminder', 'weekly_plan', 'streak', 'weekly_summary', 'motivational'];
  for (const type of types) {
    await cancelSchedByType(userId, type);
  }
  await Notifications.cancelAllScheduledNotificationsAsync();
}

async function cancelSchedByType(userId: string, type: string) {
  const key = `${type}_${userId}`;
  const ids = SCHEDULED_IDENTIFIERS.get(key);
  if (ids) {
    for (const id of ids) {
      await Notifications.cancelScheduledNotificationAsync(id);
    }
    SCHEDULED_IDENTIFIERS.delete(key);
  }
}

export async function getScheduledReminders(userId: string) {
  const all = await Notifications.getAllScheduledNotificationsAsync();
  return all.filter(n => n.content.data?.type);
}

interface ReminderSettings {
  workoutReminder?: { enabled?: boolean; hour?: number; minute?: number; days?: number[] };
  weeklyPlan?: boolean;
  streakProtection?: boolean;
  streakDays?: number;
  weeklySummary?: boolean;
  motivational?: boolean;
}

export async function setupUserReminders(userId: string, settings: ReminderSettings) {
  await cancelAllScheduled(userId);

  if (settings.workoutReminder?.enabled) {
    const { hour, minute, days } = settings.workoutReminder;
    await scheduleWorkoutReminder(userId, hour || 19, minute || 0, days || [1, 2, 3, 4, 5]);
  }

  if (settings.weeklyPlan) {
    await scheduleWeeklyPlanReminder(userId);
  }

  if (settings.streakProtection) {
    await scheduleStreakProtection(userId, settings.streakDays || 0);
  }

  if (settings.weeklySummary) {
    await scheduleWeeklySummary(userId);
  }

  if (settings.motivational) {
    await scheduleMotivational(userId);
  }
}

// src/services/notifications.ts
// Serviço de push notifications - NOVAIX FITNESS

import * as Notifications from 'expo-notifications';
import * as Device from 'expo-device';
import { Platform } from 'react-native';
import { supabase } from '../config/supabase';
import { createServiceGuard } from '../utils/serviceGuard';
import type { Achievement } from '../types';

const guard = createServiceGuard({ serviceName: 'notifications' });

Notifications.setNotificationHandler({
  handleNotification: async () => ({
    shouldShowAlert: true,
    shouldPlaySound: true,
    shouldSetBadge: true,
  } as any),
});

export async function requestNotificationPermission(): Promise<boolean> {
  return guard.guard(async () => {
    if (!Device.isDevice) {
      return false;
    }

    const { status: existingStatus } = await Notifications.getPermissionsAsync();
    let finalStatus = existingStatus;

    if (existingStatus !== 'granted') {
      const { status } = await Notifications.requestPermissionsAsync();
      finalStatus = status;
    }

    if (finalStatus !== 'granted') {
      return false;
    }

    const token = await Notifications.getExpoPushTokenAsync();

    const { data: { user } } = await supabase.auth.getUser();
    if (user) {
      await supabase
        .from('profiles')
        .update({ push_token: token.data })
        .eq('id', user.id);
    }

    if (Platform.OS === 'android') {
      await Notifications.setNotificationChannelAsync('default', {
        name: 'Default',
        importance: Notifications.AndroidImportance.MAX,
        vibrationPattern: [0, 250, 250, 250],
        lightColor: '#CCFF00',
      });

      await Notifications.setNotificationChannelAsync('workout', {
        name: 'Treinos',
        importance: Notifications.AndroidImportance.HIGH,
        vibrationPattern: [0, 250, 250, 250],
        lightColor: '#CCFF00',
        description: 'Lembretes de treino e conquistas',
      });

      await Notifications.setNotificationChannelAsync('social', {
        name: 'Social',
        importance: Notifications.AndroidImportance.DEFAULT,
        vibrationPattern: [0, 250],
        lightColor: '#CCFF00',
        description: 'Novos seguidores, curtidas e comentários',
      });
    }

    return true;
  }).then(r => r.ok ? r.data : false);
}

export async function scheduleWorkoutReminder(hour: number, minute: number, day: number): Promise<string | null> {
  const result = await guard.guard(async () => {
    return Notifications.scheduleNotificationAsync({
      content: {
        title: 'Hora de treinar!',
        body: 'Seu treino personalizado está esperando por você.',
        data: { type: 'workout_reminder' },
        sound: true,
      },
      trigger: {
        type: Notifications.SchedulableTriggerInputTypes.CALENDAR,
        hour,
        minute,
        repeats: true,
        weekday: day,
      },
    });
  });
  return result.ok ? result.data : null;
}

export async function scheduleAchievementNotification(achievement: Achievement): Promise<void> {
  await Notifications.scheduleNotificationAsync({
    content: {
      title: 'Nova conquista desbloqueada! 🏆',
      body: `Parabéns! Você desbloqueou: ${achievement.name}`,
      data: { type: 'achievement', achievementId: achievement.id },
      sound: true,
    },
    trigger: null,
  });
}

export async function scheduleStreakReminder(streakCount: number): Promise<void> {
  await Notifications.scheduleNotificationAsync({
    content: {
      title: `${streakCount} dias seguidos! 🔥`,
      body: 'Não queime sua sequência! Treine hoje para manter o hábito.',
      data: { type: 'streak_reminder', streak: streakCount },
      sound: true,
    },
    trigger: null,
  });
}

export async function cancelAllNotifications(): Promise<void> {
  await Notifications.cancelAllScheduledNotificationsAsync();
}

export async function cancelNotification(identifier: string): Promise<void> {
  await Notifications.cancelScheduledNotificationAsync(identifier);
}

export async function getScheduledNotifications(): Promise<Notifications.NotificationRequest[]> {
  return await Notifications.getAllScheduledNotificationsAsync();
}

export function addNotificationListener(
  handler: (notification: Notifications.Notification) => void,
): Notifications.Subscription {
  return Notifications.addNotificationReceivedListener(handler);
}

export function addNotificationResponseListener(
  handler: (response: Notifications.NotificationResponse) => void,
): Notifications.Subscription {
  return Notifications.addNotificationResponseReceivedListener(handler);
}

export async function clearBadgeCount(): Promise<void> {
  await Notifications.setBadgeCountAsync(0);
}

export async function getUnreadCount(userId: string): Promise<number> {
  const result = await guard.guardSupabase(async () => {
    const { count, error } = await supabase
      .from('notifications')
      .select('id', { count: 'exact', head: true })
      .eq('user_id', userId)
      .eq('read', false);
    return { data: count || 0, error };
  });
  return result.ok ? result.data : 0;
}

