// src/services/offline.tsx
// Sistema offline - re-exportacao

export { cacheWorkouts, getCachedWorkouts, cacheFavorites, getCachedFavorites, cacheProfile, getCachedProfile, cacheWorkoutDetail, getCachedWorkoutDetail, isWorkoutCached, updateLastSync, getLastSync } from './offlineCache';
export { addPendingAction, getPendingActions, clearPendingAction, clearAllPendingActions, cacheExerciseLogs, getCachedExerciseLogs } from './offlinePending';

import AsyncStorage from '@react-native-async-storage/async-storage';

const CACHE_TTL = 7 * 24 * 60 * 60 * 1000;

export async function clearOldCache() {
  try {
    const keys = await AsyncStorage.getAllKeys();
    const oldKeys = keys.filter(k => {
      if (!k.startsWith('@novaix:')) return false;
      if (k.includes('profile') || k.includes('settings')) return false;
      return true;
    });
    for (const key of oldKeys) {
      const raw = await AsyncStorage.getItem(key);
      if (raw) {
        const data = JSON.parse(raw);
        if (data.timestamp && Date.now() - data.timestamp > CACHE_TTL) {
          await AsyncStorage.removeItem(key);
        }
      }
    }
  } catch (err) {
    if (__DEV__) console.error('Erro ao limpar cache antigo:', err);
  }
}

export async function getCacheSize() {
  try {
    const keys = await AsyncStorage.getAllKeys();
    const novaixKeys = keys.filter(k => k.startsWith('@novaix:'));
    let totalSize = 0;
    for (const key of novaixKeys) {
      const raw = await AsyncStorage.getItem(key);
      if (raw) totalSize += raw.length * 2;
    }
    return { keys: novaixKeys.length, sizeBytes: totalSize, sizeMB: (totalSize / 1024 / 1024).toFixed(2) };
  } catch { return { keys: 0, sizeBytes: 0, sizeMB: '0' }; }
}

// src/services/pdfReport.js
// Relatório mensal em PDF

import * as Print from 'expo-print';
import * as Sharing from 'expo-sharing';
import { supabase } from '../config/supabase';

interface ReportWorkout {
  title?: string;
  completed_at: string;
  duration?: number;
}

interface ReportData {
  month: number;
  year: number;
  totalWorkouts: number;
  totalMinutes: number;
  totalWater: number;
  goalsCompleted: number;
  workouts: ReportWorkout[];
}

export async function generateMonthlyReport(userId: string, month: number, year: number) {
  if (!userId) return null;

  const startDate = new Date(year, month - 1, 1).toISOString();
  const endDate = new Date(year, month, 0).toISOString();

  const [workouts, meals, water, goals] = await Promise.all([
    supabase.from('user_workouts').select('*').eq('user_id', userId).eq('completed', true).gte('completed_at', startDate).lte('completed_at', endDate),
    supabase.from('user_meal_plans').select('*').eq('user_id', userId).single(),
    supabase.from('water_logs').select('amount_ml').eq('user_id', userId).gte('logged_at', startDate).lte('logged_at', endDate),
    supabase.from('short_term_goals').select('*').eq('user_id', userId),
  ]);

  const totalWorkouts = workouts.data?.length || 0;
  const totalMinutes = workouts.data?.reduce((s: number, w: Record<string, unknown>) => s + ((w.duration as number) || 0), 0) || 0;
  const totalWater = water.data?.reduce((s: number, w: Record<string, unknown>) => s + (w.amount_ml as number), 0) || 0;
  const goalsCompleted = goals.data?.filter((g: Record<string, unknown>) => g.completed)?.length || 0;

  const html = generateReportHTML({ month, year, totalWorkouts, totalMinutes, totalWater, goalsCompleted, workouts: (workouts.data || []) as unknown as ReportWorkout[] });

  try {
    const { uri } = await Print.printToFileAsync({ html, base64: false });
    if (await Sharing.isAvailableAsync()) {
      await Sharing.shareAsync(uri, { mimeType: 'application/pdf', dialogTitle: 'Relatório NOVAIX' });
    }
    return uri;
  } catch (error) {
    if (__DEV__) console.error('Erro ao gerar PDF:', error);
    return null;
  }
}

function generateReportHTML(data: ReportData): string {
  return `
<!DOCTYPE html>
<html>
<head>
  <style>
    body { font-family: Arial, sans-serif; padding: 20px; color: #333; }
    h1 { color: #CCFF00; font-size: 24px; margin-bottom: 5px; }
    h2 { color: #1E232A; font-size: 18px; margin-top: 20px; border-bottom: 2px solid #CCFF00; padding-bottom: 5px; }
    .stat { display: inline-block; width: 30%; text-align: center; margin: 10px 0; }
    .stat-value { font-size: 28px; font-weight: bold; color: #CCFF00; }
    .stat-label { font-size: 12px; color: #666; }
    .workout-item { padding: 8px 0; border-bottom: 1px solid #eee; }
    .workout-name { font-weight: bold; }
    .workout-meta { font-size: 12px; color: #666; }
    .footer { margin-top: 30px; text-align: center; font-size: 11px; color: #999; }
  </style>
</head>
<body>
  <h1>NOVAIX FITNESS</h1>
  <p>Relatório Mensal - ${data.month}/${data.year}</p>

  <h2>Resumo</h2>
  <div class="stat"><div class="stat-value">${data.totalWorkouts}</div><div class="stat-label">Treinos</div></div>
  <div class="stat"><div class="stat-value">${data.totalMinutes}</div><div class="stat-label">Minutos</div></div>
  <div class="stat"><div class="stat-value">${Math.round(data.totalWater / 1000)}L</div><div class="stat-label">Água</div></div>

  <h2>Treinos Realizados</h2>
  ${data.workouts.map((w: ReportWorkout) => `<div class="workout-item"><div class="workout-name">${w.title || 'Treino'}</div><div class="workout-meta">${new Date(w.completed_at).toLocaleDateString('pt-BR')} - ${w.duration || 0}min</div></div>`).join('')}

  <h2>Metas</h2>
  <p>${data.goalsCompleted} meta(s) concluída(s)</p>

  <div class="footer">Gerado por NOVAIX Fitness - Seu Coach Pessoal</div>
</body>
</html>`;
}

// src/services/planAdaptation.js
// Sistema de adaptação inteligente multimodal - NOVAIX FITNESS

import { supabase } from '../config/supabase';
import { analyzeProgression, applyProgression } from './progressionEngine';

const ADAPTATION_THRESHOLDS = {
  MIN_SESSIONS_FOR_ADAPT: 6,
  WEEKS_BETWEEN_ADAPTS: 4,
};

export interface UserPerformance {
  completionRate: number;
  consistency: number;
  totalSessions: number;
  exerciseLogs: any[];
  lastAdaptation: string | undefined;
  weeksSinceAdaptation: number;
}

export async function analyzeUserPerformance(userId: string): Promise<UserPerformance | null> {
  if (!userId) return null;
  try {
    const fourWeeksAgo = new Date(Date.now() - 28 * 86400000).toISOString();
    const [recentWorkouts, logs] = await Promise.all([
      supabase.from('user_workouts').select('*, workouts(category)').eq('user_id', userId).gte('completed_at', fourWeeksAgo).order('completed_at', { ascending: false }),
      supabase.from('user_exercise_logs').select('*').eq('user_id', userId).gte('created_at', fourWeeksAgo),
    ]);
    const recent = recentWorkouts.data || [];
    const exerciseLogs = logs.data || [];
    const completionRate = recent.length > 0 ? recent.filter(w => w.completed).length / recent.length : 0;
    const consistency = calculateConsistency(recent);
    const lastAdaptation = await getLastAdaptation(userId);
    const lastAdaptationTime = lastAdaptation ? (lastAdaptation.adapted_at || lastAdaptation.created_at) as string : undefined;
    
    return {
      completionRate,
      consistency,
      totalSessions: recent.length,
      exerciseLogs,
      lastAdaptation: lastAdaptationTime,
      weeksSinceAdaptation: lastAdaptationTime ? Math.floor((Date.now() - new Date(lastAdaptationTime).getTime()) / (7 * 86400000)) : 99,
    };
  } catch (err: unknown) { if (__DEV__) console.error('Erro ao analisar performance:', err); return null; }
}

function calculateConsistency(workouts: Record<string, any>[]): number {
  if (workouts.length < 2) return 1;
  const dates = workouts.map(w => new Date(w.completed_at || w.created_at).toDateString());
  const uniqueDays = new Set(dates).size;
  const timestamps = workouts.map(w => new Date(w.completed_at || w.created_at).getTime());
  const oldestTimestamp = Math.min(...timestamps);
  const weeksSpan = Math.max(1, (Date.now() - oldestTimestamp) / (7 * 86400000));
  return Math.min(1, uniqueDays / (weeksSpan * 3));
}

export async function shouldAdaptPlan(userId: string): Promise<boolean> {
  const performance = await analyzeUserPerformance(userId);
  if (!performance) return false;
  if (performance.totalSessions < ADAPTATION_THRESHOLDS.MIN_SESSIONS_FOR_ADAPT) return false;
  if (performance.weeksSinceAdaptation < ADAPTATION_THRESHOLDS.WEEKS_BETWEEN_ADAPTS) return false;
  return true;
}

export function adaptExercise(exercise: Record<string, unknown>, modality: string): Record<string, unknown> {
  const progression = analyzeProgression(modality, []);
  return applyProgression(exercise, progression);
}

export function getWorkoutModality(workout: Record<string, unknown>): string {
  const cat = ((workout?.category || workout?.focus || '') as string).toLowerCase();
  if (cat.includes('cardio') || cat.includes('corrida')) return 'cardio';
  if (cat.includes('calistenia') || cat.includes('bodyweight')) return 'calisthenics';
  if (cat.includes('dança') || cat.includes('dance') || cat.includes('zumba')) return 'dance';
  if (cat.includes('yoga') || cat.includes('pilates')) return 'yoga';
  if (cat.includes('hiit')) return 'hiit';
  return 'gym';
}

export async function adaptWorkoutPlan(userId: string, plan: any, performance: any): Promise<any> {
  const adaptedWeek = plan.week.map((workout: any) => {
    const modality = getWorkoutModality(workout);
    const adaptedExercises = (workout.exercises || []).map((ex: any) => adaptExercise(ex, modality));
    return {
      ...workout,
      exercises: adaptedExercises,
    };
  });
  return { week: adaptedWeek };
}

export async function saveAdaptation(userId: string, oldPlan: Record<string, unknown>, newPlan: Record<string, unknown>, reason: string): Promise<void> {
  if (!userId) return;
  try {
    await supabase.from('plan_adaptations').insert({ user_id: userId, old_plan: oldPlan, new_plan: newPlan, reason, adapted_at: new Date().toISOString() });
    await supabase.from('user_plans').delete().eq('user_id', userId).eq('is_active', true);
    const week = newPlan.week as Array<{ name: string; focus?: string; duration?: number; exercises?: unknown[]; day: string }>;
    const workouts = week.map(day => ({
      user_id: userId, title: day.name, category: day.focus || 'Treino', duration_minutes: day.duration || 60,
      exercises: JSON.stringify(day.exercises || []), day_of_week: day.day, is_active: true,
    }));
    await supabase.from('user_plans').upsert(workouts, { onConflict: 'user_id,day_of_week' });
  } catch (err: unknown) { if (__DEV__) console.error('Erro ao salvar adaptação:', err); }
}

export async function getLastAdaptation(userId: string): Promise<Record<string, unknown> | null> {
  if (!userId) return null;
  try {
    const { data } = await supabase.from('plan_adaptations').select('*').eq('user_id', userId).order('adapted_at', { ascending: false }).limit(1).single();
    return data;
  } catch { return null; }
}

export function getAdaptationReason(performance: UserPerformance): string {
  if (performance.completionRate < 0.5) return 'Reduzindo volume para melhor execução';
  if (performance.completionRate > 0.85) return 'Aumentando desafio';
  return 'Atualização periódica';
}

