export function generateFallbackWorkoutPlan(ctx: Record<string, unknown>): Record<string, unknown> {
  const level = (ctx?.level as string) || 'intermediate';
  const levelStr = (ctx?.level as string) || 'intermediate';
  const mappedLevel = (levelStr === 'iniciante' ? 'beginner' : levelStr === 'avancado' ? 'advanced' : 'intermediate') as DifficultyLevel;
  const rawInjuries = (ctx?.injuries as any[]) || [];
  const mappedInjuries = rawInjuries.map(i => typeof i === 'string' ? i : i.bodyPart || '');
  const exercises = getAvailableExercises({ level: mappedLevel, injuries: mappedInjuries, gymType: (ctx?.gymType as string) || 'gym' });

  const muscleGroups = ['chest', 'back', 'legs', 'shoulders', 'arms'];
  const daySplits = [
    { day: 'Segunda', name: 'Peito e Triceps', focus: 'MUSCULAÇÃO', muscles: ['chest'] },
    { day: 'Terca', name: 'Costas e Biceps', focus: 'MUSCULAÇÃO', muscles: ['back'] },
    { day: 'Quarta', name: 'Cardio', focus: 'CARDIO', muscles: [] },
    { day: 'Quinta', name: 'Pernas', focus: 'MUSCULAÇÃO', muscles: ['legs'] },
    { day: 'Sexta', name: 'Ombros e Braços', focus: 'MUSCULAÇÃO', muscles: ['shoulders', 'arms'] },
  ];

  const cardioExercises = [
    { name: 'Burpee', sets: 4, reps: '10', rest: 30, muscle: 'full_body' },
    { name: 'Mountain Climber', sets: 4, reps: '20', rest: 30, muscle: 'core' },
    { name: 'Agachamento com Salto', sets: 4, reps: '15', rest: 30, muscle: 'legs' },
    { name: 'Prancha', sets: 3, reps: '45s', rest: 30, muscle: 'core' },
  ];

  const week = daySplits.map(split => {
    if (split.muscles.length === 0) {
      return { day: split.day, name: split.name, focus: split.focus, exercises: cardioExercises, duration: 35 };
    }

    const dayExercises = exercises
      .filter(ex => split.muscles.some(m => ex.muscles?.includes(m) || ex.muscleGroup === m))
      .slice(0, 5)
      .map(ex => ({
        name: ex.name,
        sets: level === 'advanced' ? 4 : 3,
        reps: level === 'beginner' ? '12-15' : '10-12',
        rest: 60,
        muscle: ex.muscleGroup || split.muscles[0],
      }));

    return {
      day: split.day,
      name: split.name,
      focus: split.focus,
      exercises: dayExercises.length > 0 ? dayExercises : [{ name: 'Exercicio base', sets: 3, reps: '10-12', rest: 60, muscle: split.muscles[0] }],
      duration: 50,
    };
  });

  return {
    week,
    summary: {
      totalWorkouts: 5,
      musclesWorked: muscleGroups,
      tips: ['Descanse 48h entre grupos musculares', 'Beba 2.5L de agua diariamente', 'Aqueca 5-10 min antes de treinar'],
    },
  };
}

// src/services/planGenerator.js
// Gerador de planos - COM MIDDLEWARES

import { supabase } from '../config/supabase';
import { APP_CONFIG } from '../config/app';
import { GOOGLE_API_KEY } from '../config/api';
import { getAvailableExercises, DifficultyLevel } from '../data/exerciseCatalog';
import { validate } from '../middleware/validation';
import { sanitizeAIOutput } from '../utils/aiSanitize';
import { MEAL_PLAN_SYSTEM_INSTRUCTION, WORKOUT_PLAN_SYSTEM_INSTRUCTION } from './aiSystemInstructions';
import { generateFallbackMealPlan, generateFallbackWorkoutPlan } from './planFallback';

export async function generateMealPlan(profileContext: Record<string, unknown> = {}): Promise<Record<string, unknown> | null> {
  const apiKey = GOOGLE_API_KEY;
  const { weight = 70, height = 170, age = 25, goal = 'manter', dietaryRestrictions = '' } = profileContext as { weight: number; height: number; age: number; goal: string; dietaryRestrictions: string };

  const weightCheck = validate('weight', weight);
  if (!weightCheck.valid) throw new Error(weightCheck.error);
  const heightCheck = validate('height', height);
  if (!heightCheck.valid) throw new Error(heightCheck.error);

  const systemPrompt = `${MEAL_PLAN_SYSTEM_INSTRUCTION}

Formato de saida esperado:
{
  "week": [
    {
      "day": "Segunda",
      "meals": [
        {"type": "cafe", "name": "Cafe da Manha", "items": ["item1", "item2"], "calories": 400, "protein": 30, "carbs": 45, "fat": 12},
        {"type": "almoco", "name": "Almoco", "items": [...], "calories": 600, "protein": 40, "carbs": 60, "fat": 18},
        {"type": "lanche", "name": "Lanche", "items": [...], "calories": 250, "protein": 15, "carbs": 30, "fat": 8},
        {"type": "jantar", "name": "Jantar", "items": [...], "calories": 500, "protein": 35, "carbs": 50, "fat": 15}
      ],
      "totalCalories": 1750
    }
  ],
  "summary": { "avgCalories": 1750, "avgProtein": 120, "avgCarbs": 185, "avgFat": 53, "tips": ["dica1", "dica2"] }
}

REGRAS: Se VEGETARIANO, NAO inclua carnes. Se estresse RUIM, inclua alimentos ricos em magnesio.
Usuario: ${weight}kg, ${height}cm, ${age}a. Objetivo: ${goal}. Restricoes: ${dietaryRestrictions}.`;

  if (!apiKey) return generateFallbackMealPlan(profileContext);

  try {
    const url = `${APP_CONFIG.apis.geminiBaseUrl}?key=${apiKey}`;
    const response = await fetch(url, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ contents: [{ role: 'user', parts: [{ text: systemPrompt }] }] }) });
    const result = await response.json();
    const text = result.candidates?.[0]?.content?.parts?.[0]?.text;
    if (!text) return null;
    const sanitized = sanitizeAIOutput(text);
    const jsonMatch = sanitized.match(/\{[\s\S]*?\}/);
    if (jsonMatch) { const parsed = JSON.parse(jsonMatch[0]); if (parsed.week) return parsed; }
    return null;
  } catch (error: unknown) {
    if (__DEV__) console.error('Erro ao gerar plano alimentar:', error);
    return generateFallbackMealPlan(profileContext);
  }
}

export async function generateWorkoutPlan(profileContext: Record<string, unknown> = {}): Promise<Record<string, unknown> | null> {
  const apiKey = GOOGLE_API_KEY;
  const { weight = 70, goal = 'manter', level = 'intermediario', gymType = 'academia', availableDays = 4, injuries = [], preferredMuscles = [] } = profileContext as { weight: number; goal: string; level: string; gymType: string; availableDays: number; injuries: Array<{ bodyPart: string; description?: string }>; preferredMuscles: string[] };

