  const systemPrompt = `${WORKOUT_PLAN_SYSTEM_INSTRUCTION}

Catalogo de exercicios disponiveis: ${JSON.stringify(availableExercises.map(e => ({ name: e.name, muscle: e.muscleGroup, equipment: e.equipment })))}

REGRAS: Use APENAS exercicios do catalogo. Se lesao, analise a descricao. Musculos preferidos: ${preferredMuscles.join(', ') || 'Todos'}.
Usuario: ${weight}kg, ${goal}, ${level}, ${availableDays} dias, Lesoes: ${injuries.map(i => i.bodyPart + ': ' + (i.description || '')).join('; ') || 'Nenhuma'}.

Retorne JSON: { week: [{ day, name, exercises: [{name, sets, reps, rest, muscle}], duration }], summary: { totalWorkouts, musclesWorked, tips } }`;

  if (!apiKey) return generateFallbackWorkoutPlan(profileContext);

  try {
    const url = `${APP_CONFIG.apis.geminiBaseUrl}?key=${apiKey}`;
    const response = await fetch(url, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ contents: [{ role: 'user', parts: [{ text: systemPrompt }] }] }) });
    const result = await response.json();
    const text = result.candidates?.[0]?.content?.parts?.[0]?.text;
    if (!text) return null;
    const sanitized = sanitizeAIOutput(text);
    const jsonMatch = sanitized.match(/\{[\s\S]*?\}/);
    if (jsonMatch) { const parsed = JSON.parse(jsonMatch[0]); if (parsed.week) return parsed; }
    return null;
  } catch (error: unknown) {
    if (__DEV__) console.error('Erro ao gerar plano:', error);
    return generateFallbackWorkoutPlan(profileContext);
  }
}

export function calculateOneRepMax(weight: number, reps: number): number {
  if (reps <= 0) return 0;
  if (reps === 1) return weight;
  return Math.round(weight * (1 + reps / 30));
}

export async function getExerciseStrengthProgress(userId: string, exerciseName: string): Promise<Array<{ date: string; weight: number; reps: number; estimated1RM: number }>> {
  if (!userId) return [];
  try {
    const { data, error } = await supabase
      .from('user_exercise_logs')
      .select('created_at, reps_done, weight_kg')
      .eq('user_id', userId)
      .eq('exercise_name', exerciseName)
      .order('created_at', { ascending: true });

    if (error) throw error;

    return (data || []).map(log => {
      const reps = (log.reps_done as number) || 0;
      const weight = (log.weight_kg as number) || 0;
      return {
        date: new Date(log.created_at as string).toISOString().split('T')[0],
        weight,
        reps,
        estimated1RM: calculateOneRepMax(weight, reps),
      };
    });
  } catch (err: unknown) {
    if (__DEV__) console.error('Erro ao buscar progresso de força:', err);
    return [];
  }
}

export async function saveWorkoutPlan(userId: string, plan: Record<string, unknown>): Promise<boolean> {
  if (!userId || !plan?.week) return false;
  try {
    const week = plan.week as Array<{ name: string; focus?: string; duration?: number; exercises?: unknown[]; day: string }>;
    const workouts = week.map(day => ({ user_id: userId, title: day.name, category: day.focus || 'Treino', duration_minutes: day.duration || 60, exercises: JSON.stringify(day.exercises || []), day_of_week: day.day, is_active: true }));
    const { error } = await supabase.from('user_plans').upsert(workouts, { onConflict: 'user_id,day_of_week' });
    return !error;
  } catch (err: unknown) { if (__DEV__) console.error('Erro ao salvar plano:', err); return false; }
}

