// src/services/planService.ts
// Serviço de conversão e CRUD de planos semanais - NOVAIX FITNESS

import { supabase } from '../config/supabase';
import { createServiceGuard } from '../utils/serviceGuard';
import { DAY_KEYS } from '../data/weekPlan';

const guard = createServiceGuard({ serviceName: 'planService' });

export async function loadWeeklyPlan(userId: string): Promise<Record<string, unknown> | null> {
  if (!userId) return null;

  const result = await guard.guard(async () => {
    const { data: plans } = await supabase
      .from('user_plans')
      .select('day_of_week, title, exercises, duration_minutes, category')
      .eq('user_id', userId)
      .eq('is_active', true);

    if (!plans || plans.length === 0) return null;
    return convertUserPlansToWeekPlan(plans);
  });

  return result.ok ? result.data : null;
}

export async function saveWeeklyPlan(userId: string, weekPlan: Record<string, Record<string, unknown>>): Promise<boolean> {
  if (!userId || !weekPlan) return false;

  try {
    await supabase
      .from('user_plans')
      .update({ is_active: false })
      .eq('user_id', userId)
      .eq('is_active', true);

    const plans = convertWeekPlanToUserPlans(userId, weekPlan);
    const activePlans = plans.filter(p => !p.isRest);

    if (activePlans.length > 0) {
      const { error } = await supabase
        .from('user_plans')
        .insert(activePlans);
      if (error) throw error;
    }

    return true;
  } catch (err: unknown) {
    if (__DEV__) console.error('Erro ao salvar plano semanal:', err);
    return false;
  }
}

export async function updateDayPlan(userId: string, dayKey: string, dayData: Record<string, unknown>): Promise<boolean> {
  if (!userId || !dayKey) return false;

  try {
    if (dayData.isRest) {
      await supabase
        .from('user_plans')
        .delete()
        .eq('user_id', userId)
        .eq('day_of_week', dayKey)
        .eq('is_active', true);
      return true;
    }

    const { data: existing } = await supabase
      .from('user_plans')
      .select('id')
      .eq('user_id', userId)
      .eq('day_of_week', dayKey)
      .eq('is_active', true)
      .maybeSingle();

    const planRow = {
      user_id: userId,
      day_of_week: dayKey,
      title: dayData.workoutName || '',
      exercises: dayData.exercises || [],
      duration_minutes: dayData.duration || 0,
      category: dayData.category || null,
      is_active: true,
    };

    if (existing) {
      await supabase.from('user_plans').update(planRow).eq('id', existing.id);
    } else {
      await supabase.from('user_plans').insert(planRow);
    }

    return true;
  } catch (err: unknown) {
    if (__DEV__) console.error('Erro ao atualizar dia:', err);
    return false;
  }
}

interface WeekPlanDay {
  workoutId: string | null;
  workoutName: string | null;
  duration: number;
  category: string | null;
  isRest: boolean;
  exercises?: unknown[];
}

function convertUserPlansToWeekPlan(plans: Record<string, unknown>[]): Record<string, WeekPlanDay> {
  const weekPlan: Record<string, WeekPlanDay> = {};

  for (const key of DAY_KEYS) {
    const plan = plans.find(p => p.day_of_week === key);
    if (plan) {
      weekPlan[key] = {
        workoutId: (plan.exercises as any)?.[0]?.workout_id || null,
        workoutName: (plan.title as string) || '',
        duration: (plan.duration_minutes as number) || 0,
        category: (plan.category as string) || null,
        isRest: false,
        exercises: (plan.exercises as unknown[]) || [],
      };
    } else {
      weekPlan[key] = { workoutId: null, workoutName: null, duration: 0, category: null, isRest: true };
    }
  }

  return weekPlan;
}

function convertWeekPlanToUserPlans(userId: string, weekPlan: Record<string, Record<string, unknown>>): Array<Record<string, unknown>> {
  return DAY_KEYS.map(key => {
    const day = weekPlan[key];
    return {
      user_id: userId,
      day_of_week: key,
      title: day?.workoutName || '',
      exercises: day?.exercises || [],
      duration_minutes: day?.duration || 0,
      category: day?.category || null,
      is_active: true,
      isRest: !!day?.isRest,
    };
  });
}

