import * as ImagePicker from 'expo-image-picker';
import { supabase } from '../config/supabase';

interface ImageAsset {
  uri: string;
  [key: string]: unknown;
}

interface ProgressPhoto {
  id: string;
  user_id: string;
  image_url: string;
  storage_path: string;
  label: string;
  recorded_at: string;
}

export async function pickImage(): Promise<ImageAsset | null> {
  const { status } = await ImagePicker.requestMediaLibraryPermissionsAsync();
  if (status !== 'granted') {
    throw new Error('Permissao para acessar galeria negada');
  }

  const result = await ImagePicker.launchImageLibraryAsync({
    mediaTypes: ImagePicker.MediaTypeOptions.Images,
    allowsEditing: true,
    aspect: [3, 4],
    quality: 0.8,
  });

  if (result.canceled) return null;
  return result.assets[0] as unknown as ImageAsset;
}

export async function takePhoto(): Promise<ImageAsset | null> {
  const { status } = await ImagePicker.requestCameraPermissionsAsync();
  if (status !== 'granted') {
    throw new Error('Permissao para acessar camera negada');
  }

  const result = await ImagePicker.launchCameraAsync({
    allowsEditing: true,
    aspect: [3, 4],
    quality: 0.8,
  });

  if (result.canceled) return null;
  return result.assets[0] as unknown as ImageAsset;
}

export async function uploadProgressPhoto(userId: string, imageUri: string, label?: string): Promise<ProgressPhoto> {
  const fileName = `${userId}/${Date.now()}.jpg`;
  const formData = new FormData();

  formData.append('file', {
    uri: imageUri,
    type: 'image/jpeg',
    name: fileName,
  } as unknown as Blob);

  const { data: uploadData, error: uploadError } = await supabase.storage
    .from('progress-photos')
    .upload(fileName, formData, {
      contentType: 'image/jpeg',
      upsert: false,
    });

  if (uploadError) throw uploadError;

  const { data: urlData } = supabase.storage
    .from('progress-photos')
    .getPublicUrl(fileName);

  const { data, error } = await supabase
    .from('progress_photos')
    .insert({
      user_id: userId,
      image_url: urlData.publicUrl,
      storage_path: fileName,
      label: label || 'Progresso',
      recorded_at: new Date().toISOString(),
    })
    .select()
    .single();

  if (error) throw error;
  return data as ProgressPhoto;
}

export async function getProgressPhotos(userId: string, limit: number = 50): Promise<ProgressPhoto[]> {
  if (!userId) return [];

  const { data, error } = await supabase
    .from('progress_photos')
    .select('*')
    .eq('user_id', userId)
    .order('recorded_at', { ascending: false })
    .limit(limit);

  if (error) throw error;
  return (data || []) as ProgressPhoto[];
