    intensityLevels: ['Moderado', 'Intenso', 'Máximo'],
  },
};

export function getModalityConfig(modality: string): Record<string, unknown> {
  return (MODALITY_CONFIG as Record<string, Record<string, unknown>>)[modality] || MODALITY_CONFIG.gym;
}

export function analyzeProgression(workoutType: string, exerciseLogs: Record<string, unknown>[], historicalData: Record<string, unknown>[] = []): Record<string, unknown> {
  const config = getModalityConfig(workoutType);

  switch (config.progression as string) {
    case 'load':
      return analyzeLoadProgression(exerciseLogs, historicalData);
    case 'variation':
      return analyzeVariationProgression(exerciseLogs);
    case 'endurance':
      return analyzeEnduranceProgression(exerciseLogs);
    case 'complexity':
      return analyzeComplexityProgression(exerciseLogs);
    case 'flexibility':
      return analyzeFlexibilityProgression(exerciseLogs);
    case 'intensity':
      return analyzeIntensityProgression(exerciseLogs);
    default:
      return { type: 'maintain', reason: 'Modalidade desconhecida' };
  }
}

function analyzeLoadProgression(logs: Record<string, any>[], historical: Record<string, unknown>[]): Record<string, unknown> {
  if (!logs?.length) return { type: 'start', reason: 'Primeira vez' };

  const recent = logs.slice(0, 10);
  const avgWeight = recent.reduce((s, l) => s + (l.weight_kg || 0), 0) / recent.length;
  const avgReps = recent.reduce((s, l) => s + (l.reps_done || 0), 0) / recent.length;
  const completionRate = recent.filter(l => l.completed).length / recent.length;

  if (completionRate > 0.9 && avgReps >= 12) return { type: 'progress', reason: 'Alta performance', weight: avgWeight + 2.5 };
  if (completionRate < 0.5) return { type: 'regress', reason: 'Dificuldade', weight: Math.max(0, avgWeight - 2.5) };
  return { type: 'maintain', reason: 'Performance estavel' };
}

function analyzeVariationProgression(logs: Record<string, any>[]): Record<string, unknown> {
  if (!logs?.length) return { type: 'start', variationLevel: 1 };
  const lastExercise = logs[0];
  const currentLevel = lastExercise.variation_level || 1;
  const completionRate = logs.filter(l => l.completed).length / logs.length;

  if (completionRate > 0.85 && currentLevel < 5) return { type: 'progress', variationLevel: currentLevel + 1 };
  if (completionRate < 0.4 && currentLevel > 1) return { type: 'regress', variationLevel: currentLevel - 1 };
  return { type: 'maintain', variationLevel: currentLevel };
}

function analyzeEnduranceProgression(logs: Record<string, any>[]): Record<string, unknown> {
  if (!logs?.length) return { type: 'start' };
  const recent = logs.slice(0, 5);
  const avgDuration = recent.reduce((s, l) => s + (l.duration_min || 0), 0) / recent.length;
  const avgPace = recent.reduce((s, l) => s + (l.pace || 0), 0) / recent.length;

  if (avgPace < 6) return { type: 'progress', reason: 'Ritmo melhorou', duration: avgDuration + 5 };
  return { type: 'maintain', reason: 'Manter ritmo atual' };
}

function analyzeComplexityProgression(logs: Record<string, any>[]): Record<string, unknown> {
  if (!logs?.length) return { type: 'start', level: 0 };
  const avgComplexity = logs.reduce((s, l) => s + (l.complexity_score || 0), 0) / logs.length;
  const accuracy = logs.reduce((s, l) => s + (l.rhythm_accuracy || 0), 0) / logs.length;

  if (accuracy > 0.8 && avgComplexity < 4) return { type: 'progress', level: Math.min(4, Math.floor(avgComplexity) + 1) };
  return { type: 'maintain', level: Math.floor(avgComplexity) };
}

function analyzeFlexibilityProgression(logs: Record<string, any>[]): Record<string, unknown> {
  if (!logs?.length) return { type: 'start' };
  const recent = logs.slice(0, 5);
  const avgHold = recent.reduce((s, l) => s + (l.hold_time || 0), 0) / recent.length;
  const flexibility = recent.reduce((s, l) => s + (l.flexibility_score || 0), 0) / recent.length;

  if (flexibility > 70 && avgHold < 90) return { type: 'progress', holdTime: avgHold + 5 };
  return { type: 'maintain' };
}

function analyzeIntensityProgression(logs: Record<string, unknown>[]): Record<string, unknown> {
  if (!logs?.length) return { type: 'start', intensity: 0 };
  const recent = logs.slice(0, 5);
  const avgIntensity = recent.reduce((s, l) => s + ((l.intensity_score as number) || 0), 0) / recent.length;
  const avgHR = recent.reduce((s, l) => s + ((l.avg_heart_rate as number) || 0), 0) / recent.length;

  if (avgIntensity < 7 && avgHR < 150) return { type: 'progress', intensity: Math.min(10, avgIntensity + 1) };
  return { type: 'maintain' };
}

export function applyProgression(workout: Record<string, unknown>, progression: Record<string, unknown>): Record<string, unknown> {
  if (!workout?.exercises) return workout;

  const adapted = { ...workout } as Record<string, unknown>;

  switch (progression.type as string) {
    case 'progress':
      adapted.exercises = (workout.exercises as Record<string, unknown>[]).map(ex => ({
        ...ex,
        weight: progression.weight || ex.weight,
        sets: progression.sets || ex.sets,
        reps: progression.reps || ex.reps,
        variation_level: progression.variationLevel || ex.variation_level,
        hold_time: progression.holdTime || ex.hold_time,
        intensity: progression.intensity || ex.intensity,
      }));
      break;
    case 'regress':
      adapted.exercises = (workout.exercises as Record<string, unknown>[]).map(ex => ({
        ...ex,
        weight: progression.weight || ex.weight,
        sets: Math.max(2, ((ex.sets as number) || 3) - 1),
        variation_level: progression.variationLevel || ex.variation_level,
      }));
      break;
  }

  return adapted;
}

export function getProgressionSummary(progression: Record<string, unknown>): string {
  const messages = {
    start: 'Iniciando novo exercício. Foque na forma correta.',
    progress: 'Progressão detectada! Aumentando desafio.',
    regress: 'Reduzindo carga para garantir execução correta.',
    maintain: 'Mantendo nível atual. Consistência é chave!',
  };
  return messages[progression.type as keyof typeof messages] || 'Continuando treino.';
}

// src/services/pushNotifications.js
// Servico de push notifications - NOVAIX FITNESS

import * as Notifications from 'expo-notifications';
import { Platform } from 'react-native';
import { supabase } from '../config/supabase';
import { APP_CONFIG } from '../config/app';

const EXPO_API_URL = 'https://exp.host/--/api/v2/push/send';

const ROUTE_MAP = {
  workout_reminder: '/(tabs)/home',
  workout_completed: '/(tabs)/home',
  new_workout: '/(tabs)/library',
  streak: '/(tabs)/perfil',
  achievement: '/(tabs)/perfil',
  level_up: '/(tabs)/perfil',
  weekly_plan: '/(tabs)/library',
  weekly_summary: '/(tabs)/home',
  rest_day: '/(tabs)/home',
  motivational: '/(tabs)/home',
  workout_detail: '/workout-detail',
};

export async function registerForPushNotificationsAsync(userId: string): Promise<string | null> {
  if (Platform.OS === 'web') return null;

  const { status: existing } = await Notifications.getPermissionsAsync();
  let finalStatus = existing;
  if (existing !== 'granted') {
    const { status } = await Notifications.requestPermissionsAsync();
    finalStatus = status;
  }
  if (finalStatus !== 'granted') return null;

  try {
    const tokenData = await Notifications.getExpoPushTokenAsync();
    const pushToken = tokenData.data;

    if (userId && pushToken) {
      await supabase
        .from('profiles')
        .update({ push_token: pushToken })
        .eq('id', userId);
    }

    if (Platform.OS === 'android') {
      await Notifications.setNotificationChannelAsync('default', {
        name: 'NOVAIX Fitness',
        importance: Notifications.AndroidImportance.HIGH,
        vibrationPattern: [0, 250, 250, 250],
      });
    }

    return pushToken;
  } catch (err: unknown) {
    if (__DEV__) console.warn('Erro ao registrar push token:', err);
    return null;
  }
}

export function addNotificationReceivedListener(handler: (notification: { title: string | undefined; body: string | undefined; data: Record<string, unknown>; notification: unknown }) => void): Notifications.Subscription {
  return Notifications.addNotificationReceivedListener((notification) => {
    const { title, body, data } = notification.request.content;
    handler?.({ title, body, data, notification });
  });
}

export function addNotificationResponseListener(navigation: { navigate: (route: string, params?: Record<string, unknown>) => void }): Notifications.Subscription {
  return Notifications.addNotificationResponseReceivedListener((response) => {
    const { data } = response.notification.request.content;
    handleDeepLink(data, navigation);
  });
}

function handleDeepLink(data: Record<string, unknown> | undefined, navigation: { navigate: (route: string, params?: Record<string, unknown>) => void }): void {
  if (!navigation || !data) return;
  const type = data?.type as string;
  const route = ROUTE_MAP[type as keyof typeof ROUTE_MAP] || ROUTE_MAP[data?.route as keyof typeof ROUTE_MAP];
  if (!route) return;

  const params: Record<string, unknown> = {};
  if (data?.workout_id) params.id = data.workout_id;
  if (data?.achievement_id) params.id = data.achievement_id;

  navigation.navigate(route, Object.keys(params).length ? params : undefined);
}

export async function sendPushNotification(expoPushToken: string, title: string, body: string, data: Record<string, unknown> = {}): Promise<boolean> {
  if (!expoPushToken) return false;

  const message = {
    to: expoPushToken,
    sound: 'default',
    title,
    body,
    data,
    channelId: 'default',
  };

  try {
    const response = await fetch(EXPO_API_URL, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(message),
    });
    const result = await response.json();
    return result.data?.status === 'ok';
  } catch (err: unknown) {
    if (__DEV__) console.warn('Erro ao enviar push:', err);
    return false;
  }
}

export async function sendPushToUser(userId: string, title: string, body: string, data: Record<string, unknown> = {}): Promise<boolean> {
  try {
    const { data: profile } = await supabase
      .from('profiles')
      .select('push_token, notification_prefs')
      .eq('id', userId)
      .single();

    if (!profile?.push_token) return false;
    const prefs = (profile.notification_prefs as Record<string, boolean> | undefined) || (APP_CONFIG.notifications as any).defaultPrefs;
    const type = data?.type as string;
    if (type && prefs[type] === false) return false;

    return sendPushNotification(profile.push_token, title, body, data);
  } catch {
    return false;
  }
}

export async function sendBatchPushNotifications(tokens: string[], title: string, body: string, data: Record<string, unknown> = {}): Promise<void> {
  const messages = tokens
    .filter(Boolean)
    .map((token) => ({
      to: token,
      sound: 'default',
      title,
      body,
      data,
      channelId: 'default',
    }));

  if (messages.length === 0) return;

  try {
    await fetch(EXPO_API_URL, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(messages),
    });
  } catch (err: unknown) {
    if (__DEV__) console.warn('Erro ao enviar batch push:', err);
  }
}

