let stravaConnected = false;
let stravaToken = null;

export async function checkStravaAvailability() {
  try {
    const canOpen = await Linking.canOpenURL('strava://');
    return { available: canOpen };
  } catch {
    return { available: false };
  }
}

export async function connectStrava() {
  try {
    const clientId = process.env.EXPO_PUBLIC_STRAVA_CLIENT_ID;
    if (!clientId) return { started: false, error: 'Strava não configurado' };
    const authUrl = `https://www.strava.com/oauth/authorize?client_id=${clientId}&response_type=code&scope=read,activity:read_all&redirect_uri=novaix://strava-callback`;
    await Linking.openURL(authUrl);
    return { started: true };
  } catch {
    return { started: false };
  }
}

export function isStravaConnected() {
  return stravaConnected;
}

export async function syncRunningActivities() {
  if (!stravaConnected) return { synced: false, reason: 'not_connected' };

  return {
    synced: true,
    activities: [],
    lastSync: new Date().toISOString(),
  };
}

export async function getRunningStats() {
  if (!stravaConnected) return null;

  return {
    totalRuns: 0,
    totalDistance: 0,
    totalDuration: 0,
    avgPace: '0:00',
    lastActivity: null,
  };
}

export async function disconnectStrava() {
  stravaConnected = false;
  stravaToken = null;
  return { disconnected: true };
}

// src/services/syncQueue.js
// Fila de acoes offline e sincronizacao automatica

import AsyncStorage from '@react-native-async-storage/async-storage';
import NetInfo from '@react-native-community/netinfo';

const QUEUE_KEY = '@novaix:sync_queue';

interface SyncAction {
  type: string;
  payload?: Record<string, unknown>;
  [key: string]: unknown;
}

interface QueuedAction extends SyncAction {
  id: string;
  timestamp: number;
  retries: number;
}

export async function queueOfflineAction(action: SyncAction): Promise<boolean> {
  try {
    const raw = await AsyncStorage.getItem(QUEUE_KEY);
    const queue: QueuedAction[] = raw ? JSON.parse(raw) : [];
    queue.push({
      ...action,
      id: `${Date.now()}_${Math.random().toString(36).slice(2, 8)}`,
      timestamp: Date.now(),
      retries: 0,
    } as QueuedAction);
    await AsyncStorage.setItem(QUEUE_KEY, JSON.stringify(queue));
    return true;
  } catch (err: unknown) {
    if (__DEV__) console.error('Erro ao enfileirar acao:', err);
    return false;
  }
}

export async function getSyncQueue(): Promise<QueuedAction[]> {
  try {
    const raw = await AsyncStorage.getItem(QUEUE_KEY);
    return raw ? (JSON.parse(raw) as QueuedAction[]) : [];
  } catch { return []; }
}

export async function removeSyncAction(actionId: string): Promise<void> {
  try {
    const raw = await AsyncStorage.getItem(QUEUE_KEY);
    const queue: QueuedAction[] = raw ? JSON.parse(raw) : [];
    await AsyncStorage.setItem(QUEUE_KEY, JSON.stringify(queue.filter(a => a.id !== actionId)));
  } catch (err: unknown) {
    if (__DEV__) console.error('Erro ao remover acao:', err);
  }
}

export async function clearSyncQueue(): Promise<void> {
  try {
    await AsyncStorage.setItem(QUEUE_KEY, JSON.stringify([]));
  } catch (err: unknown) {
    if (__DEV__) console.error('Erro ao limpar fila:', err);
  }
}

export async function syncPendingActions(executeActionFn: (action: QueuedAction) => Promise<void>): Promise<{ synced: number; failed: number }> {
  const queue = await getSyncQueue();
  if (queue.length === 0) return { synced: 0, failed: 0 };

  let synced = 0;
  let failed = 0;
  for (const action of queue) {
    try {
      await executeActionFn(action);
      await removeSyncAction(action.id);
      synced++;
    } catch {
      action.retries = (action.retries || 0) + 1;
      if (action.retries >= 3) { await removeSyncAction(action.id); failed++; }
    }
  }
  return { synced, failed };
}

export async function isOnline(): Promise<boolean> {
  try { const state = await NetInfo.fetch(); return state.isConnected; }
  catch { return true; }
}

export async function waitForOnline(callback: () => void, checkInterval: number = 5000): Promise<() => void> {
  const interval = setInterval(async () => {
    if (await isOnline()) { clearInterval(interval); callback(); }
  }, checkInterval);
  return () => clearInterval(interval);
}

// src/services/tips.js
// Dicas personalizadas por IA - nutrição, treino, suplementação

import { APP_CONFIG } from '../config/app';
import { GOOGLE_API_KEY } from '../config/api';
import { sanitizeAIOutput } from '../utils/aiSanitize';
import { TIPS_SYSTEM_INSTRUCTION } from './aiSystemInstructions';

interface TipContext {
  goal: string;
  level: string;
  weight: number;
  ageRange: string;
  dietaryRestrictions?: string;
  injuries?: string[];
}

interface TipItem {
  title: string;
  description: string;
  icon?: string;
}

interface TipResult {
  nutrition: TipItem[];
  training: TipItem[];
  supplements: TipItem[];
  lifestyle: TipItem[];
}

export async function generatePersonalizedTips(profileContext: TipContext): Promise<TipResult | null> {
  const apiKey = GOOGLE_API_KEY;

  const systemPrompt = `${TIPS_SYSTEM_INSTRUCTION}

Perfil do usuario:
- Objetivo: ${profileContext.goal}
- Nivel: ${profileContext.level}
- Peso: ${profileContext.weight}kg
- Idade: ${profileContext.ageRange}
- Restricoes: ${profileContext.dietaryRestrictions || 'nenhuma'}
- Lesoes: ${profileContext.injuries?.join(', ') || 'nenhuma'}

Formato de saida esperado:
{
  "nutrition": [
    {"title": "Titulo da dica", "description": "Descricao curta", "icon": "nutrition"}
  ],
  "training": [
    {"title": "Titulo da dica", "description": "Descricao curta", "icon": "training"}
  ],
  "supplements": [
    {"title": "Titulo da dica", "description": "Descricao curta", "icon": "supplement"}
  ],
  "lifestyle": [
    {"title": "Titulo da dica", "description": "Descricao curta", "icon": "lifestyle"}
  ]
}

Foque em: nutricao, treino, whey/proteina, creatina, vitaminas, sono, hidratacao.
Seja pratico e especifico para o perfil do usuario.`;

  if (!apiKey) return generateFallbackTips(profileContext);

  try {
    const url = `${APP_CONFIG.apis.geminiBaseUrl}?key=${apiKey}`;
    const response = await fetch(url, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ contents: [{ role: 'user', parts: [{ text: systemPrompt }] }] }),
    });
    const result = await response.json();
    const text = result.candidates?.[0]?.content?.parts?.[0]?.text;
    if (!text) return null;
    const sanitized = sanitizeAIOutput(text);
    const jsonMatch = sanitized.match(/\{[\s\S]*?\}/);
    if (jsonMatch) return JSON.parse(jsonMatch[0]);
    return null;
  } catch (error: unknown) {
    if (__DEV__) console.error('Erro ao gerar dicas:', error);
    return generateFallbackTips(profileContext);
  }
}

function generateFallbackTips(profile: TipContext): TipResult {
  return {
    nutrition: [
      { title: 'Proteína em cada refeição', description: 'Inclua 20-30g de proteína em cada refeição para manter a massa muscular.' },
      { title: 'Carboidratos complexos', description: 'Prefira arroz integral, batata doce e aveia ao invés de refinedados.' },
      { title: 'Gorduras boas', description: 'Abacate, castanhas e azeite são aliados na saúde.' },
    ],
    training: [
      { title: 'Progressão de carga', description: 'Aumente a carga 2.5kg a cada 2 semanas quando conseguir 12 reps.' },
      { title: 'Descanso entre séries', description: '60-90s para hipertrofia, 30-45s para definição.' },
      { title: 'Aquecimento', description: '5-10 min antes de treinar para prevenir lesões.' },
    ],
    supplements: [
      { title: 'Whey Protein', description: '20-30g após o treino para recuperação muscular.' },
      { title: 'Creatina', description: '3-5g diários para força e resistência.' },
      { title: 'Vitamina D', description: 'Importante para ossos e imunidade, especialmente se não toma sol.' },
    ],
    lifestyle: [
      { title: 'Sono de qualidade', description: 'Durma 7-9h por noite para melhor recuperação.' },
      { title: 'Hidratação', description: 'Beba pelo menos 2L de água por dia, mais nos dias de treino.' },
