// src/services/virtualGifting.js
// Sistema de Virtual Gifting: moeda interna, presentes, ranking

import { supabase } from '../config/supabase';

// ============================================
// CARTEIRA
// ============================================

export async function getWallet(userId: string): Promise<Record<string, unknown>> {
  const { data } = await supabase
    .from('wallet')
    .select('*')
    .eq('user_id', userId)
    .single();

  return data || { balance: 0, total_earned: 0, total_spent: 0 };
}

// ============================================
// CATÁLOGO DE PRESENTES
// ============================================

export async function getGiftCatalog(): Promise<Record<string, unknown>[]> {
  const { data } = await supabase
    .from('gift_catalog')
    .select('*')
    .eq('is_active', true)
    .order('coin_value', { ascending: true });

  return data || [];
}

// ============================================
// ENVIAR PRESENTE
// ============================================

export async function sendGift(senderId: string, receiverId: string, giftId: string, liveId: string | null = null, message: string | null = null): Promise<Record<string, unknown>> {
  const { data, error } = await supabase.rpc('send_gift', {
    p_sender_id: senderId,
    p_receiver_id: receiverId,
    p_gift_id: giftId,
    p_live_id: liveId,
    p_message: message,
  });

  if (error) throw error;
  if (data?.error) throw new Error(data.error);
  return data;
}

// ============================================
// COMPRAR COINS
// ============================================

export async function getCoinPackages(): Promise<Record<string, unknown>[]> {
  const { data } = await supabase
    .from('coin_packages')
    .select('*')
    .eq('is_active', true)
    .order('price_brl', { ascending: true });

  return data || [];
}

export async function buyCoins(userId: string, packageId: string): Promise<Record<string, unknown>> {
  const { data, error } = await supabase.rpc('buy_coins', {
    p_user_id: userId,
    p_package_id: packageId,
  });

  if (error) throw error;
  if (data?.error) throw new Error(data.error);
  return data;
}

// ============================================
// HISTÓRICO DE PRESENTES
// ============================================

export async function getGiftHistory(userId: string, type: string = 'sent', limit: number = 20): Promise<Record<string, unknown>[]> {
  const column = type === 'sent' ? 'sender_id' : 'receiver_id';
  const { data } = await supabase
    .from('gift_transactions')
    .select('*, gift_catalog(name, emoji, coin_value), profiles:sender_id(name, avatar_url), profiles:receiver_id(name, avatar_url)')
    .eq(column, userId)
    .order('created_at', { ascending: false })
    .limit(limit);

  return data || [];
}

// ============================================
// RANKING
// ============================================

export async function getTopGifters(limit: number = 10): Promise<Record<string, unknown>[]> {
  const { data } = await supabase
    .from('gift_rankings')
    .select('*, profiles:user_id(name, avatar_url)')
    .order('total_coins_sent', { ascending: false })
    .limit(limit);

  return data || [];
}

export async function getTopReceivers(limit: number = 10): Promise<Record<string, unknown>[]> {
  const { data } = await supabase
    .from('gift_rankings')
    .select('*, profiles:user_id(name, avatar_url)')
    .order('total_coins_received', { ascending: false })
    .limit(limit);

  return data || [];
}

export async function getUserRanking(userId: string): Promise<{ rank: number; coinsSent: number }> {
  const { data: senderRank } = await supabase
    .from('gift_rankings')
    .select('total_coins_sent')
    .eq('user_id', userId)
    .single();

  const { count } = await supabase
    .from('gift_rankings')
    .select('id', { count: 'exact', head: true })
    .gt('total_coins_sent', senderRank?.total_coins_sent || 0);

  return { rank: (count || 0) + 1, coinsSent: senderRank?.total_coins_sent || 0 };
}

// ============================================
// REALTIME (Presentes em live)
// ============================================

export function subscribeToGifts(liveId: string, onGift: (gift: Record<string, unknown>) => void): () => Promise<string> {
  const channel = supabase
    .channel(`gifts-${liveId}`)
    .on('postgres_changes', {
      event: 'INSERT',
      schema: 'public',
      table: 'gift_transactions',
      filter: `live_id=eq.${liveId}`,
    }, (payload) => {
      onGift(payload.new);
    })
    .subscribe();

  return () => supabase.removeChannel(channel);
}

// src/services/waterCalculator.js
// Calculadora de hidratação baseada em IMC e fatores pessoais

import { supabase } from '../config/supabase';

export function calculateWater(weight: number, height: number, level: string, ageRange: string, injuries: any[] = []): { dailyML: number; glassesPerDay: number; imc: string; imcClassification: string } {
  // Fórmula base: peso × 35ml
  let baseML = weight * 35;

  // Ajustar por IMC
  const imc = weight / ((height / 100) ** 2);
  if (imc > 30) baseML *= 1.1;
  else if (imc > 25) baseML *= 1.05;
  else if (imc < 18.5) baseML *= 0.95;

  // Ajustar por nível de treino
  const levelFactors: Record<string, number> = { iniciante: 1.0, basico: 1.05, intermediario: 1.1, 'avançado': 1.2 };
  baseML *= levelFactors[level] || 1.0;

  // Ajustar por faixa etária
  const ageFactors: Record<string, number> = {
    '10-17': 1.0,
    '18-25': 1.0,
    '26-35': 1.0,
    '36-45': 0.98,
    '46-55': 0.95,
    '56-65': 0.92,
    '66-100': 0.90,
  };
  baseML *= ageFactors[ageRange] || 1.0;
  
  // Ajustar por lesões (menos exercício = menos água)
  if (injuries.length > 0) baseML *= 0.95;
  
  // Garantir mínimo de 1500ml e máximo de 5000ml
  baseML = Math.max(1500, Math.min(5000, baseML));
  
  return {
    dailyML: Math.round(baseML),
    glassesPerDay: Math.ceil(baseML / 250),
    imc: imc.toFixed(1),
    imcClassification: getIMCClassification(imc),
  };
}

function getIMCClassification(imc: number): string {
  if (imc < 18.5) return 'Abaixo do peso';
  if (imc < 25) return 'Normal';
  if (imc < 30) return 'Sobrepeso';
  if (imc < 35) return 'Obesidade I';
  if (imc < 40) return 'Obesidade II';
  return 'Obesidade III';
}

export function generateWaterSchedule(dailyML: number, preferredTime: string = 'morning'): Array<{ time: string; amount: number; label: string }> {
  const glassML = 250;
  const timeMap: Record<string, number> = { morning: 7, afternoon: 12, night: 18 };
  const startHour = timeMap[preferredTime] || 7;
  const numGlasses = Math.ceil(dailyML / glassML);
  
  if (numGlasses <= 6) {
    return [
      { time: '07:00', amount: glassML, label: 'Ao acordar' },
      { time: '10:00', amount: glassML, label: 'Manhã' },
      { time: '12:00', amount: glassML, label: 'Almoço' },
      { time: '15:00', amount: glassML, label: 'Tarde' },
      { time: '18:00', amount: glassML, label: 'Pré-treino' },
      { time: '20:00', amount: glassML, label: 'Pós-treino' },
    ];
  }
  
  return [
    { time: '06:30', amount: glassML, label: 'Ao acordar' },
    { time: '09:00', amount: glassML, label: 'Manhã' },
    { time: '11:00', amount: glassML, label: 'Pré-treino' },
    { time: '13:00', amount: glassML, label: 'Almoço' },
    { time: '15:00', amount: glassML, label: 'Tarde' },
    { time: '17:00', amount: glassML, label: 'Pré-treino' },
    { time: '19:00', amount: glassML, label: 'Pós-treino' },
    { time: '21:00', amount: glassML, label: 'Noite' },
  ];
}

export function hasTapeMeasure() {
  return true; // Perguntar no onboarding
}

export function adjustWaterGoalForActivity(baseGoalML: number, workoutDurationMinutes: number): number {
  const additionalML = Math.round((workoutDurationMinutes / 30) * 250);
  return Math.min(6000, baseGoalML + additionalML);
}

export async function getTodayWaterProgress(userId: string, dailyGoal: number): Promise<{ amountML: number; percent: number; remainingML: number; remainingGlasses: number }> {
  if (!userId) return { amountML: 0, percent: 0, remainingML: dailyGoal, remainingGlasses: Math.ceil(dailyGoal / 250) };
  try {
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    const { data } = await supabase
      .from('water_logs')
      .select('amount_ml')
      .eq('user_id', userId)
      .gte('logged_at', today.toISOString());

    const amountML = data?.reduce((sum, item) => sum + (item.amount_ml as number), 0) || 0;
    const percent = dailyGoal > 0 ? Math.min(100, Math.round((amountML / dailyGoal) * 100)) : 0;
    const remainingML = Math.max(0, dailyGoal - amountML);
    const remainingGlasses = Math.ceil(remainingML / 250);

    return { amountML, percent, remainingML, remainingGlasses };
  } catch (err: unknown) {
    if (__DEV__) console.error('Erro ao buscar progresso de água:', err);
    return { amountML: 0, percent: 0, remainingML: dailyGoal, remainingGlasses: Math.ceil(dailyGoal / 250) };
  }
}

// src/services/waterReminders.ts
// Lembretes de hidratação

import * as Notifications from 'expo-notifications';
import { supabase } from '../config/supabase';
import { createServiceGuard } from '../utils/serviceGuard';

const guard = createServiceGuard({ serviceName: 'waterReminders' });

export async function scheduleWaterReminders(dailyGoal: number, preferredTime: string): Promise<boolean> {
  const hasPermission = await Notifications.requestPermissionsAsync();
  if (hasPermission.status !== 'granted') return false;

  await Notifications.cancelAllScheduledNotificationsAsync();

  const timeMap = { morning: 7, afternoon: 12, night: 18 };
  const startHour = timeMap[preferredTime] || 7;
  const hoursUntilSleep = 22 - startHour;
  const interval = Math.max(1, Math.floor(hoursUntilSleep / 6));

  for (let i = 0; i < 6; i++) {
    const hour = startHour + (i * interval);
    if (hour > 22) break;

    await Notifications.scheduleNotificationAsync({
      content: {
        title: 'Hora de beber água! 💧',
        body: getWaterTip(),
        data: { type: 'water_reminder' },
      },
      trigger: {
        type: Notifications.SchedulableTriggerInputTypes.CALENDAR,
        hour,
        minute: 0,
        repeats: true,
      },
    });
  }

  return true;
}

function getWaterTip() {
  const tips = [
    'Mantenha uma garrafa por perto!',
    'Beba um copo ao acordar.',
    'Água antes, durante e depois do treino.',
    'Se a urina estiver escura, beba mais água.',
    'Coma frutas com muita água (melancia, pepino).',
    'Beba um copo 30 minutos antes das refeições.',
  ];
  return tips[Math.floor(Math.random() * tips.length)];
}

export async function logWaterIntake(userId: string, amountML: number): Promise<void> {
  if (!userId) return;
  await guard.guard(async () => {
    await supabase.from('water_logs').insert({
      user_id: userId,
      amount_ml: amountML,
      logged_at: new Date().toISOString(),
    });
  });
}

export async function getTodayWater(userId: string): Promise<number> {
  if (!userId) return 0;
  const result = await guard.guard(async () => {
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    const { data } = await supabase.from('water_logs').select('amount_ml').eq('user_id', userId).gte('logged_at', today.toISOString());
    return data?.reduce((sum, item) => sum + item.amount_ml, 0) || 0;
  });
  return result.ok ? result.data : 0;
}

export async function getWaterHistory(userId: string, days: number = 7): Promise<Array<{ amount_ml: number; logged_at: string }>> {
  if (!userId) return [];
  const result = await guard.guard(async () => {
    const startDate = new Date();
    startDate.setDate(startDate.getDate() - days);
    const { data } = await supabase.from('water_logs').select('amount_ml, logged_at').eq('user_id', userId).gte('logged_at', startDate.toISOString()).order('logged_at', { ascending: true });
    return data || [];
  });
  return result.ok ? result.data : [];
}

// src/services/workout-reminders.js
// Sistema de lembretes de treino

import * as Notifications from 'expo-notifications';
import { supabase } from '../config/supabase';
import { getRestDays, getMotivationalMessage, getWeeklyFeedback } from './reminder-helpers';

export async function setupWorkoutReminders(userId: string): Promise<void> {
  const { data: profile } = await supabase.from('profiles')
    .select('onboarding, notification_settings').eq('id', userId).single();
  const { data: obv2 } = await supabase.from('onboarding_v2')
    .select('days_per_week').eq('user_id', userId).maybeSingle();

  if (!profile?.notification_settings?.workout_reminder) return;
  const settings = profile.notification_settings;
  const workoutDays = obv2?.days_per_week || [1, 3, 5];
  const [hour, minute] = (settings.reminder_time || '19:00').split(':').map(Number);

  await Notifications.cancelAllScheduledNotificationsAsync();

  for (const day of workoutDays) {
    const d = day === 0 ? 7 : day;
    await Notifications.scheduleNotificationAsync({
      content: { title: 'Hora de treinar!', body: getMotivationalMessage(), data: { type: 'workout_reminder', day: d } },
      trigger: {
        type: Notifications.SchedulableTriggerInputTypes.CALENDAR,
        weekday: d,
        hour,
        minute,
        repeats: true,
      },
    });
  }

  if (settings.rest_day) {
    for (const day of getRestDays(workoutDays)) {
      const d = day === 0 ? 7 : day;
      await Notifications.scheduleNotificationAsync({
        content: { title: 'Dia de descanso', body: 'Recuperacao e essencial. Volte amanha com energia!', data: { type: 'rest_day' } },
        trigger: {
          type: Notifications.SchedulableTriggerInputTypes.CALENDAR,
          weekday: d,
          hour: 10,
          minute: 0,
          repeats: true,
        },
      });
    }
  }

  if (settings.weekly_plan) {
    await Notifications.scheduleNotificationAsync({
      content: { title: 'Seu plano da semana!', body: 'Confira os treinos desta semana no app.', data: { type: 'weekly_plan' } },
      trigger: {
        type: Notifications.SchedulableTriggerInputTypes.CALENDAR,
        weekday: 1,
        hour: 8,
        minute: 0,
        repeats: true,
      },
    });
  }

  if (settings.motivational) {
    await Notifications.scheduleNotificationAsync({
      content: { title: 'Foco no objetivo!', body: getMotivationalMessage(), data: { type: 'motivational' } },
      trigger: {
        type: Notifications.SchedulableTriggerInputTypes.CALENDAR,
        weekday: 4,
        hour: 19,
        minute: 30,
        repeats: true,
      },
    });
  }
}

export async function sendStreakProtectionReminder(userId: string): Promise<void> {
  const { data: profile } = await supabase
    .from('profiles')
    .select('notification_settings')
    .eq('id', userId)
    .single();

  if (!profile?.notification_settings?.streak) return;

  const { data: todayWorkout } = await supabase
    .from('user_workouts')
    .select('id')
    .eq('user_id', userId)
    .eq('completed', true)
    .gte('completed_at', new Date().toISOString().split('T')[0])
    .limit(1);

  if (!todayWorkout?.length) {
    await Notifications.scheduleNotificationAsync({
      content: {
        title: 'Seu streak está em risco!',
        body: 'Você ainda não treinou hoje. Não perca seu progresso!',
        data: { type: 'streak_reminder' },
      },
      trigger: null,
    });
  }
}

export async function sendPostWorkoutReminder(userId: string, workoutName: string): Promise<void> {
  await Notifications.scheduleNotificationAsync({
    content: {
      title: 'Treino concluido!',
      body: `Excelente! Hidrate-se e descanse bem.`,
      data: { type: 'post_workout' },
    },
    trigger: null,
  });

  setTimeout(async () => {
    await Notifications.scheduleNotificationAsync({
      content: {
        title: 'Lembrete pos-treino',
        body: 'Beba agua e coma algo proteico nas proximas 2 horas.',
        data: { type: 'recovery_reminder' },
      },
      trigger: null,
    });
  }, 3600000);
}

export async function sendWeeklySummaryReminder(userId: string): Promise<void> {
  const now = new Date();
  const weekStart = new Date(now);
  weekStart.setDate(now.getDate() - 7);

  const { data: workouts } = await supabase
    .from('user_workouts')
    .select('duration')
    .eq('user_id', userId)
    .eq('completed', true)
    .gte('completed_at', weekStart.toISOString());

  const count = workouts?.length || 0;
  const minutes = workouts?.reduce((s: number, w: Record<string, unknown>) => s + ((w.duration as number) || 0), 0) || 0;

  await Notifications.scheduleNotificationAsync({
    content: {
      title: 'Resumo da semana',
      body: `${count} treinos, ${minutes} minutos. ${getWeeklyFeedback(count)}`,
      data: { type: 'weekly_summary' },
    },
    trigger: null,
  });
}

export async function cancelAllWorkoutReminders(): Promise<void> {
  await Notifications.cancelAllScheduledNotificationsAsync();
}

export async function getActiveReminders(): Promise<Notifications.NotificationTriggerInput[]> {
  const scheduled = await Notifications.getAllScheduledNotificationsAsync();
  return scheduled.filter(n =>
    ['workout_reminder', 'rest_day', 'weekly_plan', 'motivational'].includes((n.content.data?.type as string) || '')
  ) as unknown as Notifications.NotificationTriggerInput[];
}

export async function requestNotificationPermissions(): Promise<boolean> {
  const { status } = await Notifications.requestPermissionsAsync();
  return status === 'granted';
}

export async function scheduleHydrationReminder(): Promise<void> {
  const hasPermission = await requestNotificationPermissions();
  if (!hasPermission) return;

  for (let h = 8; h <= 20; h += 2) {
    await Notifications.scheduleNotificationAsync({
      content: { title: 'Hora de beber agua!', body: 'Mantenha-se hidratado durante o dia.', data: { type: 'hydration' } },
      trigger: {
        type: Notifications.SchedulableTriggerInputTypes.CALENDAR,
        hour: h,
        minute: 0,
        repeats: true,
      },
    });
  }
}

