    backgroundColor: COLORS.surfaceElevated,
    borderRadius: 5,
    overflow: 'hidden' as const,
  } as ViewStyle,
  fill: {
    height: '100%' as any,
    backgroundColor: COLORS.primary,
    borderRadius: 3,
  } as ViewStyle,
  fillSuccess: {
    backgroundColor: COLORS.success,
  } as ViewStyle,
  fillError: {
    backgroundColor: COLORS.error,
  } as ViewStyle,
  fillGradient: {
    backgroundColor: COLORS.primary,
