    letterSpacing: 0.8,
    marginBottom: SPACING.xs,
  } as TextStyle,
  error: {
    fontFamily: 'Inter_400Regular',
    fontSize: 12,
    color: COLORS.error,
    marginTop: SPACING.xs,
  } as TextStyle,
