    paddingBottom: SPACING.xxxl,
  } as ViewStyle,
  handle: {
    width: 40,
    height: 4,
    borderRadius: 2,
    backgroundColor: COLORS.border,
    alignSelf: 'center' as const,
    marginBottom: SPACING.lg,
