    borderBottomWidth: 0,
  } as ViewStyle,
  sectionHeader: {
    fontFamily: 'Montserrat_600SemiBold',
    fontSize: 11,
    color: COLORS.textMuted,
    textTransform: 'uppercase' as const,
    letterSpacing: 1,
    paddingHorizontal: SPACING.lg,
    paddingTop: SPACING.xl,
    paddingBottom: SPACING.sm,
