    borderRadius: 3,
  } as ViewStyle,
  fillSuccess: {
    backgroundColor: COLORS.success,
  } as ViewStyle,
  fillError: {
    backgroundColor: COLORS.error,
  } as ViewStyle,
  fillGradient: {
    backgroundColor: COLORS.primary,
    borderRadius: 3,
  } as ViewStyle,
} as const;

// ─── Skeleton Loading ───────────────────────────────────────
export const skeletonStyles = {
  line: {
    height: 14,
    backgroundColor: COLORS.surfaceOverlay || COLORS.surface,
    borderRadius: BORDER_RADIUS.sm,
  } as ViewStyle,
  circle: {
    borderRadius: 999,
    backgroundColor: COLORS.surfaceOverlay || COLORS.surface,
  } as ViewStyle,
  card: {
    backgroundColor: COLORS.surfaceOverlay || COLORS.surface,
